import { supabase } from './supabaseClient';
import { loadReports, saveReport, getDeviceId } from './storageService';

export const getCurrentUser = async () => {
  const { data: { session } } = await supabase.auth.getSession();
  return session?.user || null;
};

export const signIn = async (email: string, pass: string) => {
  const { data, error } = await supabase.auth.signInWithPassword({
    email,
    password: pass,
  });
  if (error) throw error;

  // After successful sign in, migrate any guest data on this device to the user
  if (data.session?.user) {
    await migrateGuestDataToUser(data.session.user.id);
  }

  return data;
};

export const signUp = async (email: string, pass: string) => {
  const { data, error } = await supabase.auth.signUp({
    email,
    password: pass,
  });
  if (error) throw error;

  // If auto-login happens (depends on Supabase config), migrate data
  if (data.session?.user) {
    await migrateGuestDataToUser(data.session.user.id);
  }

  return data;
};

export const signOut = async () => {
  await supabase.auth.signOut();
};

/**
 * Migration Logic:
 * Finds all reports on this device that do NOT belong to a user yet,
 * and tags them with the new userId.
 */
export const migrateGuestDataToUser = async (userId: string) => {
  const deviceId = getDeviceId();

  // 1. Fetch all reports visible to this device (using the raw query logic from storageService essentially)
  // We reuse loadReports, but we need to know we are in a transition state.
  // Actually, simplest way: Fetch all reports, check if they have deviceId but NO user tag.

  // We can't use loadReports() directly because it might already be using the userId filter now that we are logged in.
  // We need a raw fetch here.

  const { data: reports } = await supabase
    .from('daily_reports')
    .select('*')
    .order('created_at', { ascending: false })
    .limit(100);

  if (!reports) return;

  const updates = [];

  for (const row of reports) {
    // Parse sources
    let sources: string[] = [];
    if (Array.isArray(row.sources)) {
      sources = row.sources;
    } else if (typeof row.sources === 'string') {
      try { sources = JSON.parse(row.sources); } catch {}
    }

    const hasDeviceTag = sources.includes(`device:${deviceId}`);
    const hasUserTag = sources.some(s => s.startsWith('user:'));
    const alreadyHasThisUser = sources.includes(`user:${userId}`);

    // If it belongs to this device and doesn't belong to the user yet
    if (hasDeviceTag && !alreadyHasThisUser) {
        const newSources = [...sources, `user:${userId}`];
        updates.push({
            ...row,
            sources: newSources
        });
    }
  }

  // Perform updates
  // Supabase doesn't support bulk update easily with different values, so we loop (it's client side migration, usually small amount of data for guest)
  for (const update of updates) {
      await supabase.from('daily_reports').upsert(update);
  }
};

import React, { useState } from 'react';
import { X, Mail, Lock, Loader2, LogIn, UserPlus, LogOut, User } from 'lucide-react';
import * as AuthService from '../services/authService';

interface AuthModalProps {
  isOpen: boolean;
  onClose: () => void;
  user: any;
  onAuthSuccess: () => void;
}

const AuthModal: React.FC<AuthModalProps> = ({ isOpen, onClose, user, onAuthSuccess }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setLoading(true);

    try {
      if (isLogin) {
        await AuthService.signIn(email, password);
      } else {
        await AuthService.signUp(email, password);
      }
      onAuthSuccess();
      onClose();
    } catch (err: any) {
      setError(err.message || 'Authentication failed');
    } finally {
      setLoading(false);
    }
  };

  const handleSignOut = async () => {
    setLoading(true);
    await AuthService.signOut();
    onAuthSuccess(); // actually onAuthChange
    onClose();
    setLoading(false);
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity" onClick={onClose}></div>

      {/* Modal Content */}
      <div className="relative bg-white rounded-3xl w-full max-w-sm shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">

        {/* Header */}
        <div className="bg-gradient-to-r from-brand-600 to-brand-700 p-6 text-white text-center relative">
          <button onClick={onClose} className="absolute top-4 right-4 text-brand-100 hover:text-white bg-white/10 hover:bg-white/20 rounded-full p-1.5 transition-all">
            <X size={18} />
          </button>

          <div className="w-16 h-16 bg-white/20 rounded-full flex items-center justify-center mx-auto mb-3 backdrop-blur-md shadow-inner">
             <User size={32} className="text-white" />
          </div>

          <h2 className="text-xl font-bold">
            {user ? 'Account' : (isLogin ? 'Welcome Back' : 'Create Account')}
          </h2>
          {!user && <p className="text-brand-100 text-xs mt-1">Sync your sales data across devices</p>}
        </div>

        <div className="p-6">
          {user ? (
            <div className="space-y-6">
              <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100 text-center">
                <p className="text-xs font-bold text-gray-400 uppercase mb-1">Signed in as</p>
                <p className="font-medium text-gray-900 break-all">{user.email}</p>
              </div>
              <button 
                onClick={handleSignOut}
                disabled={loading}
                className="w-full py-3 bg-gray-100 text-gray-700 font-bold rounded-xl flex items-center justify-center gap-2 hover:bg-red-50 hover:text-red-600 transition-all"
              >
                {loading ? <Loader2 className="animate-spin" /> : <LogOut size={18} />}
                Sign Out
              </button>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="space-y-4">
              {error && (
                <div className="bg-red-50 text-red-600 text-xs p-3 rounded-xl border border-red-100 font-medium">
                  {error}
                </div>
              )}

              <div className="space-y-1">
                <label className="text-xs font-bold text-gray-500 ml-1">Email Address</label>
                <div className="relative">
                  <Mail className="absolute left-3 top-3 text-gray-400" size={18} />
                  <input 
                    type="email" 
                    required
                    className="w-full pl-10 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-brand-500 focus:bg-white transition-all outline-none font-medium"
                    placeholder="name@company.com"
                    value={email}
                    onChange={e => setEmail(e.target.value)}
                  />
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-xs font-bold text-gray-500 ml-1">Password</label>
                <div className="relative">
                  <Lock className="absolute left-3 top-3 text-gray-400" size={18} />
                  <input 
                    type="password" 
                    required
                    minLength={6}
                    className="w-full pl-10 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-brand-500 focus:bg-white transition-all outline-none font-medium"
                    placeholder="••••••••"
                    value={password}
                    onChange={e => setPassword(e.target.value)}
                  />
                </div>
              </div>

              <button 
                type="submit" 
                disabled={loading}
                className="w-full py-3.5 bg-brand-600 text-white font-bold rounded-xl shadow-lg shadow-brand-500/30 hover:bg-brand-700 active:scale-[0.98] transition-all flex items-center justify-center gap-2 mt-2"
              >
                {loading ? <Loader2 className="animate-spin" /> : (isLogin ? <LogIn size={18} /> : <UserPlus size={18} />)}
                {isLogin ? 'Sign In' : 'Create Account'}
              </button>

              <div className="pt-2 text-center">
                <button 
                  type="button"
                  onClick={() => { setError(null); setIsLogin(!isLogin); }}
                  className="text-xs font-bold text-brand-600 hover:text-brand-800 transition-colors"
                >
                  {isLogin ? "New user? Create an account" : "Already have an account? Sign in"}
                </button>
              </div>
            </form>
          )}
        </div>
      </div>
    </div>
  );
};

export default AuthModal;

import { DailyReport, AppConfig, SalesItem, SourceType } from '../types';
import { LOCAL_STORAGE_KEYS } from '../constants';
import { supabase } from './supabaseClient';
import { generateId } from '../utils/calculations';

// Exported for authService usage
export const getDeviceId = (): string => {
  const KEY = 'dsr_device_id_v1';
  let id = localStorage.getItem(KEY);
  if (!id) {
    id = generateId();
    localStorage.setItem(KEY, id);
  }
  return id;
};

// Helper to get current authenticated user ID
const getCurrentUserId = async (): Promise<string | null> => {
  const { data: { session } } = await supabase.auth.getSession();
  return session?.user?.id || null;
};

// Helper to map camelCase (App) to snake_case (DB)
const mapToDb = async (report: DailyReport) => {
  const deviceId = getDeviceId();
  const userId = await getCurrentUserId();

  // Clean existing tags to avoid duplication
  const cleanSources = report.sources.filter(s => !s.startsWith('device:') && !s.startsWith('user:'));

  const finalSources = [...cleanSources];

  // Always add device ID for audit/tracking
  finalSources.push(`device:${deviceId}`);

  // If user is logged in, add user ID (this becomes the primary isolation key)
  if (userId) {
    finalSources.push(`user:${userId}`);
  }

  return {
    report_id: report.reportId,
    date_local: report.dateLocal,
    time_local: report.timeLocal,
    timezone: report.timezone,
    store_name: report.storeName,
    sales_rep_name: report.salesRepName,
    items: report.items,
    totals: report.totals,
    sources: finalSources,
    attachments: report.attachments,
    share_message: report.shareMessage,
    created_at: report.createdAt
  };
};

// Helper to map snake_case (DB) to camelCase (App)
const mapFromDb = (row: any): DailyReport => {
  let rawSources: any[] = [];

  if (Array.isArray(row.sources)) {
    rawSources = row.sources;
  } else if (typeof row.sources === 'string') {
    try {
      const parsed = JSON.parse(row.sources);
      if (Array.isArray(parsed)) rawSources = parsed;
    } catch (e) { }
  }

  // Filter out internal isolation tags so they don't clutter UI
  const cleanSources = rawSources.filter((s: string) => 
    typeof s === 'string' && !s.startsWith('device:') && !s.startsWith('user:')
  ) as SourceType[];

  return {
    reportId: row.report_id,
    dateLocal: row.date_local || '',
    timeLocal: row.time_local || '',
    timezone: row.timezone || '',
    storeName: row.store_name || '',
    salesRepName: row.sales_rep_name || '',
    items: Array.isArray(row.items) ? row.items : [],
    totals: row.totals || { gross: 0, discounts: 0, net: 0 },
    sources: cleanSources,
    attachments: Array.isArray(row.attachments) ? row.attachments : [],
    shareMessage: row.share_message || '',
    createdAt: (typeof row.created_at === 'string' && row.created_at.includes('T'))
      ? new Date(row.created_at).getTime()
      : parseInt(String(row.created_at || '0'), 10)
  };
};

export const loadReports = async (): Promise<DailyReport[]> => {
  const deviceId = getDeviceId();
  const userId = await getCurrentUserId();

  // Fetch recent reports
  const { data, error } = await supabase
    .from('daily_reports')
    .select('*')
    .order('created_at', { ascending: false })
    .limit(200);

  if (error) {
    console.error('Error loading reports:', error.message, error.details || '');
    return [];
  }

  if (!data) return [];

  // ISOLATION LOGIC:
  // If User Logged In -> Show only reports with matching user:${userId}
  // If Guest -> Show only reports with matching device:${deviceId}

  return data.filter(row => {
    let sources: string[] = [];
    if (Array.isArray(row.sources)) {
      sources = row.sources;
    } else if (typeof row.sources === 'string') {
      try { sources = JSON.parse(row.sources); } catch {}
    }

    if (!Array.isArray(sources)) return false;

    if (userId) {
      // Authenticated Mode: Strict User Isolation
      return sources.includes(`user:${userId}`);
    } else {
      // Guest Mode: Device Isolation
      return sources.includes(`device:${deviceId}`);
    }
  }).map(row => {
    try {
      return mapFromDb(row);
    } catch (e) {
      console.warn('Skipping malformed report row:', row, e);
      return null;
    }
  }).filter(Boolean) as DailyReport[];
};

export const saveReport = async (report: DailyReport): Promise<void> => {
  // Security Checks
  const dangerousPatterns = /javascript:|vbscript:|data:|file:/i;
  if (dangerousPatterns.test(report.shareMessage)) throw new Error("Security Error: Unsafe content.");
  if (report.items.some(i => i.notes && dangerousPatterns.test(i.notes))) throw new Error("Security Error: Unsafe content.");

  const payload = await mapToDb(report); // Now async

  const jsonSize = JSON.stringify(payload).length;
  if (jsonSize > 1000000) throw new Error("Report too large (max 1MB).");

  const { error } = await supabase
    .from('daily_reports')
    .upsert(payload);

  if (error) {
    console.error('Error saving report:', error.message);
    throw new Error(`Database Error: ${error.message}`);
  }
};

export const clearAllReports = async (): Promise<void> => {
  const reports = await loadReports();
  const ids = reports.map(r => r.reportId);

  if (ids.length === 0) return;

  const { error } = await supabase
    .from('daily_reports')
    .delete()
    .in('report_id', ids);

  if (error) {
    console.error('Error clearing reports:', error.message);
    throw new Error(`Database Error: ${error.message}`);
  }
};

export const deleteReports = async (ids: string[]): Promise<void> => {
  if (ids.length === 0) return;
  const { error } = await supabase
    .from('daily_reports')
    .delete()
    .in('report_id', ids);

  if (error) throw new Error(`Database Error: ${error.message}`);
};

export const getReportById = async (id: string): Promise<DailyReport | undefined> => {
  const { data, error } = await supabase
    .from('daily_reports')
    .select('*')
    .eq('report_id', id)
    .single();

  if (error || !data) return undefined;
  return mapFromDb(data);
};

export const uploadFile = async (file: File): Promise<string | null> => {
  try {
    const fileExt = file.name.split('.').pop();
    const fileName = `${Date.now()}_${generateId()}.${fileExt}`;
    const { data, error } = await supabase.storage.from('uploads').upload(fileName, file);
    if (error) return null;
    if (!data?.path) return null;
    const { data: { publicUrl } } = supabase.storage.from('uploads').getPublicUrl(data.path);
    return publicUrl;
  } catch (e) {
    return null;
  }
};

export const saveOcrLog = async (imageUrl: string, analysis: SalesItem[]): Promise<void> => {
  const { error } = await supabase
    .from('reports')
    .insert({ image_url: imageUrl, analysis: JSON.stringify(analysis) });
  if (error) console.warn('Error logging OCR:', error.message);
};

export const saveConfig = (config: AppConfig) => {
  localStorage.setItem(LOCAL_STORAGE_KEYS.CONFIG, JSON.stringify(config));
};

export const loadConfig = (): AppConfig => {
  const data = localStorage.getItem(LOCAL_STORAGE_KEYS.CONFIG);
  return data ? JSON.parse(data) : { salesRepName: '' };
};

