                 <X size={18} />
               </button>
            </div>

            <div className="p-5 overflow-y-auto">
               {/* Ratio Selector */}
               <div className="mb-6">
                 <label className="text-xs font-bold text-gray-500 uppercase mb-2 block">Split Ratio</label>
                 <div className="grid grid-cols-3 gap-2 bg-gray-100 p-1 rounded-xl">
                    {[0.5, 0.6, 0.7].map((r) => (
                      <button
                        key={r}
