    if (!input) return '';

    // 1. Strip HTML tags
    let clean = input.replace(/<\/?[^>]+(>|$)/g, "");

    // 2. Prevent CSV Formula Injection
    // If string starts with =, +, -, or @, prepend a single quote to force it as text
    if (/^[=+\-@]/.test(clean)) {
      clean = "'" + clean;
    }

    return clean.trim();
  };

