                      </div>

                      {/* Divider */}
                      <div className="flex items-center justify-center text-gray-300">
                        <ArrowRightLeft className="rotate-90 sm:rotate-0" size={20} />
                      </div>

                      {/* Right Column (B) */}
                      <div className="flex-1 bg-gray-50 border border-gray-200 rounded-xl overflow-hidden flex flex-col">
                         <div className="p-3 bg-gray-100 border-b border-gray-200 flex justify-between items-center">
                            <span className="font-bold text-gray-600 text-xs">Staff B</span>
                            <span className="font-extrabold text-gray-700 text-sm">{CalculationUtils.formatCurrency(getTotal(splitItemsB))}</span>
                         </div>
                         <div className="flex-1 overflow-y-auto p-2 space-y-2 max-h-[250px] sm:max-h-[350px]">
                            {splitItemsB.length === 0 && <div className="text-center p-4 text-xs text-gray-300 font-medium italic">No items</div>}
                            {splitItemsB.map((item, i) => (
                                <div key={i} 
                                   onClick={() => moveOneUnit(splitItemsB, splitItemsA, i, setSplitItemsB, setSplitItemsA)}
                                   className="bg-white p-2 rounded-lg border border-gray-200 shadow-sm cursor-pointer hover:bg-gray-50 active:scale-95 transition-all flex justify-between items-center group"
                                >
                                   <ArrowLeftIcon size={14} className="text-gray-300 group-hover:text-gray-500 order-first mr-2" />
                                   <div className="flex items-center gap-2 overflow-hidden flex-1">
                                     <span className="bg-gray-100 text-gray-600 text-[10px] font-bold px-1.5 py-0.5 rounded min-w-[20px] text-center">{item.quantity}</span>
                                     <span className="text-xs font-medium text-gray-700 truncate">{item.productName}</span>
                                   </div>
                                </div>
                            ))}
                         </div>
                      </div>
                  </div>

                  <div className="mt-3 text-center">
                     <span className="text-[10px] font-medium text-gray-400 bg-gray-100 px-3 py-1 rounded-full">
                       Tip: Tap an item to move 1 unit to the other list
                     </span>
                  </div>
                </>
              ) : (
                <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4">
                  <div className="text-center mb-6">
                    <div className="w-12 h-12 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-2">
                      <CheckCircle size={24} />
                    </div>
                    <p className="text-sm text-gray-600">Reports generated. You can now share them.</p>
                  </div>

                  {/* Result Card A */}
                  <div className="bg-white border border-gray-200 rounded-2xl p-4 shadow-sm">
                     <div className="flex justify-between items-center mb-3">
                        <div>
                          <span className="text-xs font-bold text-brand-600 bg-brand-50 px-2 py-0.5 rounded-md uppercase tracking-wide">Staff A</span>
                          <h4 className="font-bold text-gray-900 mt-1">{createdSplitReports.a.salesRepName}</h4>
                        </div>
                        <span className="font-extrabold text-lg text-brand-700">{CalculationUtils.formatCurrency(createdSplitReports.a.totals.net)}</span>
                     </div>
                     <div className="grid grid-cols-2 gap-2">
                        <button 
                          onClick={() => copyToClipboard(createdSplitReports.a.shareMessage)}
                          className="flex items-center justify-center gap-1.5 py-2.5 bg-gray-50 hover:bg-gray-100 text-gray-700 text-xs font-bold rounded-xl transition-colors border border-gray-100"
                        >
                          <Copy size={14} /> Copy Text
                        </button>
                        <button 
                          onClick={() => shareViaWhatsApp(createdSplitReports.a.shareMessage)}
                          className="flex items-center justify-center gap-1.5 py-2.5 bg-[#25D366] hover:bg-[#20bd5a] text-white text-xs font-bold rounded-xl transition-colors shadow-sm"
                        >
                          <MessageCircle size={14} fill="white" /> WhatsApp
                        </button>
                     </div>
                  </div>

                  {/* Result Card B */}
                  <div className="bg-white border border-gray-200 rounded-2xl p-4 shadow-sm">
                     <div className="flex justify-between items-center mb-3">
                        <div>
                          <span className="text-xs font-bold text-gray-500 bg-gray-100 px-2 py-0.5 rounded-md uppercase tracking-wide">Staff B</span>
                          <h4 className="font-bold text-gray-900 mt-1">{createdSplitReports.b.salesRepName}</h4>
                        </div>
                        <span className="font-extrabold text-lg text-gray-700">{CalculationUtils.formatCurrency(createdSplitReports.b.totals.net)}</span>
                     </div>
                     <div className="grid grid-cols-2 gap-2">
                        <button 
                          onClick={() => copyToClipboard(createdSplitReports.b.shareMessage)}
                          className="flex items-center justify-center gap-1.5 py-2.5 bg-gray-50 hover:bg-gray-100 text-gray-700 text-xs font-bold rounded-xl transition-colors border border-gray-100"
                        >
                          <Copy size={14} /> Copy Text
                        </button>
                        <button 
                          onClick={() => shareViaWhatsApp(createdSplitReports.b.shareMessage)}
                          className="flex items-center justify-center gap-1.5 py-2.5 bg-[#25D366] hover:bg-[#20bd5a] text-white text-xs font-bold rounded-xl transition-colors shadow-sm"
                        >
                          <MessageCircle size={14} fill="white" /> WhatsApp
                        </button>
                     </div>
                  </div>

                </div>
              )}
            </div>

            <div className="p-4 border-t border-gray-100 bg-gray-50 flex gap-3 shrink-0">
               {!createdSplitReports ? (
                 <>
                   <button 
                     onClick={() => setIsSplitModalOpen(false)}
                     className="flex-1 py-3 font-bold text-gray-600 bg-white border border-gray-200 rounded-xl hover:bg-gray-50"
                   >
                     Cancel
                   </button>
                   <button 
                     onClick={handleSplit}
                     disabled={saving || !staff2Name}
                     className="flex-[2] py-3 font-bold text-white bg-brand-600 rounded-xl shadow-lg shadow-brand-500/20 hover:bg-brand-700 disabled:opacity-50 disabled:shadow-none flex items-center justify-center gap-2"
                   >
                     {saving ? <Loader2 className="animate-spin" size={18} /> : <Split size={18} />}
                     Generate Split
                   </button>
                 </>
               ) : (
                 <button 
                   onClick={() => {
                     setIsSplitModalOpen(false);
                     // Stay on page
                   }}
                   className="w-full py-3 font-bold text-white bg-gray-900 rounded-xl shadow-lg hover:bg-black"
                 >
                   Done
                 </button>
               )}
            </div>
          </div>
        </div>
      )}

      {/* Sticky Header with Backdrop Blur */}
      <div className="sticky top-0 bg-white/90 backdrop-blur-md border-b border-gray-200 z-50 px-3 py-2 flex items-center justify-between shadow-sm transition-all">
        <div className="flex items-center gap-1 sm:gap-2">
          <button onClick={() => navigate('/')} className="p-2 text-gray-500 hover:text-gray-900 rounded-full hover:bg-gray-100 active:bg-gray-200 transition-colors">
            <ArrowLeft size={20} />
          </button>

          <div className="h-6 w-px bg-gray-200 mx-1"></div>

          <div className="flex items-center gap-0.5">
            <button 
              onClick={undo} 
              disabled={!canUndo} 
              className="p-2 text-gray-400 disabled:opacity-30 hover:text-gray-700 hover:bg-gray-50 rounded-full transition-all active:scale-95"
              title="Undo"
            >
              <Undo2 size={18} />
            </button>
            <button 
              onClick={redo} 
              disabled={!canRedo} 
              className="p-2 text-gray-400 disabled:opacity-30 hover:text-gray-700 hover:bg-gray-50 rounded-full transition-all active:scale-95"
              title="Redo"
            >
              <Redo2 size={18} />
            </button>
          </div>

          {/* Status Indicator - Mini */}
          <div className="ml-1 flex flex-col justify-center">
             {saveSuccess ? (
                <span className="text-[10px] text-green-600 font-bold uppercase tracking-wide flex items-center gap-1 animate-in fade-in"><CheckCircle size={10}/> Saved</span>
              ) : (
                <span className={`text-[10px] font-bold tracking-wide transition-colors ${isDirty ? 'text-amber-500' : 'text-gray-300'}`}>{isDirty ? 'Unsaved' : 'Saved'}</span>
              )}
          </div>
        </div>

        <div className="flex items-center gap-2">
          {report.items.length > 0 && (
            <button 
              onClick={() => setIsSplitModalOpen(true)}
              className="p-2 text-brand-600 hover:bg-brand-50 rounded-full transition-colors active:scale-95 border border-transparent hover:border-brand-100"
              title="Split Report"
            >
              <Users size={18} />
            </button>
          )}

          <button 
            onClick={handleShare} 
            className="text-brand-600 hover:bg-brand-50 p-2 sm:px-3 sm:py-2 rounded-xl text-xs font-bold transition-all active:scale-95 flex items-center gap-1.5" 
            title="Share"
          >
            <Share2 size={18} /> <span className="hidden sm:inline">Share</span>
          </button>

          <button 
            onClick={handleSaveAndExit} 
            disabled={saving}
            className="bg-gray-900 text-white px-4 py-2 rounded-xl shadow-lg shadow-gray-900/20 hover:bg-black active:scale-95 transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-1.5 text-xs font-bold"
          >
            {saving ? <Loader2 size={14} className="animate-spin"/> : <Save size={16} />}
            Save
          </button>
        </div>
      </div>

      <div className="max-w-2xl mx-auto p-5 space-y-6">

        {globalError && (
          <div className="bg-red-50 border border-red-100 text-red-700 px-4 py-3 rounded-2xl flex items-center gap-3 animate-in slide-in-from-top-4 shadow-sm">
            <div className="p-1.5 bg-white rounded-full text-red-500 shadow-sm"><AlertTriangle size={16} /></div>
            <span className="text-sm font-semibold">{globalError}</span>
          </div>
        )}

        {/* Metadata Card */}
        <div className="bg-white p-5 rounded-3xl border border-gray-100 shadow-sm space-y-5">

          {/* Off Day Toggle (Moved to Top) */}
          <div className="flex items-center justify-between p-3 bg-gray-50 rounded-xl border border-gray-200">
             <div className="flex items-center gap-3">
                <div className={`p-2 rounded-full ${report.isOffDay ? 'bg-amber-100 text-amber-600' : 'bg-gray-200 text-gray-500'}`}>
                   <Coffee size={18} />
                </div>
                <div>
                  <span className="text-sm font-bold text-gray-900 block">Mark as Off-Day</span>
                  <span className="text-xs text-gray-400">Skip items if you are not working</span>
                </div>
             </div>
             <label className="relative inline-flex items-center cursor-pointer">
               <input 
                 type="checkbox" 
                 className="sr-only peer"
                 checked={report.isOffDay || false}
                 onChange={(e) => updateReport({ isOffDay: e.target.checked })}
               />
               <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-brand-100 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-amber-500"></div>
             </label>
          </div>

          <div className="grid grid-cols-2 gap-4">
             <div className="space-y-1.5 col-span-2 sm:col-span-1">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider ml-1">Date</label>
                <div className="relative group">
                  <div className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-brand-500 transition-colors"><Calendar size={16}/></div>
                  <input 
                    type="date" 
                    value={report.dateLocal}
                    onChange={(e) => updateReport({ dateLocal: e.target.value })}
                    className="w-full text-sm font-semibold bg-gray-50 border border-gray-200 rounded-xl pl-10 pr-3 py-3 focus:border-brand-500 focus:ring-2 focus:ring-brand-100 outline-none transition-all"
                  />
                </div>
             </div>
             {!report.isOffDay && (
               <div className="space-y-1.5 col-span-2 sm:col-span-1">
                  <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider ml-1">Time</label>
                  <div className="relative group">
                    <div className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-brand-500 transition-colors"><Clock size={16}/></div>
                    <input 
                      type="time" 
                      value={report.timeLocal}
                      onChange={(e) => updateReport({ timeLocal: e.target.value })}
                      className="w-full text-sm font-semibold bg-gray-50 border border-gray-200 rounded-xl pl-10 pr-3 py-3 focus:border-brand-500 focus:ring-2 focus:ring-brand-100 outline-none transition-all"
                    />
                  </div>
               </div>
             )}
          </div>

          {!report.isOffDay && (
            <>
              <div className="space-y-1.5">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider ml-1">Timezone</label>
                <div className="relative group">
                  <div className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-brand-500 transition-colors"><Globe size={16}/></div>
                  <input 
                    list="timezones"
                    type="text" 
                    value={report.timezone || ''}
                    onChange={(e) => updateReport({ timezone: e.target.value })}
                    className={`w-full text-sm font-medium bg-gray-50 border rounded-xl pl-10 pr-3 py-3 focus:border-brand-500 focus:ring-2 focus:ring-brand-100 outline-none transition-all ${!report.timezone ? 'border-red-300' : 'border-gray-200'}`}
                    placeholder="Select or type..."
                  />
                  <datalist id="timezones">
                    <option value="Asia/Dubai" />
                    <option value="Asia/Riyadh" />
                    <option value="Europe/London" />
                    <option value="America/New_York" />
                  </datalist>
                </div>

                {dateWarning && (
                  <div className="mt-2 p-3 bg-amber-50 border border-amber-100 rounded-xl text-xs text-amber-900 flex items-center justify-between animate-in fade-in slide-in-from-top-1 shadow-sm">
                    <span className="flex items-center gap-2 font-semibold">
                      <AlertTriangle size={14} className="text-amber-600"/> 
                      {dateWarning.msg}
                    </span>
                    <button 
                      onClick={() => {
                        updateReport({ dateLocal: dateWarning.date });
                        setDateWarning(null);
                      }}
                      className="bg-white text-amber-700 px-3 py-1.5 rounded-lg border border-amber-200 font-bold text-[10px] uppercase hover:bg-amber-50 shadow-sm transition-all active:scale-95"
                    >
                      Update
                    </button>
                  </div>
                )}
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider ml-1">Store Location</label>
                <div className="relative group">
                  <div className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-brand-500 transition-colors"><MapPin size={16}/></div>
                  <select 
                    value={report.storeName || ''}
                    onChange={(e) => updateReport({ storeName: e.target.value })}
                    className="w-full text-sm font-medium bg-gray-50 border border-gray-200 rounded-xl pl-10 pr-8 py-3 appearance-none focus:border-brand-500 focus:ring-2 focus:ring-brand-100 outline-none transition-all"
                  >
                    {MOCK_STORES.map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
                </div>
              </div>
            </>
          )}

          <div className="space-y-1.5">
             <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider ml-1">Sales Rep</label>
             <div className="relative group">
                <div className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-brand-500 transition-colors"><User size={16}/></div>
                <input 
                  type="text" 
                  placeholder="Your Name"
                  value={report.salesRepName || ''}
                  onChange={(e) => updateReport({ salesRepName: e.target.value })}
                  className="w-full text-sm font-medium bg-gray-50 border border-gray-200 rounded-xl pl-10 pr-3 py-3 focus:border-brand-500 focus:ring-2 focus:ring-brand-100 outline-none transition-all placeholder-gray-300"
                />
             </div>
          </div>

        </div>

        {/* Conditionally render Capture and Items based on Off Day */}
        <div className={`transition-all duration-300 ${report.isOffDay ? 'opacity-50 grayscale pointer-events-none select-none' : 'opacity-100'}`}>
            <CapturePanel 
              onItemsCaptured={handleItemsCaptured} 
              isProcessing={processing}
              setIsProcessing={setProcessing}
              // Pass callback for attachment handling
              onAttachmentsAdded={handleAddAttachments}
            />

            {/* Attachments List */}
            {report.attachments.length > 0 && (
              <div className="space-y-2 mb-6">
                <h2 className="text-xs font-bold text-gray-500 uppercase tracking-wider ml-1">Attachments ({report.attachments.length})</h2>
                <div className="grid grid-cols-3 gap-3">
                  {report.attachments.map((att, idx) => (
                    <div key={idx} className="relative group aspect-square bg-gray-100 rounded-xl overflow-hidden border border-gray-200 shadow-sm">
                      <img src={att.url} alt="Attachment" className="w-full h-full object-cover" />
                      <button 
                        onClick={() => handleRemoveAttachment(idx)}
                        className="absolute top-1 right-1 bg-red-500 text-white p-1 rounded-full shadow-md opacity-0 group-hover:opacity-100 transition-opacity"
                      >
                        <ArrowLeft size={12} className="rotate-45" /> {/* Simulating X icon with rotate */}
                      </button>
                      <a href={att.url} target="_blank" rel="noopener noreferrer" className="absolute inset-0 z-0"></a>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="mb-6">
              <div className="flex items-center justify-between px-1 mb-3">
                <h2 className="text-sm font-bold text-gray-800">Sales Items</h2>
                <span className="text-[10px] font-bold text-gray-500 bg-white border border-gray-200 px-2 py-1 rounded-full shadow-sm">{report.items.length} items</span>
              </div>
              <ItemsTable 
                items={report.items} 
                onChange={(items) => updateReport({ items })}
                isParsing={processing}
                errors={errors}
              />
            </div>

            <TotalsPanel 
              totals={report.totals} 
              onDiscountChange={(d) => updateReport({ totals: { ...report.totals, discounts: d } })} 
            />
        </div>

        {report.isOffDay && (
           <div className="text-center p-4 bg-amber-50 border border-amber-100 rounded-2xl text-amber-800 font-medium text-sm animate-in fade-in">
              This report is marked as an <b>Off Day</b>. No sales items required.
           </div>
        )}

        {report.shareMessage && (
          <div className="bg-green-50 p-5 rounded-2xl border border-green-200/60 cursor-pointer hover:bg-green-100 transition-all active:scale-[0.99] shadow-sm group" onClick={handleShare}>
            <div className="flex justify-between items-start mb-2">
              <h3 className="text-xs font-bold text-green-700 uppercase flex items-center gap-1.5">
                 <div className="p-1 bg-white rounded-md shadow-sm text-green-600"><Share2 size={12}/></div>
                 WhatsApp Preview
              </h3>
            </div>
            <p className="text-sm text-green-900 font-medium italic leading-relaxed opacity-90 group-hover:opacity-100 whitespace-pre-wrap">
              "{report.shareMessage}"
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

export default ReportEditor;

export interface SalesItem {
  sku: string;
  productName: string;
  quantity: number;
  unitPrice: number;
  currency: string;
  notes?: string;
  lowConfidence?: boolean;
}

export interface Totals {
  gross: number;
  discounts: number;
  net: number;
}

export interface Attachment {
  type: 'image' | 'file';
  url: string;
  name?: string;
}

export type SourceType = 'manual' | 'ocr' | 'speech' | 'upload';

export interface DailyReport {
  reportId: string;
  dateLocal: string; // yyyy-mm-dd
  timeLocal: string; // HH:mm
  timezone: string;
  storeName: string;
  salesRepName: string;
  items: SalesItem[];
  totals: Totals;
  sources: SourceType[];
  attachments: Attachment[];
  shareMessage: string;
  createdAt: number; // Timestamp for sorting
  isOffDay?: boolean;
}

export interface AppConfig {
  salesRepName: string;
  defaultOffDay?: number; // 0=Sunday, 1=Monday, ... 6=Saturday
}

import React, { useState, useEffect } from 'react';
import { X, Settings, Coffee, Check, Save } from 'lucide-react';
import * as StorageService from '../services/storageService';
import { AppConfig } from '../types';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: () => void;
}

const DAYS = [
  { id: 0, label: 'Sunday' },
  { id: 1, label: 'Monday' },
  { id: 2, label: 'Tuesday' },
  { id: 3, label: 'Wednesday' },
  { id: 4, label: 'Thursday' },
  { id: 5, label: 'Friday' },
  { id: 6, label: 'Saturday' },
];

const SettingsModal: React.FC<SettingsModalProps> = ({ isOpen, onClose, onSave }) => {
  const [config, setConfig] = useState<AppConfig>({ salesRepName: '', defaultOffDay: undefined });
  const [selectedDay, setSelectedDay] = useState<number | undefined>(undefined);

  useEffect(() => {
    if (isOpen) {
      const current = StorageService.loadConfig();
      setConfig(current);
      setSelectedDay(current.defaultOffDay);
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const handleSave = () => {
    const newConfig = { ...config, defaultOffDay: selectedDay };
    StorageService.saveConfig(newConfig);
    onSave();
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity" onClick={onClose}></div>

      {/* Modal Content */}
      <div className="relative bg-white rounded-3xl w-full max-w-sm shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">

        {/* Header */}
        <div className="bg-gray-900 p-6 text-white text-center relative">
          <button onClick={onClose} className="absolute top-4 right-4 text-gray-400 hover:text-white bg-white/10 hover:bg-white/20 rounded-full p-1.5 transition-all">
            <X size={18} />
          </button>

          <div className="w-16 h-16 bg-white/10 rounded-full flex items-center justify-center mx-auto mb-3 backdrop-blur-md">
             <Settings size={32} className="text-white" />
          </div>

          <h2 className="text-xl font-bold">App Settings</h2>
          <p className="text-gray-400 text-xs mt-1">Customize your experience</p>
        </div>

        <div className="p-6">
          <div className="mb-6">
            <label className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-3 block flex items-center gap-2">
              <Coffee size={14} /> Default Off-Day
            </label>
            <div className="grid grid-cols-2 gap-2">
               {DAYS.map(day => (
                 <button
                   key={day.id}
                   onClick={() => setSelectedDay(selectedDay === day.id ? undefined : day.id)}
                   className={`py-2 px-3 rounded-xl text-sm font-bold border transition-all flex items-center justify-between ${
                     selectedDay === day.id 
                       ? 'bg-amber-50 border-amber-200 text-amber-700 shadow-sm' 
                       : 'bg-white border-gray-100 text-gray-600 hover:bg-gray-50'
                   }`}
                 >
                   {day.label}
                   {selectedDay === day.id && <Check size={14} className="text-amber-600" />}
                 </button>
               ))}
            </div>
            <p className="text-[10px] text-gray-400 mt-2 leading-relaxed">
              When you create a report on this day of the week, it will automatically be marked as an Off-Day.
            </p>
          </div>

          <button 
            onClick={handleSave}
            className="w-full py-3.5 bg-brand-600 text-white font-bold rounded-xl shadow-lg shadow-brand-500/30 hover:bg-brand-700 active:scale-[0.98] transition-all flex items-center justify-center gap-2"
          >
            <Save size={18} />
            Save Preferences
          </button>
        </div>
      </div>
    </div>
  );
};

export default SettingsModal;

import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { Plus, Search, ChevronRight, FileText, TrendingUp, Calendar, Filter, RefreshCw, History, LayoutDashboard, Loader2, Trash2, CheckSquare, X, Check, User, UserCircle, Coffee, Settings } from 'lucide-react';
import { DailyReport } from '../types';
import * as StorageService from '../services/storageService';
import * as AuthService from '../services/authService';
import { formatCurrency } from '../utils/calculations';
import { BarChart, Bar, XAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import AuthModal from '../components/AuthModal';
import SettingsModal from '../components/SettingsModal';

type ViewMode = 'home' | 'history';

const Dashboard: React.FC = () => {
  const navigate = useNavigate();
  const [reports, setReports] = useState<DailyReport[]>([]);
  const [loading, setLoading] = useState(true);
  const [viewMode, setViewMode] = useState<ViewMode>('home');

  // Auth State
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);

  // Settings State
  const [isSettingsModalOpen, setIsSettingsModalOpen] = useState(false);

  // Selection Mode State
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Filter states
  const [searchTerm, setSearchTerm] = useState('');
  const [showFilters, setShowFilters] = useState(false);
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  // Long Press Refs
  const longPressTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const isLongPress = useRef(false);

  const initData = async () => {
    setLoading(true);
    // 1. Check Auth
    const user = await AuthService.getCurrentUser();
    setCurrentUser(user);

    // 2. Load Reports (storageService now handles isolation based on auth state)
    const data = await StorageService.loadReports();
    setReports(data);
    setLoading(false);
  };

  useEffect(() => {
    initData();
  }, []);

  const handleAuthSuccess = async () => {
    // Reload everything after auth state change
    await initData();
  };

  // --- Selection Logic ---

  const enterSelectionMode = (initialId?: string) => {
    setIsSelectionMode(true);
    if (initialId) {
      setSelectedIds(new Set([initialId]));
    }
  };

  const exitSelectionMode = () => {
    setIsSelectionMode(false);
    setSelectedIds(new Set());
  };

  const toggleReportSelection = (id: string) => {
    const newSelected = new Set(selectedIds);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedIds(newSelected);
  };

  const deleteSelectedReports = async (e: React.MouseEvent) => {
    e.preventDefault(); 
    if (selectedIds.size === 0) return;

    setLoading(true);
    try {
      await StorageService.deleteReports(Array.from(selectedIds));
      const data = await StorageService.loadReports();
      setReports(data);
      exitSelectionMode();
    } catch (e) {
      alert("Failed to delete selected reports.");
    } finally {
      setLoading(false);
    }
  };

  // --- Long Press Handlers ---
  const handleTouchStart = (id: string) => {
    if (isSelectionMode) return;
    isLongPress.current = false;
    longPressTimer.current = setTimeout(() => {
      isLongPress.current = true;
      enterSelectionMode(id);
      if (navigator.vibrate) navigator.vibrate(50);
    }, 600);
  };

  const handleTouchEnd = () => {
    if (longPressTimer.current) {
      clearTimeout(longPressTimer.current);
    }
  };

  const handleTouchMove = () => {
    if (longPressTimer.current) {
      clearTimeout(longPressTimer.current);
    }
  };

  const handleCardClick = (id: string) => {
    if (isLongPress.current) {
      isLongPress.current = false;
      return;
    }

    if (isSelectionMode) {
      toggleReportSelection(id);
    } else {
      navigate(`/report/${id}`);
    }
  };

  // --- Filtering ---

  const filteredReports = reports.filter(r => {
    const matchesSearch = !searchTerm || r.storeName.toLowerCase().includes(searchTerm.toLowerCase());
    const reportDate = r.dateLocal;
    const matchesStart = !startDate || reportDate >= startDate;
    const matchesEnd = !endDate || reportDate <= endDate;
    return matchesSearch && matchesStart && matchesEnd;
  }).sort((a, b) => b.dateLocal.localeCompare(a.dateLocal) || b.createdAt - a.createdAt);

  const mostRecentReport = [...reports].sort((a, b) => b.createdAt - a.createdAt)[0];

  // Exclude off days from the chart data to avoid dipping the graph incorrectly (or include as 0 if desired)
  const sortedForChart = [...reports].sort((a, b) => a.dateLocal.localeCompare(b.dateLocal));
  const chartData = sortedForChart.slice(-7).map(r => ({
    name: r.dateLocal.slice(5),
    net: r.isOffDay ? 0 : r.totals.net
  }));

  const resetFilters = () => {
    setSearchTerm('');
    setStartDate('');
    setEndDate('');
    setShowFilters(false);
  };

  const hasFilters = searchTerm || startDate || endDate;

  return (
    <div className="min-h-screen bg-gray-50/50 pb-32 font-sans">
      <AuthModal 
        isOpen={isAuthModalOpen} 
        onClose={() => setIsAuthModalOpen(false)} 
        user={currentUser}
        onAuthSuccess={handleAuthSuccess}
      />

      <SettingsModal
        isOpen={isSettingsModalOpen}
        onClose={() => setIsSettingsModalOpen(false)}
        onSave={() => { /* Config is saved inside modal, maybe trigger refresh if needed */ }}
      />

      {/* Header Area */}
      <header className={`bg-gradient-to-br from-brand-700 via-brand-600 to-brand-800 text-white px-6 pt-12 pb-8 rounded-b-[2.5rem] shadow-xl transition-all duration-300 relative overflow-hidden ${viewMode === 'history' ? 'pb-8' : ''}`}>
        <div className="absolute top-0 left-0 w-full h-full overflow-hidden opacity-10 pointer-events-none">
           <div className="absolute -top-10 -right-10 w-40 h-40 bg-white rounded-full blur-3xl"></div>
           <div className="absolute bottom-0 left-0 w-60 h-60 bg-brand-300 rounded-full blur-3xl"></div>
        </div>

        <div className="relative z-10 flex justify-between items-start">
            <div>
                <h1 className="text-3xl font-extrabold mb-1 tracking-tight">
                  {viewMode === 'home' ? 'Daily Sales' : 'History'}
                </h1>
                <p className="text-brand-100 text-sm font-medium opacity-90">
                  {viewMode === 'home' ? 'Overview & Insights' : 'Archive & Search'}
                </p>
            </div>

            {/* Action Buttons Top Right */}
            <div className="flex gap-2">
              {/* Settings Button */}
               <button 
                onClick={() => setIsSettingsModalOpen(true)}
                className="p-2 rounded-full transition-all active:scale-95 shadow-sm border bg-white/20 backdrop-blur-md border-white/30 text-white hover:bg-white/30"
                title="Settings"
              >
                 <Settings size={22} />
              </button>

              {/* User / Auth Button */}
              <button 
                onClick={() => setIsAuthModalOpen(true)}
                className={`p-2 rounded-full transition-all active:scale-95 shadow-sm border ${currentUser ? 'bg-brand-500 border-brand-400 text-white' : 'bg-white/20 backdrop-blur-md border-white/30 text-white hover:bg-white/30'}`}
                title={currentUser ? "Account" : "Sign In"}
              >
                 {currentUser ? <UserCircle size={24} /> : <User size={22} />}
              </button>

              {viewMode === 'history' && (
                <button 
                  type="button"
                  onClick={() => isSelectionMode ? exitSelectionMode() : enterSelectionMode()} 
                  className={`text-xs px-4 py-2 rounded-full flex items-center gap-1.5 transition-all font-bold shadow-sm active:scale-95 ${isSelectionMode ? 'bg-white text-brand-700 shadow-md' : 'bg-white/20 backdrop-blur-md text-white hover:bg-white/30'}`}
                >
                  <CheckSquare size={14} strokeWidth={2.5} /> {isSelectionMode ? 'Done' : 'Select'}
                </button>
              )}
            </div>
        </div>

        {/* Search Bar - Only in History Mode */}
        {viewMode === 'history' && !isSelectionMode && (
          <div className="mt-8 flex gap-3 animate-in fade-in slide-in-from-top-4 duration-500">
            <div className="relative flex-1 group">
              <input 
                type="text" 
                placeholder="Search store name..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-white/10 border border-white/20 backdrop-blur-md rounded-2xl py-3.5 pl-11 pr-4 text-white placeholder-brand-200 focus:outline-none focus:bg-white/20 focus:border-white/40 transition-all text-sm shadow-inner group-hover:bg-white/15"
              />
              <Search className="absolute left-4 top-3.5 text-brand-200 group-hover:text-white transition-colors" size={18} />
            </div>
            <button 
              type="button"
              onClick={() => setShowFilters(!showFilters)}
              className={`p-3.5 rounded-2xl border transition-all active:scale-95 ${showFilters ? 'bg-white text-brand-600 border-white shadow-lg' : 'bg-white/10 text-white border-white/20 hover:bg-white/20'}`}
            >
              <Filter size={20} />
            </button>
            {hasFilters && (
                <button type="button" onClick={resetFilters} className="p-3.5 bg-brand-800 hover:bg-brand-900 rounded-2xl flex items-center justify-center transition-colors shadow-sm active:scale-95">
                    <RefreshCw size={20} className="text-white"/>
                </button>
            )}
          </div>
        )}

        {/* Filters Panel */}
        {viewMode === 'history' && showFilters && !isSelectionMode && (
            <div className="mt-4 grid grid-cols-2 gap-3 animate-in fade-in slide-in-from-top-2">
                <div className="space-y-1">
                    <label className="text-[10px] uppercase font-bold text-brand-200 ml-2 tracking-wider">From Date</label>
                    <input 
                        type="date" 
                        value={startDate}
                        onChange={(e) => setStartDate(e.target.value)}
                        className="w-full bg-white/10 border border-white/20 rounded-xl py-2.5 px-3 text-white text-sm focus:outline-none focus:bg-white/20 transition-colors" 
                    />
                </div>
                <div className="space-y-1">
                    <label className="text-[10px] uppercase font-bold text-brand-200 ml-2 tracking-wider">To Date</label>
                    <input 
                        type="date" 
                        value={endDate}
                        onChange={(e) => setEndDate(e.target.value)}
                        className="w-full bg-white/10 border border-white/20 rounded-xl py-2.5 px-3 text-white text-sm focus:outline-none focus:bg-white/20 transition-colors" 
                    />
                </div>
            </div>
        )}
      </header>

      <div className="px-5 -mt-6 relative z-20">
        {loading ? (
          <div className="bg-white p-10 rounded-2xl shadow-lg border border-gray-100 flex flex-col items-center justify-center animate-in fade-in duration-500">
             <Loader2 size={36} className="text-brand-500 animate-spin mb-3"/>
             <span className="text-gray-400 text-sm font-medium">Syncing data...</span>
          </div>
        ) : (
          <>
            {/* Chart Card */}
            {viewMode === 'home' && chartData.length > 0 && (
              <div className="bg-white p-5 rounded-2xl shadow-lg shadow-gray-200/50 border border-gray-100 mb-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
                <div className="flex items-center justify-between mb-6">
                   <h3 className="text-xs font-bold text-gray-500 uppercase flex items-center gap-2 tracking-wider">
                     <div className="p-1 bg-brand-50 rounded-md"><TrendingUp size={14} className="text-brand-600" /></div>
                     Trend
                   </h3>
                   <span className="text-[10px] text-brand-600 font-bold bg-brand-50 px-2.5 py-1 rounded-full border border-brand-100">Last 7 Days</span>
                </div>
                <div className="h-32 w-full">
                  <ResponsiveContainer width="100%" height="100%" minWidth={0}>
                    <BarChart data={chartData}>
                      <XAxis dataKey="name" tick={{fontSize: 10, fill: '#9ca3af'}} tickLine={false} axisLine={false} dy={10} />
                      <Tooltip 
                        contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', padding: '8px 12px'}}
                        itemStyle={{color: '#0284c7', fontSize: '13px', fontWeight: 'bold'}}
                        cursor={{fill: '#f0f9ff', radius: 4}}
                      />
                      <Bar dataKey="net" radius={[6, 6, 6, 6]} barSize={24}>
                        {chartData.map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={index === chartData.length -1 ? 'url(#colorNet)' : '#e0f2fe'} />
                        ))}
                      </Bar>
                      <defs>
                        <linearGradient id="colorNet" x1="0" y1="0" x2="0" y2="1">
                          <stop offset="0%" stopColor="#0ea5e9" stopOpacity={1}/>
                          <stop offset="100%" stopColor="#0284c7" stopOpacity={1}/>
                        </linearGradient>
                      </defs>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
            )}

            {/* HOME VIEW: Latest Report Card */}
            {viewMode === 'home' && (
              <div className="animate-in fade-in slide-in-from-bottom-6 duration-700">
                 {mostRecentReport ? (
                   <div 
                      onClick={() => navigate(`/report/${mostRecentReport.reportId}`)}
                      className="bg-white p-6 rounded-2xl border border-gray-100 shadow-xl shadow-brand-900/5 active:scale-[0.98] transition-all cursor-pointer group relative overflow-hidden"
                    >
                      <div className={`absolute top-0 right-0 w-32 h-32 rounded-full -mr-10 -mt-10 blur-2xl transition-colors ${mostRecentReport.isOffDay ? 'bg-gray-100/50' : 'bg-brand-50/50 group-hover:bg-brand-100/50'}`}></div>

                      <div className="relative z-10">
                        <div className="flex justify-between items-start mb-3">
                           <span className="bg-gray-900 text-white text-xs font-bold px-2.5 py-1 rounded-lg flex items-center gap-1.5 shadow-sm">
                              <Calendar size={12}/> {mostRecentReport.dateLocal}
                           </span>
                           <span className="text-gray-400 text-xs font-medium bg-gray-50 px-2 py-1 rounded-md">{mostRecentReport.timeLocal}</span>
                        </div>
                        <h3 className="text-xl font-bold text-gray-900 mb-1 line-clamp-1">{mostRecentReport.storeName}</h3>

                        {mostRecentReport.isOffDay ? (
                            <p className="text-xs text-gray-400 mb-4 flex items-center gap-1">
                               <Coffee size={12} /> Relax & Recharge
                            </p>
                        ) : (
                            <p className="text-xs text-gray-500 mb-4">{mostRecentReport.items.length} items recorded</p>
                        )}

                        <div className="flex items-end justify-between border-t border-gray-50 pt-4">
                           {mostRecentReport.isOffDay ? (
                              <div className="flex items-center gap-2 text-gray-400">
                                 <div className="p-1.5 bg-gray-100 rounded-full"><Coffee size={18} /></div>
                                 <span className="text-lg font-bold text-gray-500">Off Day</span>
                              </div>
                           ) : (
                              <div className="text-3xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-brand-600 to-brand-800">
                                  {formatCurrency(mostRecentReport.totals.net)}
                              </div>
                           )}

                           <div className="h-8 w-8 bg-brand-50 rounded-full flex items-center justify-center text-brand-600 group-hover:bg-brand-600 group-hover:text-white transition-all shadow-sm">
                             <ChevronRight size={18} />
                           </div>
                        </div>
                      </div>
                   </div>
                 ) : (
                    <div className="text-center py-12 bg-white rounded-2xl border border-dashed border-gray-200 shadow-sm">
                       <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-3">
                          <FileText className="text-gray-300" size={24} />
                       </div>
                       <p className="text-gray-500 font-medium">{currentUser ? "No reports in your account." : "No reports on this device."}</p>
                       <p className="text-gray-400 text-sm mt-1">Tap + to start your first report.</p>
                    </div>
                 )}
              </div>
            )}

            {/* HISTORY VIEW: Full List */}
            {viewMode === 'history' && (
              <div className="space-y-3 animate-in fade-in slide-in-from-bottom-8 duration-500 mt-2 pb-4">
                {isSelectionMode && (
                  <div className="text-center text-xs text-brand-700 font-bold bg-brand-50 p-3 rounded-xl mb-4 border border-brand-100 flex justify-center items-center gap-2 animate-in fade-in slide-in-from-top-2">
                    <CheckSquare size={14} className="text-brand-600"/> 
                    {selectedIds.size === 0 ? "Select items to delete" : `${selectedIds.size} selected`}
                  </div>
                )}
                {filteredReports.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-20 text-gray-400 bg-white rounded-2xl border border-dashed border-gray-200 shadow-sm mt-4">
                    <div className="bg-gray-50 p-5 rounded-full mb-4">
                       <FileText size={32} className="text-gray-300" />
                    </div>
                    <p className="text-sm font-medium text-gray-600">
                        {hasFilters ? 'No reports match your filters.' : 'No reports found.'}
                    </p>
                  </div>
                ) : (
                  filteredReports.map((report) => {
                    const isSelected = selectedIds.has(report.reportId);
                    const isOffDay = report.isOffDay;

                    return (
                      <div 
                        key={report.reportId}
                        onTouchStart={() => handleTouchStart(report.reportId)}
                        onTouchEnd={handleTouchEnd}
                        onTouchMove={handleTouchMove}
                        onClick={() => handleCardClick(report.reportId)}
                        className={`bg-white p-4 rounded-2xl border shadow-sm transition-all cursor-pointer flex justify-between items-center group relative overflow-hidden select-none ${
                          isSelectionMode 
                             ? isSelected 
                                ? 'border-brand-500 ring-1 ring-brand-500 bg-brand-50/30' 
                                : 'border-gray-100 opacity-100'
                             : 'border-gray-100 hover:border-brand-200 hover:shadow-md active:scale-[0.98]'
                        }`}
                      >
                        {isSelectionMode && (
                          <div className={`mr-4 w-6 h-6 min-w-[1.5rem] rounded-full border-2 flex items-center justify-center transition-all duration-200 ${isSelected ? 'bg-brand-500 border-brand-500 scale-110' : 'bg-white border-gray-300'}`}>
                            {isSelected && <Check size={14} className="text-white" strokeWidth={3} />}
                          </div>
                        )}

                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 mb-1.5">
                            <div className="flex items-center gap-1.5 bg-gray-50 border border-gray-100 px-2 py-0.5 rounded text-gray-600 shadow-sm">
                                <Calendar size={10} className="text-gray-400" />
                                <span className="text-[10px] font-bold uppercase tracking-wide">{report.dateLocal}</span>
                            </div>
                            <span className="text-[10px] text-gray-400 font-medium">{report.timeLocal}</span>
                          </div>
                          <p className={`text-sm font-bold truncate pr-2 ${isSelected ? 'text-brand-900' : 'text-gray-900'}`}>{report.storeName}</p>
                        </div>
                        <div className="text-right">
                          {isOffDay ? (
                              <span className="text-[10px] font-bold text-gray-400 bg-gray-100 border border-gray-200 px-2 py-1 rounded-md uppercase tracking-wider">Off Day</span>
                          ) : (
                              <span className={`block text-base font-bold ${isSelected ? 'text-brand-700' : 'text-brand-600'}`}>{formatCurrency(report.totals.net)}</span>
                          )}

                          {!isSelectionMode && !isOffDay && (
                            <div className="flex items-center justify-end text-gray-400 text-[10px] mt-1 font-medium uppercase tracking-wide group-hover:text-brand-400 transition-colors">
                              {report.items.length} items <ChevronRight size={10} className="ml-1" />
                            </div>
                          )}
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            )}
          </>
        )}
      </div>

      {/* Floating Bottom Action Bar */}
      <div className="fixed bottom-6 left-1/2 transform -translate-x-1/2 w-[calc(100%-3rem)] max-w-md z-50">

        {isSelectionMode ? (
           <div className="flex gap-3 animate-in slide-in-from-bottom-6 duration-300">
              <button 
                type="button"
                onClick={exitSelectionMode}
                className="flex-1 h-14 bg-white/90 backdrop-blur-md border border-gray-200 text-gray-700 font-bold rounded-2xl shadow-xl flex items-center justify-center gap-2 hover:bg-white active:scale-95 transition-all"
              >
                <X size={20} /> Cancel
              </button>
              <button 
                type="button"
                onClick={deleteSelectedReports}
                disabled={selectedIds.size === 0}
                className="flex-[2] h-14 bg-red-600 text-white font-bold rounded-2xl shadow-xl shadow-red-600/30 flex items-center justify-center gap-2 hover:bg-red-700 active:scale-95 transition-all disabled:opacity-50 disabled:shadow-none"
              >
                <Trash2 size={20} fill="currentColor" className="text-red-600/20" /> 
                <span>Delete ({selectedIds.size})</span>
              </button>
           </div>
        ) : (
          <div className="bg-white/80 backdrop-blur-xl border border-white/40 p-2 rounded-[2rem] shadow-2xl shadow-gray-200/50 flex items-center justify-between pl-3 pr-2 gap-4 ring-1 ring-gray-200/50">
            <div className="flex bg-gray-100/80 p-1 rounded-full relative">
               <div 
                 className={`absolute top-1 bottom-1 w-[calc(50%-4px)] bg-white rounded-full shadow-sm transition-all duration-300 ease-out ${viewMode === 'home' ? 'left-1' : 'left-[calc(50%+2px)]'}`}
               ></div>

               <button 
                  type="button"
                  onClick={() => setViewMode('home')}
                  className={`relative z-10 w-12 h-10 rounded-full flex items-center justify-center transition-colors duration-300 ${viewMode === 'home' ? 'text-brand-600' : 'text-gray-400'}`}
               >
                  <LayoutDashboard size={20} />
               </button>
               <button 
                  type="button"
                  onClick={() => setViewMode('history')}
                  className={`relative z-10 w-12 h-10 rounded-full flex items-center justify-center transition-colors duration-300 ${viewMode === 'history' ? 'text-brand-600' : 'text-gray-400'}`}
               >
                  <History size={20} />
               </button>
            </div>

            <button 
              type="button"
              onClick={() => navigate('/new')}
              className="h-14 px-8 bg-gray-900 text-white rounded-[1.5rem] shadow-lg shadow-gray-900/20 flex items-center justify-center gap-2 hover:bg-black active:scale-95 transition-all group"
            >
              <Plus size={24} className="group-hover:rotate-90 transition-transform duration-300" />
              <span className="font-bold text-sm">New Report</span>
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { ArrowLeft, Share2, Clock, MapPin, User, Calendar, CheckCircle, Globe, AlertTriangle, Loader2, Undo2, Redo2, Save, Users, X, Split, Percent, Copy, MessageCircle, ArrowRightLeft, ArrowRight, ArrowLeft as ArrowLeftIcon, Plus, Minus, Coffee } from 'lucide-react';
import { DailyReport, SalesItem, SourceType } from '../types';
import * as StorageService from '../services/storageService';
import * as CalculationUtils from '../utils/calculations';
import { MOCK_STORES } from '../constants';
import useUndoRedo from '../hooks/useUndoRedo';

import CapturePanel from '../components/CapturePanel';
import ItemsTable from '../components/ItemsTable';
import TotalsPanel from '../components/TotalsPanel';

const ReportEditor: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const isNew = !id;

  const [loading, setLoading] = useState(true);
  const [processing, setProcessing] = useState(false);
  const [saving, setSaving] = useState(false);

  // Use Custom Hook for State Management
  const { state: report, set: setReport, undo, redo, canUndo, canRedo, init: initReport } = useUndoRedo<DailyReport | null>(null);

  const [isDirty, setIsDirty] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const [dateWarning, setDateWarning] = useState<{msg: string, date: string} | null>(null);

  // Validation State
  const [errors, setErrors] = useState<Record<number, { [key in keyof SalesItem]?: string } & { items?: string }>>({});
  const [globalError, setGlobalError] = useState<string | null>(null);

  // Split Feature State
  const [isSplitModalOpen, setIsSplitModalOpen] = useState(false);
  const [splitRatio, setSplitRatio] = useState<0.5 | 0.6 | 0.7>(0.5);
  const [staff2Name, setStaff2Name] = useState('');

  // Advanced Split State
  const [splitItemsA, setSplitItemsA] = useState<SalesItem[]>([]);
  const [splitItemsB, setSplitItemsB] = useState<SalesItem[]>([]);

  // New State for Success View
  const [createdSplitReports, setCreatedSplitReports] = useState<{a: DailyReport, b: DailyReport} | null>(null);

  // Initialize Report
  useEffect(() => {
    const init = async () => {
      if (isNew) {
        const { dateLocal, timeLocal, tz } = CalculationUtils.getLocalDateTimeAndTimezone();
        const config = StorageService.loadConfig();

        const newReport: DailyReport = {
          reportId: CalculationUtils.generateId(),
          dateLocal,
          timeLocal,
          timezone: tz,
          storeName: MOCK_STORES[0],
          salesRepName: config.salesRepName || '',
          items: [],
          totals: { gross: 0, discounts: 0, net: 0 },
          sources: [],
          attachments: [],
          shareMessage: '',
          createdAt: Date.now(),
          isOffDay: false
        };

        // Initial auto-check for off-day based on today's date
        if (config.defaultOffDay !== undefined) {
           const parts = dateLocal.split('-');
           const todayIndex = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2])).getDay();
           if (todayIndex === config.defaultOffDay) {
             newReport.isOffDay = true;
             // Re-calc share message
             newReport.shareMessage = CalculationUtils.buildShareMessage(newReport);
           }
        }

        initReport(newReport);
        setLoading(false);
      } else {
        const existing = await StorageService.getReportById(id as string);
        if (existing) {
          initReport(existing);
        } else {
          alert("Report not found");
          navigate('/');
        }
        setLoading(false);
      }
    };
    init();
  }, [id, isNew, navigate, initReport]);

  // Reset split state when modal closes/opens
  useEffect(() => {
    if (!isSplitModalOpen) {
      setCreatedSplitReports(null);
      setStaff2Name('');
    }
  }, [isSplitModalOpen]);

  // Atomic Update Function
  const updateReport = useCallback((changes: Partial<DailyReport>) => {
    if (!report) return;

    const updatedReport = { ...report, ...changes };

    // 1. Recalculate Totals
    const newTotals = CalculationUtils.computeTotals(updatedReport.items, updatedReport.totals.discounts);
    updatedReport.totals = newTotals;

    // 2. Recalculate Share Message
    updatedReport.shareMessage = CalculationUtils.buildShareMessage(updatedReport);

    setReport(updatedReport);
    setIsDirty(true);
  }, [report, setReport]);

  // Effect: Watch for date changes to apply default Off-Day logic
  useEffect(() => {
    if (!report) return;

    // Only apply logic if we are editing the date, to provide the "unless I change or pick another" experience.
    // However, since we can't easily track *why* this effect fired (user input vs init), we rely on state comparison.
    // Actually, we can check the config every time the date changes.

    const config = StorageService.loadConfig();
    if (config.defaultOffDay === undefined) return;

    try {
      const parts = report.dateLocal.split('-');
      // Construct date in local time to get correct day index (0-6)
      const dateObj = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]));
      const dayIndex = dateObj.getDay();

      // Logic:
      // If the selected day MATCHES the default off-day -> Turn ON isOffDay
      // If the selected day DOES NOT MATCH -> Turn OFF isOffDay (assuming user wants to work on other days)

      const shouldBeOffDay = dayIndex === config.defaultOffDay;

      if (shouldBeOffDay && !report.isOffDay) {
        updateReport({ isOffDay: true });
      } else if (!shouldBeOffDay && report.isOffDay) {
        // Only auto-turn off if the report is empty, to prevent accidental data loss if they move a populated report to another date
        if (report.items.length === 0) {
           updateReport({ isOffDay: false });
        }
      }

    } catch (e) {
      console.error("Date parsing error in effect", e);
    }

  }, [report?.dateLocal]); // Only trigger when dateLocal changes

  // Calculate Initial Split when modal opens or ratio changes
  useEffect(() => {
    if (isSplitModalOpen && report && !createdSplitReports) {
      const [itemsA, itemsB] = CalculationUtils.splitSalesItems(report.items, splitRatio);
      setSplitItemsA(itemsA);
      setSplitItemsB(itemsB);
    }
  }, [isSplitModalOpen, splitRatio, report, createdSplitReports]);

  // Manual Move Logic
  const moveOneUnit = (fromList: SalesItem[], toList: SalesItem[], index: number, setFrom: any, setTo: any) => {
    const itemToMove = fromList[index];
    if (!itemToMove) return;

    // 1. Remove 1 unit from source
    const newFrom = [...fromList];
    if (itemToMove.quantity > 1) {
        newFrom[index] = { ...itemToMove, quantity: itemToMove.quantity - 1 };
    } else {
        newFrom.splice(index, 1);
    }

    // 2. Add 1 unit to destination
    const newTo = [...toList];
    const existingIndex = newTo.findIndex(i => 
        i.productName === itemToMove.productName && 
        i.unitPrice === itemToMove.unitPrice && 
        i.sku === itemToMove.sku &&
        i.notes === itemToMove.notes
    );

    if (existingIndex >= 0) {
        newTo[existingIndex] = { ...newTo[existingIndex], quantity: newTo[existingIndex].quantity + 1 };
    } else {
        newTo.push({ ...itemToMove, quantity: 1 });
    }

    // Update state
    setFrom(newFrom);
    setTo(newTo);
  };

  // Helper to calculate totals for the split view
  const getTotal = (items: SalesItem[]) => items.reduce((sum, i) => sum + (i.quantity * i.unitPrice), 0);

  // Timezone & Date Consistency Check
  useEffect(() => {
    if (!report?.timezone || !report?.dateLocal) return;

    try {
      const now = new Date();
      const formatter = new Intl.DateTimeFormat('en-CA', { // en-CA is yyyy-mm-dd
        timeZone: report.timezone,
        year: 'numeric',
        month: '2-digit',
        day: '2-digit'
      });
      const todayInTz = formatter.format(now);

      if (todayInTz !== report.dateLocal) {
        setDateWarning({
          msg: `It is currently ${todayInTz} in ${report.timezone.split('/')[1] || report.timezone}.`,
          date: todayInTz
        });
      } else {
        setDateWarning(null);
      }
    } catch (e) {
      setDateWarning(null); 
    }
  }, [report?.timezone, report?.dateLocal]);

  const validate = (): boolean => {
    if (!report) return false;
    let isValid = true;
    const newErrors: Record<number, { [key in keyof SalesItem]?: string } & { items?: string }> = {};
    setGlobalError(null);

    // 1. Check Items Length (Relaxed if Off Day)
    if (!report.isOffDay && report.items.length === 0) {
      newErrors[-1] = { items: "At least one item is required." }; 
      setGlobalError("Please add at least one item.");
      isValid = false;
    }

    // 2. Check Item Fields
    report.items.forEach((item, index) => {
      const itemErrors: { [key in keyof SalesItem]?: string } = {};

      if (!item.productName || !(item.productName || '').trim()) {
        itemErrors.productName = "Required";
        isValid = false;
      }

      if (item.quantity <= 0 || isNaN(item.quantity) || !Number.isInteger(item.quantity)) {
        itemErrors.quantity = "Min 1";
        isValid = false;
      }

      if (item.unitPrice < 0 || isNaN(item.unitPrice)) {
        itemErrors.unitPrice = "Invalid";
        isValid = false;
      }

      if (Object.keys(itemErrors).length > 0) {
        newErrors[index] = itemErrors;
      }
    });

    setErrors(newErrors);
    return isValid;
  };

  // Helper: Sanitize input to prevent XSS (HTML tags) and CSV Injection
  const sanitizeInput = (input: string): string => {
    if (!input) return '';

    // 1. Strip HTML tags
    let clean = input.replace(/<\/?[^>]+(>|$)/g, "");

    // 2. Prevent CSV Formula Injection
    // If string starts with =, +, -, or @, prepend a single quote to force it as text
    if (/^[=+\-@]/.test(clean)) {
      clean = "'" + clean;
    }

    return clean.trim();
  };

  const handleSave = async () => {
    if (!report) return false;

    // Sanitize text fields
    const salesRepName = sanitizeInput(report.salesRepName);
    report.salesRepName = salesRepName;

    report.items = report.items.map(i => ({
      ...i,
      productName: sanitizeInput(i.productName),
      sku: sanitizeInput(i.sku),
      notes: sanitizeInput(i.notes)
    }));

    if (!salesRepName) {
      alert("Please enter a Sales Rep Name");
      return false;
    }

    if (!validate()) {
      return false;
    }

    setSaving(true);
    try {
      await StorageService.saveReport(report);
      StorageService.saveConfig({ salesRepName: report.salesRepName, defaultOffDay: StorageService.loadConfig().defaultOffDay });
      setIsDirty(false);
      setErrors({});

      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 2000);
      return true;
    } catch (e: any) {
      // Improved Error Handling: Show specific message from service
      alert(e.message || "Failed to save report. Please check your connection.");
      return false;
    } finally {
      setSaving(false);
    }
  };

  const handleSaveAndExit = async () => {
    const success = await handleSave();
    if (success) navigate('/');
  };

  const handleShare = async () => {
    if (isDirty || isNew) {
      const success = await handleSave();
      if (!success) return;
    }
    navigate(`/share/${report?.reportId}`);
  };

  const handleSplit = () => {
    if (!report) return;
    if (!staff2Name.trim()) {
      alert("Please enter a name for the second staff member.");
      return;
    }

    setSaving(true);
    try {
      // 1. Prepare Report A (Current User/Staff 1)
      const reportA: DailyReport = {
        ...report,
        reportId: CalculationUtils.generateId(), // New ID
        items: splitItemsA,
        totals: CalculationUtils.computeTotals(splitItemsA, 0), // Assuming no discounts split for now
        salesRepName: report.salesRepName,
        createdAt: Date.now()
      };
      reportA.shareMessage = CalculationUtils.buildShareMessage(reportA);

      // 2. Prepare Report B (Staff 2)
      const reportB: DailyReport = {
        ...report,
        reportId: CalculationUtils.generateId(), // New ID
        items: splitItemsB,
        totals: CalculationUtils.computeTotals(splitItemsB, 0),
        salesRepName: staff2Name,
        createdAt: Date.now() + 1 // Ensure distinct timestamps
      };
      reportB.shareMessage = CalculationUtils.buildShareMessage(reportB);

      // NOTE: We do NOT save these to DB or delete the original.
      // This is purely for generating shareable content.

      // Save config for convenience
      StorageService.saveConfig({ salesRepName: report.salesRepName, defaultOffDay: StorageService.loadConfig().defaultOffDay });

      // 4. Update State to Show Success View
      setCreatedSplitReports({ a: reportA, b: reportB });

    } catch (e: any) {
      console.error(e);
      alert(`Failed to generate split reports: ${e.message}`);
    } finally {
      setSaving(false);
    }
  };

  const handleItemsCaptured = (newItems: SalesItem[], source: SourceType) => {
    if (!report) return;
    updateReport({
      items: [...report.items, ...newItems],
      sources: Array.from(new Set([...report.sources, source]))
    });
  };

  const handleRemoveAttachment = (index: number) => {
    if (!report) return;
    const newAttachments = [...report.attachments];
    newAttachments.splice(index, 1);
    updateReport({ attachments: newAttachments });
  };

  const handleAddAttachments = (urls: string[]) => {
    if (!report) return;
    const newAttachments = urls.map(url => ({ type: 'image' as const, url }));
    updateReport({ attachments: [...report.attachments, ...newAttachments] });
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    // Could add a toast here
  };

  const shareViaWhatsApp = (text: string) => {
    const url = `https://wa.me/?text=${encodeURIComponent(text)}`;
    window.open(url, '_blank');
  };

  if (loading || !report) return <div className="p-8 text-center text-gray-500 flex flex-col items-center justify-center min-h-screen"><Loader2 className="animate-spin mb-3 text-brand-600" size={32} />Loading...</div>;

  return (
    <div className="min-h-screen bg-gray-50 pb-32">
      {/* Split Modal */}
      {isSplitModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity" onClick={() => setIsSplitModalOpen(false)}></div>
          <div className="relative bg-white rounded-t-3xl sm:rounded-3xl w-full max-w-2xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-10 sm:zoom-in-95 duration-300 flex flex-col max-h-[95vh]">

            <div className="bg-brand-600 p-4 text-white flex justify-between items-center shrink-0">
               <h2 className="text-lg font-bold flex items-center gap-2">
                 <Users size={20} /> 
                 {createdSplitReports ? 'Reports Generated' : 'Split Report'}
               </h2>
               <button onClick={() => setIsSplitModalOpen(false)} className="bg-white/10 p-1.5 rounded-full hover:bg-white/20">
                 <X size={18} />
               </button>
            </div>

            <div className="p-5 overflow-y-auto flex-1 bg-gray-50/50">
              {!createdSplitReports ? (
                <>
                  {/* CONFIGURATION MODE */}
                  {/* Ratio Selector */}
                  <div className="mb-6 bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
                    <label className="text-xs font-bold text-gray-500 uppercase mb-2 block flex items-center gap-2">
                       <Split size={14} /> Auto-Split Ratio
                    </label>
                    <div className="grid grid-cols-3 gap-2 bg-gray-100 p-1 rounded-xl">
                        {[0.5, 0.6, 0.7].map((r) => (
                          <button
                            key={r}
                            onClick={() => setSplitRatio(r as any)}
                            className={`py-2 rounded-lg text-sm font-bold transition-all ${splitRatio === r ? 'bg-white text-brand-700 shadow-sm ring-1 ring-gray-200' : 'text-gray-400 hover:text-gray-600'}`}
                          >
                            {r * 100} / {100 - (r * 100)}
                          </button>
                        ))}
                    </div>
                  </div>

                  {/* Staff Names */}
                  <div className="grid grid-cols-2 gap-4 mb-4">
                    <div>
                      <label className="text-xs font-bold text-brand-600 uppercase mb-1 block">Staff A (You)</label>
                      <input 
                          type="text" 
                          value={report.salesRepName} 
                          onChange={(e) => updateReport({ salesRepName: e.target.value })}
                          className="w-full bg-white border border-gray-200 rounded-xl px-3 py-2 text-sm font-semibold focus:border-brand-500 focus:ring-1 focus:ring-brand-500 outline-none"
                          placeholder="Name 1"
                      />
                    </div>
                    <div>
                      <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">Staff B</label>
                      <input 
                          type="text" 
                          value={staff2Name} 
                          onChange={(e) => setStaff2Name(e.target.value)}
                          className="w-full bg-white border border-brand-300 rounded-xl px-3 py-2 text-sm font-semibold focus:border-brand-500 focus:ring-2 focus:ring-brand-100 outline-none"
                          placeholder="Enter Name 2"
                          autoFocus
                      />
                    </div>
                  </div>

                  {/* Detailed Item List */}
                  <div className="flex flex-col sm:flex-row gap-3 h-full min-h-[300px]">
                      {/* Left Column (A) */}
                      <div className="flex-1 bg-brand-50/50 border border-brand-100 rounded-xl overflow-hidden flex flex-col">
                         <div className="p-3 bg-brand-50 border-b border-brand-100 flex justify-between items-center">
                            <span className="font-bold text-brand-900 text-xs">Staff A</span>
                            <span className="font-extrabold text-brand-700 text-sm">{CalculationUtils.formatCurrency(getTotal(splitItemsA))}</span>
                         </div>
                         <div className="flex-1 overflow-y-auto p-2 space-y-2 max-h-[250px] sm:max-h-[350px]">
                            {splitItemsA.length === 0 && <div className="text-center p-4 text-xs text-brand-300 font-medium italic">No items</div>}
                            {splitItemsA.map((item, i) => (
                                <div key={i} 
                                   onClick={() => moveOneUnit(splitItemsA, splitItemsB, i, setSplitItemsA, setSplitItemsB)}
                                   className="bg-white p-2 rounded-lg border border-brand-100 shadow-sm cursor-pointer hover:bg-brand-50 active:scale-95 transition-all flex justify-between items-center group"
                                >
                                   <div className="flex items-center gap-2 overflow-hidden">
                                     <span className="bg-brand-100 text-brand-700 text-[10px] font-bold px-1.5 py-0.5 rounded min-w-[20px] text-center">{item.quantity}</span>
                                     <span className="text-xs font-medium text-gray-700 truncate">{item.productName}</span>
                                   </div>
                                   <ArrowRight size={14} className="text-brand-300 group-hover:text-brand-500" />
                                </div>
                            ))}
                         </div>
                      </div>

                      {/* Divider */}
                      <div className="flex items-center justify-center text-gray-300">
                        <ArrowRightLeft className="rotate-90 sm:rotate-0" size={20} />
                      </div>

                      {/* Right Column (B) */}
                      <div className="flex-1 bg-gray-50 border border-gray-200 rounded-xl overflow-hidden flex flex-col">
                         <div className="p-3 bg-gray-100 border-b border-gray-200 flex justify-between items-center">
                            <span className="font-bold text-gray-600 text-xs">Staff B</span>
                            <span className="font-extrabold text-gray-700 text-sm">{CalculationUtils.formatCurrency(getTotal(splitItemsB))}</span>
                         </div>
                         <div className="flex-1 overflow-y-auto p-2 space-y-2 max-h-[250px] sm:max-h-[350px]">
                            {splitItemsB.length === 0 && <div className="text-center p-4 text-xs text-gray-300 font-medium italic">No items</div>}
                            {splitItemsB.map((item, i) => (
                                <div key={i} 
                                   onClick={() => moveOneUnit(splitItemsB, splitItemsA, i, setSplitItemsB, setSplitItemsA)}
                                   className="bg-white p-2 rounded-lg border border-gray-200 shadow-sm cursor-pointer hover:bg-gray-50 active:scale-95 transition-all flex justify-between items-center group"
                                >
                                   <ArrowLeftIcon size={14} className="text-gray-300 group-hover:text-gray-500 order-first mr-2" />
                                   <div className="flex items-center gap-2 overflow-hidden flex-1">
                                     <span className="bg-gray-100 text-gray-600 text-[10px] font-bold px-1.5 py-0.5 rounded min-w-[20px] text-center">{item.quantity}</span>
                                     <span className="text-xs font-medium text-gray-700 truncate">{item.productName}</span>
                                   </div>
                                </div>
                            ))}
                         </div>
                      </div>
                  </div>

                  <div className="mt-3 text-center">
                     <span className="text-[10px] font-medium text-gray-400 bg-gray-100 px-3 py-1 rounded-full">
                       Tip: Tap an item to move 1 unit to the other list
                     </span>
                  </div>
                </>
              ) : (
                <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4">
                  <div className="text-center mb-6">
                    <div className="w-12 h-12 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-2">
                      <CheckCircle size={24} />
                    </div>
                    <p className="text-sm text-gray-600">Reports generated. You can now share them.</p>
                  </div>

                  {/* Result Card A */}
                  <div className="bg-white border border-gray-200 rounded-2xl p-4 shadow-sm">
                     <div className="flex justify-between items-center mb-3">
                        <div>
                          <span className="text-xs font-bold text-brand-600 bg-brand-50 px-2 py-0.5 rounded-md uppercase tracking-wide">Staff A</span>
                          <h4 className="font-bold text-gray-900 mt-1">{createdSplitReports.a.salesRepName}</h4>
                        </div>
                        <span className="font-extrabold text-lg text-brand-700">{CalculationUtils.formatCurrency(createdSplitReports.a.totals.net)}</span>
                     </div>
                     <div className="grid grid-cols-2 gap-2">
                        <button 
                          onClick={() => copyToClipboard(createdSplitReports.a.shareMessage)}
                          className="flex items-center justify-center gap-1.5 py-2.5 bg-gray-50 hover:bg-gray-100 text-gray-700 text-xs font-bold rounded-xl transition-colors border border-gray-100"
                        >
                          <Copy size={14} /> Copy Text
                        </button>
                        <button 
                          onClick={() => shareViaWhatsApp(createdSplitReports.a.shareMessage)}
                          className="flex items-center justify-center gap-1.5 py-2.5 bg-[#25D366] hover:bg-[#20bd5a] text-white text-xs font-bold rounded-xl transition-colors shadow-sm"
                        >
                          <MessageCircle size={14} fill="white" /> WhatsApp
                        </button>
                     </div>
                  </div>

                  {/* Result Card B */}
                  <div className="bg-white border border-gray-200 rounded-2xl p-4 shadow-sm">
                     <div className="flex justify-between items-center mb-3">
                        <div>
                          <span className="text-xs font-bold text-gray-500 bg-gray-100 px-2 py-0.5 rounded-md uppercase tracking-wide">Staff B</span>
                          <h4 className="font-bold text-gray-900 mt-1">{createdSplitReports.b.salesRepName}</h4>
                        </div>
                        <span className="font-extrabold text-lg text-gray-700">{CalculationUtils.formatCurrency(createdSplitReports.b.totals.net)}</span>
                     </div>
                     <div className="grid grid-cols-2 gap-2">
                        <button 
                          onClick={() => copyToClipboard(createdSplitReports.b.shareMessage)}
                          className="flex items-center justify-center gap-1.5 py-2.5 bg-gray-50 hover:bg-gray-100 text-gray-700 text-xs font-bold rounded-xl transition-colors border border-gray-100"
                        >
                          <Copy size={14} /> Copy Text
                        </button>
                        <button 
                          onClick={() => shareViaWhatsApp(createdSplitReports.b.shareMessage)}
                          className="flex items-center justify-center gap-1.5 py-2.5 bg-[#25D366] hover:bg-[#20bd5a] text-white text-xs font-bold rounded-xl transition-colors shadow-sm"
                        >
                          <MessageCircle size={14} fill="white" /> WhatsApp
                        </button>
                     </div>
                  </div>

                </div>
              )}
            </div>

            <div className="p-4 border-t border-gray-100 bg-gray-50 flex gap-3 shrink-0">
               {!createdSplitReports ? (
                 <>
                   <button 
                     onClick={() => setIsSplitModalOpen(false)}
                     className="flex-1 py-3 font-bold text-gray-600 bg-white border border-gray-200 rounded-xl hover:bg-gray-50"
                   >
                     Cancel
                   </button>
                   <button 
                     onClick={handleSplit}
                     disabled={saving || !staff2Name}
                     className="flex-[2] py-3 font-bold text-white bg-brand-600 rounded-xl shadow-lg shadow-brand-500/20 hover:bg-brand-700 disabled:opacity-50 disabled:shadow-none flex items-center justify-center gap-2"
                   >
                     {saving ? <Loader2 className="animate-spin" size={18} /> : <Split size={18} />}
                     Generate Split
                   </button>
                 </>
               ) : (
                 <button 
