import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Plus, Search, ChevronRight, FileText, TrendingUp, Calendar, Filter, RefreshCw, History, LayoutDashboard, Loader2, Trash2, CheckSquare, X, Check, User, UserCircle, Coffee, Settings } from 'lucide-react';
import { DailyReport } from '../types';
import * as StorageService from '../services/storageService';
import * as AuthService from '../services/authService';
import { formatCurrency } from '../utils/calculations';
import { BarChart, Bar, XAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import AuthModal from '../components/AuthModal';
import SettingsModal from '../components/SettingsModal';

type ViewMode = 'home' | 'history';

const Dashboard: React.FC = () => {
  const navigate = useNavigate();
  const [reports, setReports] = useState<DailyReport[]>([]);
  const [loading, setLoading] = useState(true);
  const [viewMode, setViewMode] = useState<ViewMode>('home');

  // Auth State
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);

  // Settings State
  const [isSettingsModalOpen, setIsSettingsModalOpen] = useState(false);

  // Selection Mode State
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Filter states
  const [searchTerm, setSearchTerm] = useState('');
  const [showFilters, setShowFilters] = useState(false);
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  // Long Press State (Replaced useRef with useState for compatibility)
  const [longPressTimer, setLongPressTimer] = useState<any>(null);
  const [isLongPress, setIsLongPress] = useState(false);

  const initData = async () => {
    setLoading(true);
    // 1. Check Auth
    const user = await AuthService.getCurrentUser();
    setCurrentUser(user);

    // 2. Load Reports (storageService now handles isolation based on auth state)
    const data = await StorageService.loadReports();
    setReports(data);
    setLoading(false);
  };

  useEffect(() => {
    initData();
  }, []);

  const handleAuthSuccess = async () => {
    // Reload everything after auth state change
    await initData();
  };

  // --- Selection Logic ---

  const enterSelectionMode = (initialId?: string) => {
    setIsSelectionMode(true);
    if (initialId) {
      setSelectedIds(new Set([initialId]));
    }
  };

  const exitSelectionMode = () => {
    setIsSelectionMode(false);
    setSelectedIds(new Set());
  };

  const toggleReportSelection = (id: string) => {
    const newSelected = new Set(selectedIds);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedIds(newSelected);
  };

  const deleteSelectedReports = async (e: React.MouseEvent) => {
    e.preventDefault(); 
    if (selectedIds.size === 0) return;

    setLoading(true);
    try {
      await StorageService.deleteReports(Array.from(selectedIds));
      const data = await StorageService.loadReports();
      setReports(data);
      exitSelectionMode();
    } catch (e) {
      alert("Failed to delete selected reports.");
    } finally {
      setLoading(false);
    }
  };

  // --- Long Press Handlers ---
  const handleTouchStart = (id: string) => {
    if (isSelectionMode) return;

    // Reset state
    setIsLongPress(false);

    const timer = setTimeout(() => {
      setIsLongPress(true);
      enterSelectionMode(id);
      if (navigator.vibrate) navigator.vibrate(50);
    }, 600);

    setLongPressTimer(timer);
  };

  const handleTouchEnd = () => {
    if (longPressTimer) {
      clearTimeout(longPressTimer);
      setLongPressTimer(null);
    }
  };

  const handleTouchMove = () => {
    if (longPressTimer) {
      clearTimeout(longPressTimer);
      setLongPressTimer(null);
    }
  };

  const handleCardClick = (id: string) => {
    // If long press was detected (and triggered selection mode), we prevent standard click logic
    // However, if we are ALREADY in selection mode, long press logic is bypassed above, 
    // so we just toggle.
    // The only edge case is the split second where long press triggered but user also lifts finger
    // triggering onClick.

    if (isLongPress) {
      setIsLongPress(false); // Reset for next time
      return;
    }

    if (isSelectionMode) {
      toggleReportSelection(id);
    } else {
      navigate(`/report/${id}`);
    }
  };

  // --- Filtering ---

  const filteredReports = reports.filter(r => {
    const matchesSearch = !searchTerm || r.storeName.toLowerCase().includes(searchTerm.toLowerCase());
    const reportDate = r.dateLocal;
    const matchesStart = !startDate || reportDate >= startDate;
    const matchesEnd = !endDate || reportDate <= endDate;
    return matchesSearch && matchesStart && matchesEnd;
  }).sort((a, b) => b.dateLocal.localeCompare(a.dateLocal) || b.createdAt - a.createdAt);

  const mostRecentReport = [...reports].sort((a, b) => b.createdAt - a.createdAt)[0];

  // Exclude off days from the chart data to avoid dipping the graph incorrectly (or include as 0 if desired)
  const sortedForChart = [...reports].sort((a, b) => a.dateLocal.localeCompare(b.dateLocal));
  const chartData = sortedForChart.slice(-7).map(r => ({
    name: r.dateLocal.slice(5),
    net: r.isOffDay ? 0 : r.totals.net
  }));

  const resetFilters = () => {
    setSearchTerm('');
    setStartDate('');
    setEndDate('');
    setShowFilters(false);
  };

  const hasFilters = searchTerm || startDate || endDate;

  return (
    <div className="min-h-screen bg-gray-50/50 pb-32 font-sans">
      <AuthModal 
        isOpen={isAuthModalOpen} 
        onClose={() => setIsAuthModalOpen(false)} 
        user={currentUser}
        onAuthSuccess={handleAuthSuccess}
      />

      <SettingsModal
        isOpen={isSettingsModalOpen}
        onClose={() => setIsSettingsModalOpen(false)}
        onSave={() => { /* Config is saved inside modal, maybe trigger refresh if needed */ }}
      />

      {/* Header Area */}
      <header className={`bg-gradient-to-br from-brand-700 via-brand-600 to-brand-800 text-white px-6 pt-12 pb-8 rounded-b-[2.5rem] shadow-xl transition-all duration-300 relative overflow-hidden ${viewMode === 'history' ? 'pb-8' : ''}`}>
        <div className="absolute top-0 left-0 w-full h-full overflow-hidden opacity-10 pointer-events-none">
           <div className="absolute -top-10 -right-10 w-40 h-40 bg-white rounded-full blur-3xl"></div>
           <div className="absolute bottom-0 left-0 w-60 h-60 bg-brand-300 rounded-full blur-3xl"></div>
        </div>

        <div className="relative z-10 flex justify-between items-start">
            <div>
                <h1 className="text-3xl font-extrabold mb-1 tracking-tight">
                  {viewMode === 'home' ? 'Daily Sales' : 'History'}
                </h1>
                <p className="text-brand-100 text-sm font-medium opacity-90">
                  {viewMode === 'home' ? 'Overview & Insights' : 'Archive & Search'}
                </p>
            </div>

            {/* Action Buttons Top Right */}
            <div className="flex gap-2">
              {/* Settings Button */}
               <button 
                onClick={() => setIsSettingsModalOpen(true)}
                className="p-2 rounded-full transition-all active:scale-95 shadow-sm border bg-white/20 backdrop-blur-md border-white/30 text-white hover:bg-white/30"
                title="Settings"
              >
                 <Settings size={22} />
              </button>

              {/* User / Auth Button */}
              <button 
                onClick={() => setIsAuthModalOpen(true)}
                className={`p-2 rounded-full transition-all active:scale-95 shadow-sm border ${currentUser ? 'bg-brand-500 border-brand-400 text-white' : 'bg-white/20 backdrop-blur-md border-white/30 text-white hover:bg-white/30'}`}
                title={currentUser ? "Account" : "Sign In"}
              >
                 {currentUser ? <UserCircle size={24} /> : <User size={22} />}
              </button>

              {viewMode === 'history' && (
                <button 
                  type="button"
                  onClick={() => isSelectionMode ? exitSelectionMode() : enterSelectionMode()} 
                  className={`text-xs px-4 py-2 rounded-full flex items-center gap-1.5 transition-all font-bold shadow-sm active:scale-95 ${isSelectionMode ? 'bg-white text-brand-700 shadow-md' : 'bg-white/20 backdrop-blur-md text-white hover:bg-white/30'}`}
                >
                  <CheckSquare size={14} strokeWidth={2.5} /> {isSelectionMode ? 'Done' : 'Select'}
                </button>
              )}
            </div>
        </div>

        {/* Search Bar - Only in History Mode */}
        {viewMode === 'history' && !isSelectionMode && (
          <div className="mt-8 flex gap-3 animate-in fade-in slide-in-from-top-4 duration-500">
            <div className="relative flex-1 group">
              <input 
                type="text" 
                placeholder="Search store name..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-white/10 border border-white/20 backdrop-blur-md rounded-2xl py-3.5 pl-11 pr-4 text-white placeholder-brand-200 focus:outline-none focus:bg-white/20 focus:border-white/40 transition-all text-sm shadow-inner group-hover:bg-white/15"
              />
              <Search className="absolute left-4 top-3.5 text-brand-200 group-hover:text-white transition-colors" size={18} />
            </div>
            <button 
              type="button"
              onClick={() => setShowFilters(!showFilters)}
              className={`p-3.5 rounded-2xl border transition-all active:scale-95 ${showFilters ? 'bg-white text-brand-600 border-white shadow-lg' : 'bg-white/10 text-white border-white/20 hover:bg-white/20'}`}
            >
              <Filter size={20} />
            </button>
            {hasFilters && (
                <button type="button" onClick={resetFilters} className="p-3.5 bg-brand-800 hover:bg-brand-900 rounded-2xl flex items-center justify-center transition-colors shadow-sm active:scale-95">
                    <RefreshCw size={20} className="text-white"/>
                </button>
            )}
          </div>
        )}

        {/* Filters Panel */}
        {viewMode === 'history' && showFilters && !isSelectionMode && (
            <div className="mt-4 grid grid-cols-2 gap-3 animate-in fade-in slide-in-from-top-2">
                <div className="space-y-1">
                    <label className="text-[10px] uppercase font-bold text-brand-200 ml-2 tracking-wider">From Date</label>
                    <input 
                        type="date" 
                        value={startDate}
                        onChange={(e) => setStartDate(e.target.value)}
                        className="w-full bg-white/10 border border-white/20 rounded-xl py-2.5 px-3 text-white text-sm focus:outline-none focus:bg-white/20 transition-colors" 
                    />
                </div>
                <div className="space-y-1">
                    <label className="text-[10px] uppercase font-bold text-brand-200 ml-2 tracking-wider">To Date</label>
                    <input 
                        type="date" 
                        value={endDate}
                        onChange={(e) => setEndDate(e.target.value)}
                        className="w-full bg-white/10 border border-white/20 rounded-xl py-2.5 px-3 text-white text-sm focus:outline-none focus:bg-white/20 transition-colors" 
                    />
                </div>
            </div>
        )}
      </header>

      <div className="px-5 -mt-6 relative z-20">
        {loading ? (
          <div className="bg-white p-10 rounded-2xl shadow-lg border border-gray-100 flex flex-col items-center justify-center animate-in fade-in duration-500">
             <Loader2 size={36} className="text-brand-500 animate-spin mb-3"/>
             <span className="text-gray-400 text-sm font-medium">Syncing data...</span>
          </div>
        ) : (
          <>
            {/* Chart Card */}
            {viewMode === 'home' && chartData.length > 0 && (
              <div className="bg-white p-5 rounded-2xl shadow-lg shadow-gray-200/50 border border-gray-100 mb-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
                <div className="flex items-center justify-between mb-6">
                   <h3 className="text-xs font-bold text-gray-500 uppercase flex items-center gap-2 tracking-wider">
                     <div className="p-1 bg-brand-50 rounded-md"><TrendingUp size={14} className="text-brand-600" /></div>
                     Trend
                   </h3>
                   <span className="text-[10px] text-brand-600 font-bold bg-brand-50 px-2.5 py-1 rounded-full border border-brand-100">Last 7 Days</span>
                </div>
                <div className="h-32 w-full">
                  <ResponsiveContainer width="100%" height="100%" minWidth={0}>
                    <BarChart data={chartData}>
                      <XAxis dataKey="name" tick={{fontSize: 10, fill: '#9ca3af'}} tickLine={false} axisLine={false} dy={10} />
                      <Tooltip 
                        contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', padding: '8px 12px'}}
                        itemStyle={{color: '#0284c7', fontSize: '13px', fontWeight: 'bold'}}
                        cursor={{fill: '#f0f9ff', radius: 4}}
                      />
                      <Bar dataKey="net" radius={[6, 6, 6, 6]} barSize={24}>
                        {chartData.map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={index === chartData.length -1 ? 'url(#colorNet)' : '#e0f2fe'} />
                        ))}
                      </Bar>
                      <defs>
                        <linearGradient id="colorNet" x1="0" y1="0" x2="0" y2="1">
                          <stop offset="0%" stopColor="#0ea5e9" stopOpacity={1}/>
                          <stop offset="100%" stopColor="#0284c7" stopOpacity={1}/>
                        </linearGradient>
                      </defs>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
            )}

            {/* HOME VIEW: Latest Report Card */}
            {viewMode === 'home' && (
              <div className="animate-in fade-in slide-in-from-bottom-6 duration-700">
                 {mostRecentReport ? (
                   <div 
                      onClick={() => navigate(`/report/${mostRecentReport.reportId}`)}
                      className="bg-white p-6 rounded-2xl border border-gray-100 shadow-xl shadow-brand-900/5 active:scale-[0.98] transition-all cursor-pointer group relative overflow-hidden"
                    >
                      <div className={`absolute top-0 right-0 w-32 h-32 rounded-full -mr-10 -mt-10 blur-2xl transition-colors ${mostRecentReport.isOffDay ? 'bg-gray-100/50' : 'bg-brand-50/50 group-hover:bg-brand-100/50'}`}></div>

                      <div className="relative z-10">
                        <div className="flex justify-between items-start mb-3">
                           <span className="bg-gray-900 text-white text-xs font-bold px-2.5 py-1 rounded-lg flex items-center gap-1.5 shadow-sm">
                              <Calendar size={12}/> {mostRecentReport.dateLocal}
                           </span>
                           <span className="text-gray-400 text-xs font-medium bg-gray-50 px-2 py-1 rounded-md">{mostRecentReport.timeLocal}</span>
                        </div>
                        <h3 className="text-xl font-bold text-gray-900 mb-1 line-clamp-1">{mostRecentReport.storeName}</h3>

                        {mostRecentReport.isOffDay ? (
                            <p className="text-xs text-gray-400 mb-4 flex items-center gap-1">
                               <Coffee size={12} /> Relax & Recharge
                            </p>
                        ) : (
                            <p className="text-xs text-gray-500 mb-4">{mostRecentReport.items.length} items recorded</p>
                        )}

                        <div className="flex items-end justify-between border-t border-gray-50 pt-4">
                           {mostRecentReport.isOffDay ? (
                              <div className="flex items-center gap-2 text-gray-400">
                                 <div className="p-1.5 bg-gray-100 rounded-full"><Coffee size={18} /></div>
                                 <span className="text-lg font-bold text-gray-500">Off Day</span>
                              </div>
                           ) : (
                              <div className="text-3xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-brand-600 to-brand-800">
                                  {formatCurrency(mostRecentReport.totals.net)}
                              </div>
                           )}

                           <div className="h-8 w-8 bg-brand-50 rounded-full flex items-center justify-center text-brand-600 group-hover:bg-brand-600 group-hover:text-white transition-all shadow-sm">
                             <ChevronRight size={18} />
                           </div>
                        </div>
                      </div>
                   </div>
                 ) : (
                    <div className="text-center py-12 bg-white rounded-2xl border border-dashed border-gray-200 shadow-sm">
                       <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-3">
                          <FileText className="text-gray-300" size={24} />
                       </div>
                       <p className="text-gray-500 font-medium">{currentUser ? "No reports in your account." : "No reports on this device."}</p>
                       <p className="text-gray-400 text-sm mt-1">Tap + to start your first report.</p>
                    </div>
                 )}
              </div>
            )}

            {/* HISTORY VIEW: Full List */}
            {viewMode === 'history' && (
              <div className="space-y-3 animate-in fade-in slide-in-from-bottom-8 duration-500 mt-2 pb-4">
                {isSelectionMode && (
                  <div className="text-center text-xs text-brand-700 font-bold bg-brand-50 p-3 rounded-xl mb-4 border border-brand-100 flex justify-center items-center gap-2 animate-in fade-in slide-in-from-top-2">
                    <CheckSquare size={14} className="text-brand-600"/> 
                    {selectedIds.size === 0 ? "Select items to delete" : `${selectedIds.size} selected`}
                  </div>
                )}
                {filteredReports.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-20 text-gray-400 bg-white rounded-2xl border border-dashed border-gray-200 shadow-sm mt-4">
                    <div className="bg-gray-50 p-5 rounded-full mb-4">
                       <FileText size={32} className="text-gray-300" />
                    </div>
                    <p className="text-sm font-medium text-gray-600">
                        {hasFilters ? 'No reports match your filters.' : 'No reports found.'}
                    </p>
                  </div>
                ) : (
                  filteredReports.map((report) => {
                    const isSelected = selectedIds.has(report.reportId);
                    const isOffDay = report.isOffDay;

                    return (
                      <div 
                        key={report.reportId}
                        onTouchStart={() => handleTouchStart(report.reportId)}
                        onTouchEnd={handleTouchEnd}
                        onTouchMove={handleTouchMove}
                        onClick={() => handleCardClick(report.reportId)}
                        className={`bg-white p-4 rounded-2xl border shadow-sm transition-all cursor-pointer flex justify-between items-center group relative overflow-hidden select-none ${
                          isSelectionMode 
                             ? isSelected 
                                ? 'border-brand-500 ring-1 ring-brand-500 bg-brand-50/30' 
                                : 'border-gray-100 opacity-100'
                             : 'border-gray-100 hover:border-brand-200 hover:shadow-md active:scale-[0.98]'
                        }`}
                      >
                        {isSelectionMode && (
                          <div className={`mr-4 w-6 h-6 min-w-[1.5rem] rounded-full border-2 flex items-center justify-center transition-all duration-200 ${isSelected ? 'bg-brand-500 border-brand-500 scale-110' : 'bg-white border-gray-300'}`}>
                            {isSelected && <Check size={14} className="text-white" strokeWidth={3} />}
                          </div>
                        )}

                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 mb-1.5">
                            <div className="flex items-center gap-1.5 bg-gray-50 border border-gray-100 px-2 py-0.5 rounded text-gray-600 shadow-sm">
                                <Calendar size={10} className="text-gray-400" />
                                <span className="text-[10px] font-bold uppercase tracking-wide">{report.dateLocal}</span>
                            </div>
                            <span className="text-[10px] text-gray-400 font-medium">{report.timeLocal}</span>
                          </div>
                          <p className={`text-sm font-bold truncate pr-2 ${isSelected ? 'text-brand-900' : 'text-gray-900'}`}>{report.storeName}</p>
                        </div>
                        <div className="text-right">
                          {isOffDay ? (
                              <span className="text-[10px] font-bold text-gray-400 bg-gray-100 border border-gray-200 px-2 py-1 rounded-md uppercase tracking-wider">Off Day</span>
                          ) : (
                              <span className={`block text-base font-bold ${isSelected ? 'text-brand-700' : 'text-brand-600'}`}>{formatCurrency(report.totals.net)}</span>
                          )}

                          {!isSelectionMode && !isOffDay && (
                            <div className="flex items-center justify-end text-gray-400 text-[10px] mt-1 font-medium uppercase tracking-wide group-hover:text-brand-400 transition-colors">
                              {report.items.length} items <ChevronRight size={10} className="ml-1" />
                            </div>
                          )}
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            )}
          </>
        )}
      </div>

      {/* Floating Bottom Action Bar */}
      <div className="fixed bottom-6 left-1/2 transform -translate-x-1/2 w-[calc(100%-3rem)] max-w-md z-50">

        {isSelectionMode ? (
           <div className="flex gap-3 animate-in slide-in-from-bottom-6 duration-300">
              <button 
                type="button"
                onClick={exitSelectionMode}
                className="flex-1 h-14 bg-white/90 backdrop-blur-md border border-gray-200 text-gray-700 font-bold rounded-2xl shadow-xl flex items-center justify-center gap-2 hover:bg-white active:scale-95 transition-all"
              >
                <X size={20} /> Cancel
              </button>
              <button 
                type="button"
                onClick={deleteSelectedReports}
                disabled={selectedIds.size === 0}
                className="flex-[2] h-14 bg-red-600 text-white font-bold rounded-2xl shadow-xl shadow-red-600/30 flex items-center justify-center gap-2 hover:bg-red-700 active:scale-95 transition-all disabled:opacity-50 disabled:shadow-none"
              >
                <Trash2 size={20} fill="currentColor" className="text-red-600/20" /> 
                <span>Delete ({selectedIds.size})</span>
              </button>
           </div>
        ) : (
          <div className="bg-white/80 backdrop-blur-xl border border-white/40 p-2 rounded-[2rem] shadow-2xl shadow-gray-200/50 flex items-center justify-between pl-3 pr-2 gap-4 ring-1 ring-gray-200/50">
            <div className="flex bg-gray-100/80 p-1 rounded-full relative">
               <div 
                 className={`absolute top-1 bottom-1 w-[calc(50%-4px)] bg-white rounded-full shadow-sm transition-all duration-300 ease-out ${viewMode === 'home' ? 'left-1' : 'left-[calc(50%+2px)]'}`}
               ></div>

               <button 
                  type="button"
                  onClick={() => setViewMode('home')}
                  className={`relative z-10 w-12 h-10 rounded-full flex items-center justify-center transition-colors duration-300 ${viewMode === 'home' ? 'text-brand-600' : 'text-gray-400'}`}
               >
                  <LayoutDashboard size={20} />
               </button>
               <button 
                  type="button"
                  onClick={() => setViewMode('history')}
                  className={`relative z-10 w-12 h-10 rounded-full flex items-center justify-center transition-colors duration-300 ${viewMode === 'history' ? 'text-brand-600' : 'text-gray-400'}`}
               >
                  <History size={20} />
               </button>
            </div>

            <button 
              type="button"
              onClick={() => navigate('/new')}
              className="h-14 px-8 bg-gray-900 text-white rounded-[1.5rem] shadow-lg shadow-gray-900/20 flex items-center justify-center gap-2 hover:bg-black active:scale-95 transition-all group"
            >
              <Plus size={24} className="group-hover:rotate-90 transition-transform duration-300" />
              <span className="font-bold text-sm">New Report</span>
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
    <App />
);

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Plus, Search, ChevronRight, FileText, TrendingUp, Calendar, Filter, RefreshCw, History, LayoutDashboard, Loader2, Trash2, CheckSquare, X, Check, User, UserCircle, Coffee, Settings } from 'lucide-react';
import { DailyReport } from '../types';
import * as StorageService from '../services/storageService';
import * as AuthService from '../services/authService';
import { formatCurrency } from '../utils/calculations';
import { BarChart, Bar, XAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import AuthModal from '../components/AuthModal';
import SettingsModal from '../components/SettingsModal';

type ViewMode = 'home' | 'history';

// Use a module-level variable for the timer to avoid useState async issues and useRef dependencies
let longPressTimer: any = null;

const Dashboard: React.FC = () => {
  const navigate = useNavigate();
  const [reports, setReports] = useState<DailyReport[]>([]);
  const [loading, setLoading] = useState(true);
  const [viewMode, setViewMode] = useState<ViewMode>('home');

  // Auth State
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);

  // Settings State
  const [isSettingsModalOpen, setIsSettingsModalOpen] = useState(false);

  // Selection Mode State
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Filter states
  const [searchTerm, setSearchTerm] = useState('');
  const [showFilters, setShowFilters] = useState(false);
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  // Long Press State
  const [isLongPress, setIsLongPress] = useState(false);

  const initData = async () => {
    setLoading(true);
    // 1. Check Auth
    const user = await AuthService.getCurrentUser();
    setCurrentUser(user);

    // 2. Load Reports (storageService now handles isolation based on auth state)
    const data = await StorageService.loadReports();
    setReports(data);
    setLoading(false);
  };

  useEffect(() => {
    initData();
  }, []);

  const handleAuthSuccess = async () => {
    // Reload everything after auth state change
    await initData();
  };

  // --- Selection Logic ---

  const enterSelectionMode = (initialId?: string) => {
    setIsSelectionMode(true);
    if (initialId) {
      setSelectedIds(new Set([initialId]));
    }
  };

  const exitSelectionMode = () => {
    setIsSelectionMode(false);
    setSelectedIds(new Set());
  };

  const toggleReportSelection = (id: string) => {
    const newSelected = new Set(selectedIds);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedIds(newSelected);
  };

  const deleteSelectedReports = async (e: React.MouseEvent) => {
    e.preventDefault(); 
    if (selectedIds.size === 0) return;

    setLoading(true);
    try {
      await StorageService.deleteReports(Array.from(selectedIds));
      const data = await StorageService.loadReports();
      setReports(data);
      exitSelectionMode();
    } catch (e) {
      alert("Failed to delete selected reports.");
    } finally {
      setLoading(false);
    }
  };

  // --- Long Press Handlers ---
  const handleTouchStart = (id: string) => {
    if (isSelectionMode) return;

    // Reset state
    setIsLongPress(false);

    // Clear any existing timer just in case
    if (longPressTimer) clearTimeout(longPressTimer);

    longPressTimer = setTimeout(() => {
      setIsLongPress(true);
      enterSelectionMode(id);
      if (navigator.vibrate) navigator.vibrate(50);
    }, 600);
  };

  const handleTouchEnd = () => {
    if (longPressTimer) {
      clearTimeout(longPressTimer);
      longPressTimer = null;
    }
  };

  const handleTouchMove = () => {
    if (longPressTimer) {
      clearTimeout(longPressTimer);
      longPressTimer = null;
    }
  };

  const handleCardClick = (id: string) => {
    // If long press was detected (and triggered selection mode), we prevent standard click logic
    // However, if we are ALREADY in selection mode, long press logic is bypassed above, 
    // so we just toggle.
    // The only edge case is the split second where long press triggered but user also lifts finger
    // triggering onClick.

    if (isLongPress) {
      setIsLongPress(false); // Reset for next time
      return;
    }

    if (isSelectionMode) {
      toggleReportSelection(id);
    } else {
      navigate(`/report/${id}`);
    }
  };

  // --- Filtering ---

  const filteredReports = reports.filter(r => {
    const matchesSearch = !searchTerm || r.storeName.toLowerCase().includes(searchTerm.toLowerCase());
    const reportDate = r.dateLocal;
    const matchesStart = !startDate || reportDate >= startDate;
    const matchesEnd = !endDate || reportDate <= endDate;
    return matchesSearch && matchesStart && matchesEnd;
  }).sort((a, b) => b.dateLocal.localeCompare(a.dateLocal) || b.createdAt - a.createdAt);

  const mostRecentReport = [...reports].sort((a, b) => b.createdAt - a.createdAt)[0];

  // Exclude off days from the chart data to avoid dipping the graph incorrectly (or include as 0 if desired)
  const sortedForChart = [...reports].sort((a, b) => a.dateLocal.localeCompare(b.dateLocal));
  const chartData = sortedForChart.slice(-7).map(r => ({
    name: r.dateLocal.slice(5),
    net: r.isOffDay ? 0 : r.totals.net
  }));

  const resetFilters = () => {
    setSearchTerm('');
    setStartDate('');
    setEndDate('');
    setShowFilters(false);
  };

  const hasFilters = searchTerm || startDate || endDate;

  return (
    <div className="min-h-screen bg-gray-50/50 pb-32 font-sans">
      <AuthModal 
        isOpen={isAuthModalOpen} 
        onClose={() => setIsAuthModalOpen(false)} 
        user={currentUser}
        onAuthSuccess={handleAuthSuccess}
      />

      <SettingsModal
        isOpen={isSettingsModalOpen}
        onClose={() => setIsSettingsModalOpen(false)}
        onSave={() => { /* Config is saved inside modal, maybe trigger refresh if needed */ }}
      />

      {/* Header Area */}
      <header className={`bg-gradient-to-br from-brand-700 via-brand-600 to-brand-800 text-white px-6 pt-12 pb-8 rounded-b-[2.5rem] shadow-xl transition-all duration-300 relative overflow-hidden ${viewMode === 'history' ? 'pb-8' : ''}`}>
        <div className="absolute top-0 left-0 w-full h-full overflow-hidden opacity-10 pointer-events-none">
           <div className="absolute -top-10 -right-10 w-40 h-40 bg-white rounded-full blur-3xl"></div>
           <div className="absolute bottom-0 left-0 w-60 h-60 bg-brand-300 rounded-full blur-3xl"></div>
        </div>

        <div className="relative z-10 flex justify-between items-start">
            <div>
                <h1 className="text-3xl font-extrabold mb-1 tracking-tight">
                  {viewMode === 'home' ? 'Daily Sales' : 'History'}
                </h1>
                <p className="text-brand-100 text-sm font-medium opacity-90">
                  {viewMode === 'home' ? 'Overview & Insights' : 'Archive & Search'}
                </p>
            </div>

            {/* Action Buttons Top Right */}
            <div className="flex gap-2">
              {/* Settings Button */}
               <button 
                onClick={() => setIsSettingsModalOpen(true)}
                className="p-2 rounded-full transition-all active:scale-95 shadow-sm border bg-white/20 backdrop-blur-md border-white/30 text-white hover:bg-white/30"
                title="Settings"
              >
                 <Settings size={22} />
              </button>

              {/* User / Auth Button */}
              <button 
                onClick={() => setIsAuthModalOpen(true)}
                className={`p-2 rounded-full transition-all active:scale-95 shadow-sm border ${currentUser ? 'bg-brand-500 border-brand-400 text-white' : 'bg-white/20 backdrop-blur-md border-white/30 text-white hover:bg-white/30'}`}
                title={currentUser ? "Account" : "Sign In"}
              >
                 {currentUser ? <UserCircle size={24} /> : <User size={22} />}
              </button>

              {viewMode === 'history' && (
                <button 
                  type="button"
                  onClick={() => isSelectionMode ? exitSelectionMode() : enterSelectionMode()} 
                  className={`text-xs px-4 py-2 rounded-full flex items-center gap-1.5 transition-all font-bold shadow-sm active:scale-95 ${isSelectionMode ? 'bg-white text-brand-700 shadow-md' : 'bg-white/20 backdrop-blur-md text-white hover:bg-white/30'}`}
                >
                  <CheckSquare size={14} strokeWidth={2.5} /> {isSelectionMode ? 'Done' : 'Select'}
                </button>
              )}
            </div>
        </div>

        {/* Search Bar - Only in History Mode */}
        {viewMode === 'history' && !isSelectionMode && (
          <div className="mt-8 flex gap-3 animate-in fade-in slide-in-from-top-4 duration-500">
            <div className="relative flex-1 group">
              <input 
                type="text" 
                placeholder="Search store name..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-white/10 border border-white/20 backdrop-blur-md rounded-2xl py-3.5 pl-11 pr-4 text-white placeholder-brand-200 focus:outline-none focus:bg-white/20 focus:border-white/40 transition-all text-sm shadow-inner group-hover:bg-white/15"
              />
              <Search className="absolute left-4 top-3.5 text-brand-200 group-hover:text-white transition-colors" size={18} />
            </div>
            <button 
              type="button"
              onClick={() => setShowFilters(!showFilters)}
              className={`p-3.5 rounded-2xl border transition-all active:scale-95 ${showFilters ? 'bg-white text-brand-600 border-white shadow-lg' : 'bg-white/10 text-white border-white/20 hover:bg-white/20'}`}
            >
              <Filter size={20} />
            </button>
            {hasFilters && (
                <button type="button" onClick={resetFilters} className="p-3.5 bg-brand-800 hover:bg-brand-900 rounded-2xl flex items-center justify-center transition-colors shadow-sm active:scale-95">
                    <RefreshCw size={20} className="text-white"/>
                </button>
            )}
          </div>
        )}

        {/* Filters Panel */}
        {viewMode === 'history' && showFilters && !isSelectionMode && (
            <div className="mt-4 grid grid-cols-2 gap-3 animate-in fade-in slide-in-from-top-2">
                <div className="space-y-1">
                    <label className="text-[10px] uppercase font-bold text-brand-200 ml-2 tracking-wider">From Date</label>
                    <input 
                        type="date" 
                        value={startDate}
                        onChange={(e) => setStartDate(e.target.value)}
                        className="w-full bg-white/10 border border-white/20 rounded-xl py-2.5 px-3 text-white text-sm focus:outline-none focus:bg-white/20 transition-colors" 
                    />
                </div>
                <div className="space-y-1">
                    <label className="text-[10px] uppercase font-bold text-brand-200 ml-2 tracking-wider">To Date</label>
                    <input 
                        type="date" 
                        value={endDate}
                        onChange={(e) => setEndDate(e.target.value)}
                        className="w-full bg-white/10 border border-white/20 rounded-xl py-2.5 px-3 text-white text-sm focus:outline-none focus:bg-white/20 transition-colors" 
                    />
                </div>
            </div>
        )}
      </header>

      <div className="px-5 -mt-6 relative z-20">
        {loading ? (
          <div className="bg-white p-10 rounded-2xl shadow-lg border border-gray-100 flex flex-col items-center justify-center animate-in fade-in duration-500">
             <Loader2 size={36} className="text-brand-500 animate-spin mb-3"/>
             <span className="text-gray-400 text-sm font-medium">Syncing data...</span>
          </div>
        ) : (
          <>
            {/* Chart Card */}
            {viewMode === 'home' && chartData.length > 0 && (
              <div className="bg-white p-5 rounded-2xl shadow-lg shadow-gray-200/50 border border-gray-100 mb-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
                <div className="flex items-center justify-between mb-6">
                   <h3 className="text-xs font-bold text-gray-500 uppercase flex items-center gap-2 tracking-wider">
                     <div className="p-1 bg-brand-50 rounded-md"><TrendingUp size={14} className="text-brand-600" /></div>
                     Trend
                   </h3>
                   <span className="text-[10px] text-brand-600 font-bold bg-brand-50 px-2.5 py-1 rounded-full border border-brand-100">Last 7 Days</span>
                </div>
                <div className="h-32 w-full">
                  <ResponsiveContainer width="100%" height="100%" minWidth={0}>
                    <BarChart data={chartData}>
                      <XAxis dataKey="name" tick={{fontSize: 10, fill: '#9ca3af'}} tickLine={false} axisLine={false} dy={10} />
                      <Tooltip 
                        contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', padding: '8px 12px'}}
                        itemStyle={{color: '#0284c7', fontSize: '13px', fontWeight: 'bold'}}
                        cursor={{fill: '#f0f9ff', radius: 4}}
                      />
                      <Bar dataKey="net" radius={[6, 6, 6, 6]} barSize={24}>
                        {chartData.map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={index === chartData.length -1 ? 'url(#colorNet)' : '#e0f2fe'} />
                        ))}
                      </Bar>
                      <defs>
                        <linearGradient id="colorNet" x1="0" y1="0" x2="0" y2="1">
                          <stop offset="0%" stopColor="#0ea5e9" stopOpacity={1}/>
                          <stop offset="100%" stopColor="#0284c7" stopOpacity={1}/>
                        </linearGradient>
                      </defs>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
            )}

            {/* HOME VIEW: Latest Report Card */}
            {viewMode === 'home' && (
              <div className="animate-in fade-in slide-in-from-bottom-6 duration-700">
                 {mostRecentReport ? (
                   <div 
                      onClick={() => navigate(`/report/${mostRecentReport.reportId}`)}
                      className="bg-white p-6 rounded-2xl border border-gray-100 shadow-xl shadow-brand-900/5 active:scale-[0.98] transition-all cursor-pointer group relative overflow-hidden"
                    >
                      <div className={`absolute top-0 right-0 w-32 h-32 rounded-full -mr-10 -mt-10 blur-2xl transition-colors ${mostRecentReport.isOffDay ? 'bg-gray-100/50' : 'bg-brand-50/50 group-hover:bg-brand-100/50'}`}></div>

                      <div className="relative z-10">
                        <div className="flex justify-between items-start mb-3">
                           <span className="bg-gray-900 text-white text-xs font-bold px-2.5 py-1 rounded-lg flex items-center gap-1.5 shadow-sm">
                              <Calendar size={12}/> {mostRecentReport.dateLocal}
                           </span>
                           <span className="text-gray-400 text-xs font-medium bg-gray-50 px-2 py-1 rounded-md">{mostRecentReport.timeLocal}</span>
                        </div>
                        <h3 className="text-xl font-bold text-gray-900 mb-1 line-clamp-1">{mostRecentReport.storeName}</h3>

                        {mostRecentReport.isOffDay ? (
                            <p className="text-xs text-gray-400 mb-4 flex items-center gap-1">
                               <Coffee size={12} /> Relax & Recharge
                            </p>
                        ) : (
                            <p className="text-xs text-gray-500 mb-4">{mostRecentReport.items.length} items recorded</p>
                        )}

                        <div className="flex items-end justify-between border-t border-gray-50 pt-4">
                           {mostRecentReport.isOffDay ? (
                              <div className="flex items-center gap-2 text-gray-400">
                                 <div className="p-1.5 bg-gray-100 rounded-full"><Coffee size={18} /></div>
                                 <span className="text-lg font-bold text-gray-500">Off Day</span>
                              </div>
                           ) : (
                              <div className="text-3xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-brand-600 to-brand-800">
                                  {formatCurrency(mostRecentReport.totals.net)}
                              </div>
                           )}

                           <div className="h-8 w-8 bg-brand-50 rounded-full flex items-center justify-center text-brand-600 group-hover:bg-brand-600 group-hover:text-white transition-all shadow-sm">
                             <ChevronRight size={18} />
                           </div>
                        </div>
                      </div>
                   </div>
                 ) : (
                    <div className="text-center py-12 bg-white rounded-2xl border border-dashed border-gray-200 shadow-sm">
                       <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-3">
                          <FileText className="text-gray-300" size={24} />
                       </div>
                       <p className="text-gray-500 font-medium">{currentUser ? "No reports in your account." : "No reports on this device."}</p>
                       <p className="text-gray-400 text-sm mt-1">Tap + to start your first report.</p>
                    </div>
                 )}
              </div>
            )}

            {/* HISTORY VIEW: Full List */}
            {viewMode === 'history' && (
              <div className="space-y-3 animate-in fade-in slide-in-from-bottom-8 duration-500 mt-2 pb-4">
                {isSelectionMode && (
                  <div className="text-center text-xs text-brand-700 font-bold bg-brand-50 p-3 rounded-xl mb-4 border border-brand-100 flex justify-center items-center gap-2 animate-in fade-in slide-in-from-top-2">
                    <CheckSquare size={14} className="text-brand-600"/> 
                    {selectedIds.size === 0 ? "Select items to delete" : `${selectedIds.size} selected`}
                  </div>
                )}
                {filteredReports.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-20 text-gray-400 bg-white rounded-2xl border border-dashed border-gray-200 shadow-sm mt-4">
                    <div className="bg-gray-50 p-5 rounded-full mb-4">
                       <FileText size={32} className="text-gray-300" />
                    </div>
                    <p className="text-sm font-medium text-gray-600">
                        {hasFilters ? 'No reports match your filters.' : 'No reports found.'}
                    </p>
                  </div>
                ) : (
                  filteredReports.map((report) => {
                    const isSelected = selectedIds.has(report.reportId);
                    const isOffDay = report.isOffDay;

                    return (
                      <div 
                        key={report.reportId}
                        onTouchStart={() => handleTouchStart(report.reportId)}
                        onTouchEnd={handleTouchEnd}
                        onTouchMove={handleTouchMove}
                        onClick={() => handleCardClick(report.reportId)}
                        className={`bg-white p-4 rounded-2xl border shadow-sm transition-all cursor-pointer flex justify-between items-center group relative overflow-hidden select-none ${
                          isSelectionMode 
                             ? isSelected 
                                ? 'border-brand-500 ring-1 ring-brand-500 bg-brand-50/30' 
                                : 'border-gray-100 opacity-100'
                             : 'border-gray-100 hover:border-brand-200 hover:shadow-md active:scale-[0.98]'
                        }`}
                      >
                        {isSelectionMode && (
                          <div className={`mr-4 w-6 h-6 min-w-[1.5rem] rounded-full border-2 flex items-center justify-center transition-all duration-200 ${isSelected ? 'bg-brand-500 border-brand-500 scale-110' : 'bg-white border-gray-300'}`}>
                            {isSelected && <Check size={14} className="text-white" strokeWidth={3} />}
                          </div>
                        )}

                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 mb-1.5">
                            <div className="flex items-center gap-1.5 bg-gray-50 border border-gray-100 px-2 py-0.5 rounded text-gray-600 shadow-sm">
                                <Calendar size={10} className="text-gray-400" />
                                <span className="text-[10px] font-bold uppercase tracking-wide">{report.dateLocal}</span>
                            </div>
                            <span className="text-[10px] text-gray-400 font-medium">{report.timeLocal}</span>
                          </div>
                          <p className={`text-sm font-bold truncate pr-2 ${isSelected ? 'text-brand-900' : 'text-gray-900'}`}>{report.storeName}</p>
                        </div>
                        <div className="text-right">
                          {isOffDay ? (
                              <span className="text-[10px] font-bold text-gray-400 bg-gray-100 border border-gray-200 px-2 py-1 rounded-md uppercase tracking-wider">Off Day</span>
                          ) : (
                              <span className={`block text-base font-bold ${isSelected ? 'text-brand-700' : 'text-brand-600'}`}>{formatCurrency(report.totals.net)}</span>
                          )}

                          {!isSelectionMode && !isOffDay && (
                            <div className="flex items-center justify-end text-gray-400 text-[10px] mt-1 font-medium uppercase tracking-wide group-hover:text-brand-400 transition-colors">
                              {report.items.length} items <ChevronRight size={10} className="ml-1" />
                            </div>
                          )}
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            )}
          </>
        )}
      </div>

      {/* Floating Bottom Action Bar */}
      <div className="fixed bottom-6 left-1/2 transform -translate-x-1/2 w-[calc(100%-3rem)] max-w-md z-50">

        {isSelectionMode ? (
           <div className="flex gap-3 animate-in slide-in-from-bottom-6 duration-300">
              <button 
                type="button"
                onClick={exitSelectionMode}
                className="flex-1 h-14 bg-white/90 backdrop-blur-md border border-gray-200 text-gray-700 font-bold rounded-2xl shadow-xl flex items-center justify-center gap-2 hover:bg-white active:scale-95 transition-all"
              >
                <X size={20} /> Cancel
              </button>
              <button 
                type="button"
                onClick={deleteSelectedReports}
                disabled={selectedIds.size === 0}
                className="flex-[2] h-14 bg-red-600 text-white font-bold rounded-2xl shadow-xl shadow-red-600/30 flex items-center justify-center gap-2 hover:bg-red-700 active:scale-95 transition-all disabled:opacity-50 disabled:shadow-none"
              >
                <Trash2 size={20} fill="currentColor" className="text-red-600/20" /> 
                <span>Delete ({selectedIds.size})</span>
              </button>
           </div>
        ) : (
          <div className="bg-white/80 backdrop-blur-xl border border-white/40 p-2 rounded-[2rem] shadow-2xl shadow-gray-200/50 flex items-center justify-between pl-3 pr-2 gap-4 ring-1 ring-gray-200/50">
            <div className="flex bg-gray-100/80 p-1 rounded-full relative">
               <div 
                 className={`absolute top-1 bottom-1 w-[calc(50%-4px)] bg-white rounded-full shadow-sm transition-all duration-300 ease-out ${viewMode === 'home' ? 'left-1' : 'left-[calc(50%+2px)]'}`}
               ></div>

               <button 
                  type="button"
                  onClick={() => setViewMode('home')}
                  className={`relative z-10 w-12 h-10 rounded-full flex items-center justify-center transition-colors duration-300 ${viewMode === 'home' ? 'text-brand-600' : 'text-gray-400'}`}
               >
                  <LayoutDashboard size={20} />
               </button>
               <button 
                  type="button"
                  onClick={() => setViewMode('history')}
                  className={`relative z-10 w-12 h-10 rounded-full flex items-center justify-center transition-colors duration-300 ${viewMode === 'history' ? 'text-brand-600' : 'text-gray-400'}`}
               >
                  <History size={20} />
               </button>
            </div>

            <button 
              type="button"
              onClick={() => navigate('/new')}
              className="h-14 px-8 bg-gray-900 text-white rounded-[1.5rem] shadow-lg shadow-gray-900/20 flex items-center justify-center gap-2 hover:bg-black active:scale-95 transition-all group"
            >
              <Plus size={24} className="group-hover:rotate-90 transition-transform duration-300" />
              <span className="font-bold text-sm">New Report</span>
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
    <App />
);

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Plus, Search, ChevronRight, FileText, TrendingUp, Calendar, Filter, RefreshCw, History, LayoutDashboard, Loader2, Trash2, CheckSquare, X, Check, User, UserCircle } from 'lucide-react';
import { DailyReport } from '../types';
import * as StorageService from '../services/storageService';
import * as AuthService from '../services/authService';
import { formatCurrency } from '../utils/calculations';
import { BarChart, Bar, XAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import AuthModal from '../components/AuthModal';

type ViewMode = 'home' | 'history';

// Module-level variables to handle touch interactions safely without Hooks
let longPressTimer: any = null;
let isLongPressEvent = false;

const Dashboard: React.FC = () => {
  const navigate = useNavigate();
  const [reports, setReports] = useState<DailyReport[]>([]);
  const [loading, setLoading] = useState(true);
  const [viewMode, setViewMode] = useState<ViewMode>('home');

  // Auth State
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);

  // Selection Mode State
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Filter states
  const [searchTerm, setSearchTerm] = useState('');
  const [showFilters, setShowFilters] = useState(false);
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const initData = async () => {
    setLoading(true);
    // 1. Check Auth
    const user = await AuthService.getCurrentUser();
    setCurrentUser(user);

    // 2. Load Reports (storageService now handles isolation based on auth state)
    const data = await StorageService.loadReports();
    setReports(data);
    setLoading(false);
  };

  useEffect(() => {
    initData();
  }, []);

  const handleAuthSuccess = async () => {
    // Reload everything after auth state change
    await initData();
  };

  // --- Selection Logic ---

  const enterSelectionMode = (initialId?: string) => {
    setIsSelectionMode(true);
    if (initialId) {
      setSelectedIds(new Set([initialId]));
    }
  };

  const exitSelectionMode = () => {
    setIsSelectionMode(false);
    setSelectedIds(new Set());
  };

  const toggleReportSelection = (id: string) => {
    const newSelected = new Set(selectedIds);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedIds(newSelected);
  };

  const deleteSelectedReports = async (e: React.MouseEvent) => {
    e.preventDefault(); 
    if (selectedIds.size === 0) return;

    setLoading(true);
    try {
      await StorageService.deleteReports(Array.from(selectedIds));
      const data = await StorageService.loadReports();
      setReports(data);
      exitSelectionMode();
    } catch (e) {
      alert("Failed to delete selected reports.");
    } finally {
      setLoading(false);
    }
  };

  // --- Long Press Handlers ---
  const handleTouchStart = (id: string) => {
    if (isSelectionMode) return;

    // Reset flags
    isLongPressEvent = false;
    if (longPressTimer) clearTimeout(longPressTimer);

    longPressTimer = setTimeout(() => {
      isLongPressEvent = true;
      enterSelectionMode(id);
      if (navigator.vibrate) navigator.vibrate(50);
    }, 600);
  };

  const handleTouchEnd = () => {
    if (longPressTimer) {
      clearTimeout(longPressTimer);
      longPressTimer = null;
    }
  };

  const handleTouchMove = () => {
    if (longPressTimer) {
      clearTimeout(longPressTimer);
      longPressTimer = null;
    }
  };

  const handleCardClick = (id: string) => {
    // If we just triggered a long press, consume this click event
    if (isLongPressEvent) {
      isLongPressEvent = false;
      return;
    }

    if (isSelectionMode) {
      toggleReportSelection(id);
    } else {
      navigate(`/report/${id}`);
    }
  };

  // --- Filtering ---

  const filteredReports = reports.filter(r => {
    const matchesSearch = !searchTerm || r.storeName.toLowerCase().includes(searchTerm.toLowerCase());
    const reportDate = r.dateLocal;
    const matchesStart = !startDate || reportDate >= startDate;
    const matchesEnd = !endDate || reportDate <= endDate;
    return matchesSearch && matchesStart && matchesEnd;
  }).sort((a, b) => b.dateLocal.localeCompare(a.dateLocal) || b.createdAt - a.createdAt);

  const mostRecentReport = [...reports].sort((a, b) => b.createdAt - a.createdAt)[0];
  const sortedForChart = [...reports].sort((a, b) => a.dateLocal.localeCompare(b.dateLocal));
  const chartData = sortedForChart.slice(-7).map(r => ({
    name: r.dateLocal.slice(5),
    net: r.totals.net
  }));

  const resetFilters = () => {
    setSearchTerm('');
    setStartDate('');
    setEndDate('');
    setShowFilters(false);
  };

  const hasFilters = searchTerm || startDate || endDate;

  return (
    <div className="min-h-screen bg-gray-50/50 pb-32 font-sans">
      <AuthModal 
        isOpen={isAuthModalOpen} 
        onClose={() => setIsAuthModalOpen(false)} 
        user={currentUser}
        onAuthSuccess={handleAuthSuccess}
      />

      {/* Header Area */}
      <header className={`bg-gradient-to-br from-brand-700 via-brand-600 to-brand-800 text-white px-6 pt-12 pb-8 rounded-b-[2.5rem] shadow-xl transition-all duration-300 relative overflow-hidden ${viewMode === 'history' ? 'pb-8' : ''}`}>
        <div className="absolute top-0 left-0 w-full h-full overflow-hidden opacity-10 pointer-events-none">
           <div className="absolute -top-10 -right-10 w-40 h-40 bg-white rounded-full blur-3xl"></div>
           <div className="absolute bottom-0 left-0 w-60 h-60 bg-brand-300 rounded-full blur-3xl"></div>
        </div>

        <div className="relative z-10 flex justify-between items-start">
            <div>
                <h1 className="text-3xl font-extrabold mb-1 tracking-tight">
                  {viewMode === 'home' ? 'Daily Sales' : 'History'}
                </h1>
                <p className="text-brand-100 text-sm font-medium opacity-90">
                  {viewMode === 'home' ? 'Overview & Insights' : 'Archive & Search'}
                </p>
            </div>

            {/* Action Buttons Top Right */}
            <div className="flex gap-2">
              {/* User / Auth Button */}
              <button 
                onClick={() => setIsAuthModalOpen(true)}
                className={`p-2 rounded-full transition-all active:scale-95 shadow-sm border ${currentUser ? 'bg-brand-500 border-brand-400 text-white' : 'bg-white/20 backdrop-blur-md border-white/30 text-white hover:bg-white/30'}`}
                title={currentUser ? "Account" : "Sign In"}
              >
                 {currentUser ? <UserCircle size={24} /> : <User size={22} />}
              </button>

              {viewMode === 'history' && (
                <button 
                  type="button"
                  onClick={() => isSelectionMode ? exitSelectionMode() : enterSelectionMode()} 
                  className={`text-xs px-4 py-2 rounded-full flex items-center gap-1.5 transition-all font-bold shadow-sm active:scale-95 ${isSelectionMode ? 'bg-white text-brand-700 shadow-md' : 'bg-white/20 backdrop-blur-md text-white hover:bg-white/30'}`}
                >
                  <CheckSquare size={14} strokeWidth={2.5} /> {isSelectionMode ? 'Done' : 'Select'}
                </button>
              )}
            </div>
        </div>

        {/* Search Bar - Only in History Mode */}
        {viewMode === 'history' && !isSelectionMode && (
          <div className="mt-8 flex gap-3 animate-in fade-in slide-in-from-top-4 duration-500">
            <div className="relative flex-1 group">
              <input 
                type="text" 
                placeholder="Search store name..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-white/10 border border-white/20 backdrop-blur-md rounded-2xl py-3.5 pl-11 pr-4 text-white placeholder-brand-200 focus:outline-none focus:bg-white/20 focus:border-white/40 transition-all text-sm shadow-inner group-hover:bg-white/15"
              />
              <Search className="absolute left-4 top-3.5 text-brand-200 group-hover:text-white transition-colors" size={18} />
            </div>
            <button 
              type="button"
              onClick={() => setShowFilters(!showFilters)}
              className={`p-3.5 rounded-2xl border transition-all active:scale-95 ${showFilters ? 'bg-white text-brand-600 border-white shadow-lg' : 'bg-white/10 text-white border-white/20 hover:bg-white/20'}`}
            >
              <Filter size={20} />
            </button>
            {hasFilters && (
                <button type="button" onClick={resetFilters} className="p-3.5 bg-brand-800 hover:bg-brand-900 rounded-2xl flex items-center justify-center transition-colors shadow-sm active:scale-95">
                    <RefreshCw size={20} className="text-white"/>
                </button>
            )}
          </div>
        )}

        {/* Filters Panel */}
        {viewMode === 'history' && showFilters && !isSelectionMode && (
            <div className="mt-4 grid grid-cols-2 gap-3 animate-in fade-in slide-in-from-top-2">
                <div className="space-y-1">
                    <label className="text-[10px] uppercase font-bold text-brand-200 ml-2 tracking-wider">From Date</label>
                    <input 
                        type="date" 
                        value={startDate}
                        onChange={(e) => setStartDate(e.target.value)}
                        className="w-full bg-white/10 border border-white/20 rounded-xl py-2.5 px-3 text-white text-sm focus:outline-none focus:bg-white/20 transition-colors" 
                    />
                </div>
                <div className="space-y-1">
                    <label className="text-[10px] uppercase font-bold text-brand-200 ml-2 tracking-wider">To Date</label>
                    <input 
                        type="date" 
                        value={endDate}
                        onChange={(e) => setEndDate(e.target.value)}
                        className="w-full bg-white/10 border border-white/20 rounded-xl py-2.5 px-3 text-white text-sm focus:outline-none focus:bg-white/20 transition-colors" 
                    />
                </div>
            </div>
        )}
      </header>

      <div className="px-5 -mt-6 relative z-20">
        {loading ? (
          <div className="bg-white p-10 rounded-2xl shadow-lg border border-gray-100 flex flex-col items-center justify-center animate-in fade-in duration-500">
             <Loader2 size={36} className="text-brand-500 animate-spin mb-3"/>
             <span className="text-gray-400 text-sm font-medium">Syncing data...</span>
          </div>
        ) : (
          <>
            {/* Chart Card */}
            {viewMode === 'home' && chartData.length > 0 && (
              <div className="bg-white p-5 rounded-2xl shadow-lg shadow-gray-200/50 border border-gray-100 mb-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
                <div className="flex items-center justify-between mb-6">
                   <h3 className="text-xs font-bold text-gray-500 uppercase flex items-center gap-2 tracking-wider">
                     <div className="p-1 bg-brand-50 rounded-md"><TrendingUp size={14} className="text-brand-600" /></div>
                     Trend
                   </h3>
                   <span className="text-[10px] text-brand-600 font-bold bg-brand-50 px-2.5 py-1 rounded-full border border-brand-100">Last 7 Days</span>
                </div>
                <div className="h-32 w-full">
                  <ResponsiveContainer width="100%" height="100%" minWidth={0}>
                    <BarChart data={chartData}>
                      <XAxis dataKey="name" tick={{fontSize: 10, fill: '#9ca3af'}} tickLine={false} axisLine={false} dy={10} />
                      <Tooltip 
                        contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', padding: '8px 12px'}}
                        itemStyle={{color: '#0284c7', fontSize: '13px', fontWeight: 'bold'}}
                        cursor={{fill: '#f0f9ff', radius: 4}}
                      />
                      <Bar dataKey="net" radius={[6, 6, 6, 6]} barSize={24}>
                        {chartData.map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={index === chartData.length -1 ? 'url(#colorNet)' : '#e0f2fe'} />
                        ))}
                      </Bar>
                      <defs>
                        <linearGradient id="colorNet" x1="0" y1="0" x2="0" y2="1">
                          <stop offset="0%" stopColor="#0ea5e9" stopOpacity={1}/>
                          <stop offset="100%" stopColor="#0284c7" stopOpacity={1}/>
                        </linearGradient>
                      </defs>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
            )}

            {/* HOME VIEW: Latest Report Card */}
            {viewMode === 'home' && (
              <div className="animate-in fade-in slide-in-from-bottom-6 duration-700">
                 {mostRecentReport ? (
                   <div 
                      onClick={() => navigate(`/report/${mostRecentReport.reportId}`)}
                      className="bg-white p-6 rounded-2xl border border-gray-100 shadow-xl shadow-brand-900/5 active:scale-[0.98] transition-all cursor-pointer group relative overflow-hidden"
                    >
                      <div className="absolute top-0 right-0 w-32 h-32 bg-brand-50/50 rounded-full -mr-10 -mt-10 blur-2xl group-hover:bg-brand-100/50 transition-colors"></div>

                      <div className="relative z-10">
                        <div className="flex justify-between items-start mb-3">
                           <span className="bg-gray-900 text-white text-xs font-bold px-2.5 py-1 rounded-lg flex items-center gap-1.5 shadow-sm">
                              <Calendar size={12}/> {mostRecentReport.dateLocal}
                           </span>
                           <span className="text-gray-400 text-xs font-medium bg-gray-50 px-2 py-1 rounded-md">{mostRecentReport.timeLocal}</span>
                        </div>
                        <h3 className="text-xl font-bold text-gray-900 mb-1 line-clamp-1">{mostRecentReport.storeName}</h3>
                        <p className="text-xs text-gray-500 mb-4">{mostRecentReport.items.length} items recorded</p>

                        <div className="flex items-end justify-between border-t border-gray-50 pt-4">
                           <div className="text-3xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-brand-600 to-brand-800">
                              {formatCurrency(mostRecentReport.totals.net)}
                           </div>
                           <div className="h-8 w-8 bg-brand-50 rounded-full flex items-center justify-center text-brand-600 group-hover:bg-brand-600 group-hover:text-white transition-all shadow-sm">
                             <ChevronRight size={18} />
                           </div>
                        </div>
                      </div>
                   </div>
                 ) : (
                    <div className="text-center py-12 bg-white rounded-2xl border border-dashed border-gray-200 shadow-sm">
                       <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-3">
                          <FileText className="text-gray-300" size={24} />
                       </div>
                       <p className="text-gray-500 font-medium">{currentUser ? "No reports in your account." : "No reports on this device."}</p>
                       <p className="text-gray-400 text-sm mt-1">Tap + to start your first report.</p>
                    </div>
                 )}
              </div>
            )}

            {/* HISTORY VIEW: Full List */}
            {viewMode === 'history' && (
              <div className="space-y-3 animate-in fade-in slide-in-from-bottom-8 duration-500 mt-2 pb-4">
                {isSelectionMode && (
                  <div className="text-center text-xs text-brand-700 font-bold bg-brand-50 p-3 rounded-xl mb-4 border border-brand-100 flex justify-center items-center gap-2 animate-in fade-in slide-in-from-top-2">
                    <CheckSquare size={14} className="text-brand-600"/> 
                    {selectedIds.size === 0 ? "Select items to delete" : `${selectedIds.size} selected`}
                  </div>
                )}
                {filteredReports.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-20 text-gray-400 bg-white rounded-2xl border border-dashed border-gray-200 shadow-sm mt-4">
                    <div className="bg-gray-50 p-5 rounded-full mb-4">
                       <FileText size={32} className="text-gray-300" />
                    </div>
                    <p className="text-sm font-medium text-gray-600">
                        {hasFilters ? 'No reports match your filters.' : 'No reports found.'}
                    </p>
                  </div>
                ) : (
                  filteredReports.map((report) => {
                    const isSelected = selectedIds.has(report.reportId);
                    return (
                      <div 
                        key={report.reportId}
                        onTouchStart={() => handleTouchStart(report.reportId)}
                        onTouchEnd={handleTouchEnd}
                        onTouchMove={handleTouchMove}
                        onClick={() => handleCardClick(report.reportId)}
                        className={`bg-white p-4 rounded-2xl border shadow-sm transition-all cursor-pointer flex justify-between items-center group relative overflow-hidden select-none ${
                          isSelectionMode 
                             ? isSelected 
                                ? 'border-brand-500 ring-1 ring-brand-500 bg-brand-50/30' 
                                : 'border-gray-100 opacity-100'
                             : 'border-gray-100 hover:border-brand-200 hover:shadow-md active:scale-[0.98]'
                        }`}
                      >
                        {isSelectionMode && (
                          <div className={`mr-4 w-6 h-6 min-w-[1.5rem] rounded-full border-2 flex items-center justify-center transition-all duration-200 ${isSelected ? 'bg-brand-500 border-brand-500 scale-110' : 'bg-white border-gray-300'}`}>
                            {isSelected && <Check size={14} className="text-white" strokeWidth={3} />}
                          </div>
                        )}

                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 mb-1.5">
                            <div className="flex items-center gap-1.5 bg-gray-50 border border-gray-100 px-2 py-0.5 rounded text-gray-600 shadow-sm">
                                <Calendar size={10} className="text-gray-400" />
                                <span className="text-[10px] font-bold uppercase tracking-wide">{report.dateLocal}</span>
                            </div>
                            <span className="text-[10px] text-gray-400 font-medium">{report.timeLocal}</span>
                          </div>
                          <p className={`text-sm font-bold truncate pr-2 ${isSelected ? 'text-brand-900' : 'text-gray-900'}`}>{report.storeName}</p>
                        </div>
                        <div className="text-right">
                          <span className={`block text-base font-bold ${isSelected ? 'text-brand-700' : 'text-brand-600'}`}>{formatCurrency(report.totals.net)}</span>
                          {!isSelectionMode && (
                            <div className="flex items-center justify-end text-gray-400 text-[10px] mt-1 font-medium uppercase tracking-wide group-hover:text-brand-400 transition-colors">
                              {report.items.length} items <ChevronRight size={10} className="ml-1" />
                            </div>
                          )}
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            )}
          </>
        )}
      </div>

      {/* Floating Bottom Action Bar */}
      <div className="fixed bottom-6 left-1/2 transform -translate-x-1/2 w-[calc(100%-3rem)] max-w-md z-50">

        {isSelectionMode ? (
           <div className="flex gap-3 animate-in slide-in-from-bottom-6 duration-300">
              <button 
                type="button"
                onClick={exitSelectionMode}
                className="flex-1 h-14 bg-white/90 backdrop-blur-md border border-gray-200 text-gray-700 font-bold rounded-2xl shadow-xl flex items-center justify-center gap-2 hover:bg-white active:scale-95 transition-all"
              >
                <X size={20} /> Cancel
              </button>
              <button 
                type="button"
                onClick={deleteSelectedReports}
                disabled={selectedIds.size === 0}
                className="flex-[2] h-14 bg-red-600 text-white font-bold rounded-2xl shadow-xl shadow-red-600/30 flex items-center justify-center gap-2 hover:bg-red-700 active:scale-95 transition-all disabled:opacity-50 disabled:shadow-none"
              >
                <Trash2 size={20} fill="currentColor" className="text-red-600/20" /> 
                <span>Delete ({selectedIds.size})</span>
              </button>
           </div>
        ) : (
          <div className="bg-white/80 backdrop-blur-xl border border-white/40 p-2 rounded-[2rem] shadow-2xl shadow-gray-200/50 flex items-center justify-between pl-3 pr-2 gap-4 ring-1 ring-gray-200/50">
            <div className="flex bg-gray-100/80 p-1 rounded-full relative">
               <div 
                 className={`absolute top-1 bottom-1 w-[calc(50%-4px)] bg-white rounded-full shadow-sm transition-all duration-300 ease-out ${viewMode === 'home' ? 'left-1' : 'left-[calc(50%+2px)]'}`}
               ></div>

               <button 
                  type="button"
                  onClick={() => setViewMode('home')}
                  className={`relative z-10 w-12 h-10 rounded-full flex items-center justify-center transition-colors duration-300 ${viewMode === 'home' ? 'text-brand-600' : 'text-gray-400'}`}
               >
                  <LayoutDashboard size={20} />
               </button>
               <button 
                  type="button"
                  onClick={() => setViewMode('history')}
                  className={`relative z-10 w-12 h-10 rounded-full flex items-center justify-center transition-colors duration-300 ${viewMode === 'history' ? 'text-brand-600' : 'text-gray-400'}`}
               >
                  <History size={20} />
               </button>
            </div>

            <button 
              type="button"
              onClick={() => navigate('/new')}
              className="h-14 px-8 bg-gray-900 text-white rounded-[1.5rem] shadow-lg shadow-gray-900/20 flex items-center justify-center gap-2 hover:bg-black active:scale-95 transition-all group"
            >
              <Plus size={24} className="group-hover:rotate-90 transition-transform duration-300" />
              <span className="font-bold text-sm">New Report</span>
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { Camera, Mic, Upload, Loader2, Clipboard, StopCircle, ArrowRight, Check, X, Volume2, AlertTriangle } from 'lucide-react';
import { SalesItem } from '../types';
import * as GeminiService from '../services/geminiService';
import { formatCurrency } from '../utils/calculations';
import * as StorageService from '../services/storageService';

interface CapturePanelProps {
  onItemsCaptured: (items: SalesItem[], method: 'ocr' | 'speech' | 'manual' | 'upload') => void;
  isProcessing: boolean;
  setIsProcessing: (val: boolean) => void;
  onAttachmentsAdded?: (urls: string[]) => void;
}

type TabType = 'snap' | 'copy' | 'speech' | 'upload';

const CapturePanel: React.FC<CapturePanelProps> = ({ onItemsCaptured, isProcessing, setIsProcessing, onAttachmentsAdded }) => {
  const [activeTab, setActiveTab] = useState<TabType>('snap');
  const [inputText, setInputText] = useState('');
  const [isRecording, setIsRecording] = useState(false);

  // Replace useRef with useState for compatibility
  const [mediaRecorder, setMediaRecorder] = useState<MediaRecorder | null>(null);

  // Review Mode State
  const [pendingItems, setPendingItems] = useState<SalesItem[] | null>(null);
  const [pendingSource, setPendingSource] = useState<'ocr' | 'speech' | 'manual' | 'upload'>('manual');

  // Note: We are not exposing attachments state directly to the parent in this component version based on props,
  // but we are uploading files. Ideally, onItemsCaptured should accept attachments or we handle it differently.
  // For now, we follow the existing pattern.

  // Helper: Client-side image compression
  const compressImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const img = new Image();
      const reader = new FileReader();

      reader.onload = (e) => {
        img.src = e.target?.result as string;
      };

      img.onload = () => {
        const canvas = document.createElement('canvas');
        // Increased resolution to 2048 to preserve text details on screenshots
        const maxWidth = 2048; 
        let width = img.width;
        let height = img.height;

        if (width > maxWidth) {
          height = (height * maxWidth) / width;
          width = maxWidth;
        }

        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);

        // JPEG quality 0.85 for better text clarity
        const dataUrl = canvas.toDataURL('image/jpeg', 0.85); 
        resolve(dataUrl.split(',')[1]); // Return base64 only
      };

      reader.onerror = (error) => reject(error);
      reader.readAsDataURL(file);
    });
  };

  // Debounce timer for auto-parsing text
  useEffect(() => {
    if (activeTab !== 'copy' || !inputText.trim() || isProcessing || pendingItems) return;

    const timer = setTimeout(() => {
      // Auto-parse if text is substantial (e.g. pasted)
      if (inputText.length > 5 && inputText.length < 5000) {
        handleTextSubmit();
      }
    }, 1200); // 1.2s debounce

    return () => clearTimeout(timer);
  }, [inputText, activeTab, pendingItems]);

  // Audio Read Back Effect
  useEffect(() => {
    if (pendingItems && pendingSource === 'speech') {
      speakItems(pendingItems);
    }
  }, [pendingItems]);

  const speakItems = (items: SalesItem[]) => {
    if (!items.length || !window.speechSynthesis) return;

    // Stop any current speech
    window.speechSynthesis.cancel();

    const summary = items.length === 1 
      ? `Captured 1 item. ${items[0].quantity} ${items[0].productName} at ${items[0].unitPrice} ${items[0].currency}.`
      : `Captured ${items.length} items. Top item: ${items[0].quantity} ${items[0].productName}.`;

    const utterance = new SpeechSynthesisUtterance(summary);
    utterance.rate = 1.1;
    window.speechSynthesis.speak(utterance);
  };

  // --- Handlers ---

  const handleCapturedResults = (items: SalesItem[], source: 'ocr' | 'speech' | 'manual' | 'upload') => {
    if (items.length === 0) {
      alert("No items found. Please try again.");
      return;
    }
    setPendingSource(source);
    setPendingItems(items);
  };

  const confirmPendingItems = () => {
    if (pendingItems) {
      onItemsCaptured(pendingItems, pendingSource);
      setPendingItems(null);
      setInputText('');
      window.speechSynthesis.cancel();
    }
  };

  const discardPendingItems = () => {
    setPendingItems(null);
    window.speechSynthesis.cancel();
  };

  const handleTextSubmit = async () => {
    if (!inputText.trim() || isProcessing) return;
    // Security: Strict length limit prevents DoS
    if (inputText.length > 5000) {
      alert("Text is too long (max 5000 chars). Please reduce the content.");
      return;
    }

    setIsProcessing(true);
    try {
      const items = await GeminiService.parseFromText(inputText);
      handleCapturedResults(items, 'manual');
    } catch (e: any) {
      alert(`Failed to parse text: ${e.message}`);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleFile = async (file: File, type: 'ocr' | 'upload') => {
    if (!file) return;

    // Security: File size limit (10MB)
    if (file.size > 10 * 1024 * 1024) {
      alert("File is too large (max 10MB).");
      return;
    }

    setIsProcessing(true);

    // 1. Initiate Upload to Storage (Parallel)
    const uploadPromise = StorageService.uploadFile(file);

    try {
      let items: SalesItem[] = [];

      // 2. Process with Gemini
      if (file.type === 'text/csv' || file.name.endsWith('.csv')) {
        const reader = new FileReader();
        reader.onloadend = async () => {
          try {
            const text = reader.result as string;
            // Security: Limit CSV text size processed
            const content = text.length > 20000 ? text.slice(0, 20000) : text;
            items = await GeminiService.parseFromText(content);
            finishProcessing(items);
          } catch (e: any) {
             console.error(e);
             alert(`Failed to parse CSV: ${e.message}`);
             setIsProcessing(false);
          }
        };
        reader.readAsText(file);
        return; // Exit here, let onloadend handle completion
      } 

      // Image Handling (OCR)
      else if (file.type.startsWith('image/')) {
        try {
          // Compress/Resize image on client before sending to AI
          const base64 = await compressImage(file);
          items = await GeminiService.parseFromFile(base64, 'image/jpeg');

          // Wait for upload to complete to log it
          const publicUrl = await uploadPromise;
          if (publicUrl) {
            // Log the OCR attempt to the new 'reports' table
            await StorageService.saveOcrLog(publicUrl, items);
            // Notify parent
            if (onAttachmentsAdded) {
               onAttachmentsAdded([publicUrl]);
            }
          }

          handleCapturedResults(items, type);
        } catch (err: any) {
          console.error(err);
          alert(`Image processing failed: ${err.message || 'Unknown error'}. Please check your API Key configuration.`);
        }
      } 

      // PDF/Other Handling
      else {
        const reader = new FileReader();
        reader.onloadend = async () => {
          try {
            const base64 = (reader.result as string).split(',')[1];
            items = await GeminiService.parseFromFile(base64, file.type);

            // Wait for upload to complete
            const publicUrl = await uploadPromise;
            if (publicUrl && onAttachmentsAdded) {
               onAttachmentsAdded([publicUrl]);
            }

            handleCapturedResults(items, type);
          } catch (err: any) {
            console.error(err);
            alert(`File processing failed: ${err.message}. Please check your API Key configuration.`);
          } finally {
            setIsProcessing(false);
          }
        };
        reader.readAsDataURL(file);
        return; // Exit here
      }
    } catch (e) {
      console.error(e);
    } finally {
      if (!file.type.endsWith('.csv') && !file.type.startsWith('application/pdf')) {
        setIsProcessing(false);
      }
    }
  };

  const finishProcessing = (items: SalesItem[]) => {
      handleCapturedResults(items, 'manual'); // CSV treated as manual/text
      setIsProcessing(false);
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      setMediaRecorder(recorder);

      // Use local variable for chunks to avoid closure/ref issues
      const localChunks: Blob[] = [];

      recorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          localChunks.push(event.data);
        }
      };

      recorder.onstop = async () => {
        setIsProcessing(true);
        const mimeType = MediaRecorder.isTypeSupported('audio/webm') ? 'audio/webm' : 'audio/mp4';
        const audioBlob = new Blob(localChunks, { type: mimeType });

        const reader = new FileReader();
        reader.onloadend = async () => {
           try {
             const base64 = (reader.result as string).split(',')[1];
             const items = await GeminiService.parseFromAudio(base64, mimeType);
             handleCapturedResults(items, 'speech');
           } catch (e: any) {
             console.error(e);
             alert(`Speech processing failed: ${e.message}`);
           } finally {
             setIsProcessing(false);
           }
        };
        reader.readAsDataURL(audioBlob);
        stream.getTracks().forEach(track => track.stop());
      };

      recorder.start();
      setIsRecording(true);
    } catch (err) {
      alert("Microphone access denied or not available.");
    }
  };

  const stopRecording = () => {
    if (mediaRecorder && isRecording) {
      mediaRecorder.stop();
      setIsRecording(false);
    }
  };

  const TabButton = ({ id, icon: Icon, label }: { id: TabType, icon: any, label: string }) => (
    <button
      onClick={() => setActiveTab(id)}
      disabled={isProcessing || !!pendingItems}
      className={`relative flex-1 py-3 text-xs sm:text-sm font-bold flex items-center justify-center gap-2 transition-all rounded-xl z-10 ${
        activeTab === id 
          ? 'text-brand-700' 
          : 'text-gray-400 hover:bg-gray-50'
      } ${isProcessing || pendingItems ? 'opacity-50 cursor-not-allowed' : ''}`}
    >
      <Icon size={18} strokeWidth={2.5} />
      <span>{label}</span>
      {activeTab === id && (
        <div className="absolute inset-0 bg-white rounded-xl shadow-sm border border-gray-100 -z-10 animate-in fade-in zoom-in-95 duration-200"></div>
      )}
    </button>
  );

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-gray-200 overflow-hidden mb-6 relative">
      {/* Review Overlay */}
      {pendingItems && (
        <div className="absolute inset-0 bg-white z-20 flex flex-col animate-in fade-in slide-in-from-bottom-4 duration-300">
          <div className="bg-brand-50 px-4 py-3 border-b border-brand-100 flex justify-between items-center">
            <h3 className="font-bold text-brand-900 text-sm flex items-center gap-2">
              <Check className="text-green-500" size={16} /> 
              Review Captured Items ({pendingItems.length})
            </h3>
            {pendingSource === 'speech' && (
              <button onClick={() => speakItems(pendingItems)} className="p-1.5 text-brand-600 hover:bg-brand-100 rounded-full">
                <Volume2 size={16} />
              </button>
            )}
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-2">
            {pendingItems.map((item, i) => (
              <div key={i} className={`flex justify-between items-center text-sm p-3 rounded-xl border ${item.lowConfidence ? 'bg-amber-50 border-amber-200' : 'bg-gray-50 border-gray-100'}`}>
                <div>
                   <div className="flex items-center gap-2">
                     <span className="font-bold text-gray-900">{item.quantity}x</span> 
                     <span className={item.lowConfidence ? 'text-amber-900' : ''}>{item.productName}</span>
                     {item.lowConfidence && (
                       <span title="Low Confidence">
                         <AlertTriangle size={14} className="text-amber-500" />
                       </span>
                     )}
                   </div>
                   <div className="text-xs text-gray-400">{item.notes}</div>
                </div>
                <span className="font-bold text-brand-600">{formatCurrency(item.unitPrice, item.currency)}</span>
              </div>
            ))}
          </div>
          <div className="p-3 border-t border-gray-100 flex gap-3">
            <button 
              onClick={discardPendingItems}
              className="flex-1 py-3 text-sm font-bold text-gray-500 bg-gray-100 rounded-2xl hover:bg-gray-200 transition-colors"
            >
              Discard
            </button>
            <button 
              onClick={confirmPendingItems}
              className="flex-1 py-3 text-sm font-bold text-white bg-brand-600 rounded-2xl shadow-lg shadow-brand-200 hover:bg-brand-700 transition-colors flex items-center justify-center gap-2"
            >
              <Check size={16} /> Confirm
            </button>
          </div>
        </div>
      )}

      {/* Tabs */}
      <div className="bg-gray-100/50 p-1.5 flex gap-1 rounded-t-3xl border-b border-gray-100">
        <TabButton id="snap" icon={Camera} label="Snap" />
        <TabButton id="copy" icon={Clipboard} label="Copy" />
        <TabButton id="speech" icon={Mic} label="Speech" />
        <TabButton id="upload" icon={Upload} label="Upload" />
      </div>

      {/* Content */}
      <div className="p-4 min-h-[180px] flex items-center justify-center bg-white">
        {isProcessing ? (
          <div className="flex flex-col items-center justify-center py-8 w-full animate-in fade-in duration-300">
            <div className="relative mb-4">
              <div className="absolute inset-0 bg-brand-200 rounded-full animate-ping opacity-75 duration-1000"></div>
              <div className="relative bg-white p-4 rounded-full shadow-md border border-brand-50">
                 <Loader2 className="animate-spin text-brand-600" size={32} />
              </div>
            </div>
            <span className="text-sm font-bold text-gray-800 animate-pulse">Analyzing Content...</span>
            <span className="text-xs text-gray-400 mt-1">Extracting product details</span>
          </div>
        ) : (
          <div className="w-full h-full animate-in slide-in-from-bottom-2 duration-300">
            {activeTab === 'snap' && (
              <label className="flex flex-col items-center justify-center w-full h-40 border-2 border-brand-200 border-dashed rounded-2xl cursor-pointer bg-brand-50/50 hover:bg-brand-50 transition-all group active:scale-[0.99]">
                  <div className="flex flex-col items-center justify-center pt-5 pb-6">
                      <div className="p-3 bg-white rounded-full shadow-sm mb-3 group-hover:shadow-md group-hover:scale-110 transition-all">
                        <Camera className="w-8 h-8 text-brand-500" />
                      </div>
                      <p className="text-sm text-brand-900 font-bold">Take a Photo</p>
                      <p className="text-xs text-brand-500/70 mt-1 font-medium">Receipts, tags, handwritten notes</p>
                  </div>
                  <input 
                    type="file" 
                    accept="image/*" 
                    capture="environment" 
                    className="hidden" 
                    onClick={(e) => { (e.target as HTMLInputElement).value = ''; }}
                    onChange={(e) => e.target.files?.[0] && handleFile(e.target.files[0], 'ocr')} 
                  />
              </label>
            )}

            {activeTab === 'copy' && (
              <div className="space-y-3">
                <div className="relative">
                  <textarea
                    className="w-full p-4 border border-gray-200 rounded-2xl text-sm focus:ring-2 focus:ring-brand-500 focus:border-brand-500 outline-none shadow-sm min-h-[140px] resize-none bg-gray-50/50"
                    placeholder="Paste text here... (e.g. '3x iPhone 15 @ 3499')"
                    value={inputText}
                    onChange={(e) => setInputText(e.target.value)}
                    maxLength={5000} // Security Limit
                  />
                  {inputText && (
                    <div className="absolute bottom-3 right-3 animate-in fade-in zoom-in">
                       <button 
                         onClick={handleTextSubmit}
                         className="bg-brand-600 text-white p-2.5 rounded-full shadow-lg shadow-brand-500/30 hover:bg-brand-700 transition-colors"
                       >
                         <ArrowRight size={18} />
                       </button>
                    </div>
                  )}
                </div>
                <div className="flex justify-between text-[10px] text-gray-400 font-bold px-2 uppercase tracking-wide">
                  <span>Auto-parsing active</span>
                  <span>{inputText.length}/5000</span>
                </div>
              </div>
            )}

            {activeTab === 'speech' && (
              <div className="flex flex-col items-center justify-center h-full py-2">
                <button
                  onClick={isRecording ? stopRecording : startRecording}
                  className={`relative w-24 h-24 rounded-full flex items-center justify-center shadow-2xl transition-all duration-300 ${
                    isRecording 
                      ? 'bg-red-500 scale-105 ring-8 ring-red-100' 
                      : 'bg-gradient-to-br from-brand-500 to-brand-600 hover:shadow-brand-500/40 ring-8 ring-brand-50'
                  }`}
                >
                  {isRecording ? <StopCircle size={40} className="text-white" /> : <Mic size={40} className="text-white" />}
                  {isRecording && (
                    <>
                      <span className="absolute w-full h-full rounded-full animate-ping bg-red-500 opacity-20"></span>
                      <span className="absolute w-full h-full rounded-full animate-pulse bg-red-500 opacity-10 animation-delay-500"></span>
                    </>
                  )}
                </button>
                <p className="mt-5 text-base font-bold text-gray-800">
                  {isRecording ? "Listening..." : "Tap to Speak"}
                </p>
                <p className="text-xs text-gray-400 mt-1 max-w-[200px] text-center font-medium">
                  {isRecording ? "Tap again to finish" : "Dictate items, prices, and quantities naturally"}
                </p>
              </div>
            )}

            {activeTab === 'upload' && (
              <label className="flex flex-col items-center justify-center w-full h-40 border-2 border-gray-200 border-dashed rounded-2xl cursor-pointer bg-white hover:bg-gray-50 transition-all group active:scale-[0.99]">
                  <div className="flex flex-col items-center justify-center pt-5 pb-6">
                      <div className="p-3 bg-gray-50 rounded-full mb-3 group-hover:bg-white group-hover:shadow-sm transition-all group-hover:scale-110">
                        <Upload className="w-8 h-8 text-gray-400 group-hover:text-brand-500 transition-colors" />
                      </div>
                      <p className="text-sm text-gray-600 font-bold group-hover:text-brand-700 transition-colors">Upload File</p>
                      <p className="text-xs text-gray-400 mt-1 font-medium">Screenshots, Photos, PDF, CSV</p>
                  </div>
                  <input 
                    type="file" 
                    accept="image/*, application/pdf, .csv, text/csv" 
                    className="hidden" 
                    onClick={(e) => { (e.target as HTMLInputElement).value = ''; }}
                    onChange={(e) => e.target.files?.[0] && handleFile(e.target.files[0], 'upload')} 
                  />
              </label>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default CapturePanel;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
    <App />
);

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Plus, Search, ChevronRight, FileText, TrendingUp, Calendar, Filter, RefreshCw, History, LayoutDashboard, Loader2, Trash2, CheckSquare, X, Check, User, UserCircle, Coffee, Settings } from 'lucide-react';
import { DailyReport } from '../types';
import * as StorageService from '../services/storageService';
import * as AuthService from '../services/authService';
import { formatCurrency } from '../utils/calculations';
import AuthModal from '../components/AuthModal';

type ViewMode = 'home' | 'history';

// Module-level variables to handle touch interactions safely without Hooks
let longPressTimer: any = null;
let isLongPressEvent = false;

const Dashboard: React.FC = () => {
  const navigate = useNavigate();
  const [reports, setReports] = useState<DailyReport[]>([]);
  const [loading, setLoading] = useState(true);
  const [viewMode, setViewMode] = useState<ViewMode>('home');

  // Auth State
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);

  // Selection Mode State
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Filter states
  const [searchTerm, setSearchTerm] = useState('');
  const [showFilters, setShowFilters] = useState(false);
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const initData = async () => {
    setLoading(true);
    // 1. Check Auth
    const user = await AuthService.getCurrentUser();
    setCurrentUser(user);

    // 2. Load Reports
    const data = await StorageService.loadReports();
    setReports(data);
    setLoading(false);
  };

  useEffect(() => {
    initData();
  }, []);

  const handleAuthSuccess = async () => {
    await initData();
  };

  // --- Selection Logic ---

  const enterSelectionMode = (initialId?: string) => {
    setIsSelectionMode(true);
    if (initialId) {
      setSelectedIds(new Set([initialId]));
    }
  };

  const exitSelectionMode = () => {
    setIsSelectionMode(false);
    setSelectedIds(new Set());
  };

  const toggleReportSelection = (id: string) => {
    const newSelected = new Set(selectedIds);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedIds(newSelected);
  };

  const deleteSelectedReports = async (e: React.MouseEvent) => {
    e.preventDefault(); 
    if (selectedIds.size === 0) return;

    setLoading(true);
    try {
      await StorageService.deleteReports(Array.from(selectedIds));
      const data = await StorageService.loadReports();
      setReports(data);
      exitSelectionMode();
    } catch (e) {
      alert("Failed to delete selected reports.");
    } finally {
      setLoading(false);
    }
  };

  // --- Long Press Handlers ---
  const handleTouchStart = (id: string) => {
    if (isSelectionMode) return;
    isLongPressEvent = false;
    if (longPressTimer) clearTimeout(longPressTimer);
    longPressTimer = setTimeout(() => {
      isLongPressEvent = true;
      enterSelectionMode(id);
      if (navigator.vibrate) navigator.vibrate(50);
    }, 600);
  };

  const handleTouchEnd = () => {
    if (longPressTimer) {
      clearTimeout(longPressTimer);
      longPressTimer = null;
    }
  };

  const handleTouchMove = () => {
    if (longPressTimer) {
      clearTimeout(longPressTimer);
      longPressTimer = null;
    }
  };

  const handleCardClick = (id: string) => {
    if (isLongPressEvent) {
      isLongPressEvent = false;
      return;
    }
    if (isSelectionMode) {
      toggleReportSelection(id);
    } else {
      navigate(`/report/${id}`);
    }
  };

  // --- Filtering ---
  const filteredReports = reports.filter(r => {
    const matchesSearch = !searchTerm || r.storeName.toLowerCase().includes(searchTerm.toLowerCase());
    const reportDate = r.dateLocal;
    const matchesStart = !startDate || reportDate >= startDate;
    const matchesEnd = !endDate || reportDate <= endDate;
    return matchesSearch && matchesStart && matchesEnd;
  }).sort((a, b) => b.dateLocal.localeCompare(a.dateLocal) || b.createdAt - a.createdAt);

  const mostRecentReport = [...reports].sort((a, b) => b.createdAt - a.createdAt)[0];

  // Custom Chart Logic (Replaces Recharts)
  const sortedForChart = [...reports].sort((a, b) => a.dateLocal.localeCompare(b.dateLocal));
  const last7Days = sortedForChart.slice(-7);
  const maxVal = Math.max(...last7Days.map(r => r.totals.net), 1);

  const resetFilters = () => {
    setSearchTerm('');
    setStartDate('');
    setEndDate('');
    setShowFilters(false);
  };

  const hasFilters = searchTerm || startDate || endDate;

  return (
    <div className="min-h-screen bg-gray-50/50 pb-32 font-sans">
      <AuthModal 
        isOpen={isAuthModalOpen} 
        onClose={() => setIsAuthModalOpen(false)} 
        user={currentUser}
        onAuthSuccess={handleAuthSuccess}
      />

      {/* Header Area */}
      <header className={`bg-gradient-to-br from-brand-700 via-brand-600 to-brand-800 text-white px-6 pt-12 pb-8 rounded-b-[2.5rem] shadow-xl transition-all duration-300 relative overflow-hidden ${viewMode === 'history' ? 'pb-8' : ''}`}>
        <div className="absolute top-0 left-0 w-full h-full overflow-hidden opacity-10 pointer-events-none">
           <div className="absolute -top-10 -right-10 w-40 h-40 bg-white rounded-full blur-3xl"></div>
           <div className="absolute bottom-0 left-0 w-60 h-60 bg-brand-300 rounded-full blur-3xl"></div>
        </div>

        <div className="relative z-10 flex justify-between items-start">
            <div>
                <h1 className="text-3xl font-extrabold mb-1 tracking-tight">
                  {viewMode === 'home' ? 'Daily Sales' : 'History'}
                </h1>
                <p className="text-brand-100 text-sm font-medium opacity-90">
                  {viewMode === 'home' ? 'Overview & Insights' : 'Archive & Search'}
                </p>
            </div>

            <div className="flex gap-2">
              <button 
                onClick={() => setIsAuthModalOpen(true)}
                className={`p-2 rounded-full transition-all active:scale-95 shadow-sm border ${currentUser ? 'bg-brand-500 border-brand-400 text-white' : 'bg-white/20 backdrop-blur-md border-white/30 text-white hover:bg-white/30'}`}
                title={currentUser ? "Account" : "Sign In"}
              >
                 {currentUser ? <UserCircle size={24} /> : <User size={22} />}
              </button>

              {viewMode === 'history' && (
                <button 
                  type="button"
                  onClick={() => isSelectionMode ? exitSelectionMode() : enterSelectionMode()} 
                  className={`text-xs px-4 py-2 rounded-full flex items-center gap-1.5 transition-all font-bold shadow-sm active:scale-95 ${isSelectionMode ? 'bg-white text-brand-700 shadow-md' : 'bg-white/20 backdrop-blur-md text-white hover:bg-white/30'}`}
                >
                  <CheckSquare size={14} strokeWidth={2.5} /> {isSelectionMode ? 'Done' : 'Select'}
                </button>
              )}
            </div>
        </div>

        {viewMode === 'history' && !isSelectionMode && (
          <div className="mt-8 flex gap-3 animate-in fade-in slide-in-from-top-4 duration-500">
            <div className="relative flex-1 group">
              <input 
                type="text" 
                placeholder="Search store name..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-white/10 border border-white/20 backdrop-blur-md rounded-2xl py-3.5 pl-11 pr-4 text-white placeholder-brand-200 focus:outline-none focus:bg-white/20 focus:border-white/40 transition-all text-sm shadow-inner group-hover:bg-white/15"
              />
              <Search className="absolute left-4 top-3.5 text-brand-200 group-hover:text-white transition-colors" size={18} />
            </div>
            <button 
              type="button"
              onClick={() => setShowFilters(!showFilters)}
              className={`p-3.5 rounded-2xl border transition-all active:scale-95 ${showFilters ? 'bg-white text-brand-600 border-white shadow-lg' : 'bg-white/10 text-white border-white/20 hover:bg-white/20'}`}
            >
              <Filter size={20} />
            </button>
            {hasFilters && (
                <button type="button" onClick={resetFilters} className="p-3.5 bg-brand-800 hover:bg-brand-900 rounded-2xl flex items-center justify-center transition-colors shadow-sm active:scale-95">
                    <RefreshCw size={20} className="text-white"/>
                </button>
            )}
          </div>
        )}

        {viewMode === 'history' && showFilters && !isSelectionMode && (
            <div className="mt-4 grid grid-cols-2 gap-3 animate-in fade-in slide-in-from-top-2">
                <div className="space-y-1">
                    <label className="text-[10px] uppercase font-bold text-brand-200 ml-2 tracking-wider">From Date</label>
                    <input 
                        type="date" 
                        value={startDate}
                        onChange={(e) => setStartDate(e.target.value)}
                        className="w-full bg-white/10 border border-white/20 rounded-xl py-2.5 px-3 text-white text-sm focus:outline-none focus:bg-white/20 transition-colors" 
                    />
                </div>
                <div className="space-y-1">
                    <label className="text-[10px] uppercase font-bold text-brand-200 ml-2 tracking-wider">To Date</label>
                    <input 
                        type="date" 
                        value={endDate}
                        onChange={(e) => setEndDate(e.target.value)}
                        className="w-full bg-white/10 border border-white/20 rounded-xl py-2.5 px-3 text-white text-sm focus:outline-none focus:bg-white/20 transition-colors" 
                    />
                </div>
            </div>
        )}
      </header>

      <div className="px-5 -mt-6 relative z-20">
        {loading ? (
          <div className="bg-white p-10 rounded-2xl shadow-lg border border-gray-100 flex flex-col items-center justify-center animate-in fade-in duration-500">
             <Loader2 size={36} className="text-brand-500 animate-spin mb-3"/>
             <span className="text-gray-400 text-sm font-medium">Syncing data...</span>
          </div>
        ) : (
          <>
            {/* Custom Chart Card */}
            {viewMode === 'home' && last7Days.length > 0 && (
              <div className="bg-white p-5 rounded-2xl shadow-lg shadow-gray-200/50 border border-gray-100 mb-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
                <div className="flex items-center justify-between mb-6">
                   <h3 className="text-xs font-bold text-gray-500 uppercase flex items-center gap-2 tracking-wider">
                     <div className="p-1 bg-brand-50 rounded-md"><TrendingUp size={14} className="text-brand-600" /></div>
                     Trend
                   </h3>
                   <span className="text-[10px] text-brand-600 font-bold bg-brand-50 px-2.5 py-1 rounded-full border border-brand-100">Last 7 Days</span>
                </div>
                <div className="h-32 w-full flex items-end justify-between gap-2">
                   {last7Days.map((r, i) => {
                      const heightPct = r.isOffDay ? 0 : Math.max(Math.round((r.totals.net / maxVal) * 100), 10);
                      const isLast = i === last7Days.length - 1;
                      return (
                        <div key={r.reportId} className="flex flex-col items-center gap-2 flex-1 h-full justify-end group cursor-default">
                           {/* Bar */}
                           <div 
                              className={`w-full max-w-[24px] rounded-t-md transition-all duration-500 relative ${isLast ? 'bg-brand-600' : 'bg-brand-100 group-hover:bg-brand-200'}`}
                              style={{ height: `${heightPct}%` }}
                           >
                              {/* Tooltip */}
                              <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-1.5 px-2 py-1 bg-gray-900 text-white text-[10px] font-bold rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap z-10 pointer-events-none">
                                {formatCurrency(r.totals.net)}
                              </div>
                           </div>
                           {/* Label */}
                           <span className={`text-[10px] font-bold ${isLast ? 'text-brand-600' : 'text-gray-400'}`}>
                             {r.dateLocal.slice(5)}
                           </span>
                        </div>
                      );
                   })}
                </div>
              </div>
            )}

            {/* HOME VIEW: Latest Report Card */}
            {viewMode === 'home' && (
              <div className="animate-in fade-in slide-in-from-bottom-6 duration-700">
                 {mostRecentReport ? (
                   <div 
                      onClick={() => navigate(`/report/${mostRecentReport.reportId}`)}
                      className="bg-white p-6 rounded-2xl border border-gray-100 shadow-xl shadow-brand-900/5 active:scale-[0.98] transition-all cursor-pointer group relative overflow-hidden"
                    >
                      <div className={`absolute top-0 right-0 w-32 h-32 rounded-full -mr-10 -mt-10 blur-2xl transition-colors ${mostRecentReport.isOffDay ? 'bg-gray-100/50' : 'bg-brand-50/50 group-hover:bg-brand-100/50'}`}></div>

                      <div className="relative z-10">
                        <div className="flex justify-between items-start mb-3">
                           <span className="bg-gray-900 text-white text-xs font-bold px-2.5 py-1 rounded-lg flex items-center gap-1.5 shadow-sm">
                              <Calendar size={12}/> {mostRecentReport.dateLocal}
                           </span>
                           <span className="text-gray-400 text-xs font-medium bg-gray-50 px-2 py-1 rounded-md">{mostRecentReport.timeLocal}</span>
                        </div>
                        <h3 className="text-xl font-bold text-gray-900 mb-1 line-clamp-1">{mostRecentReport.storeName}</h3>

                        {mostRecentReport.isOffDay ? (
                            <p className="text-xs text-gray-400 mb-4 flex items-center gap-1">
                               <Coffee size={12} /> Relax & Recharge
                            </p>
                        ) : (
                            <p className="text-xs text-gray-500 mb-4">{mostRecentReport.items.length} items recorded</p>
                        )}

                        <div className="flex items-end justify-between border-t border-gray-50 pt-4">
                           {mostRecentReport.isOffDay ? (
                              <div className="flex items-center gap-2 text-gray-400">
                                 <div className="p-1.5 bg-gray-100 rounded-full"><Coffee size={18} /></div>
                                 <span className="text-lg font-bold text-gray-500">Off Day</span>
                              </div>
                           ) : (
                              <div className="text-3xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-brand-600 to-brand-800">
                                  {formatCurrency(mostRecentReport.totals.net)}
                              </div>
                           )}

                           <div className="h-8 w-8 bg-brand-50 rounded-full flex items-center justify-center text-brand-600 group-hover:bg-brand-600 group-hover:text-white transition-all shadow-sm">
                             <ChevronRight size={18} />
                           </div>
                        </div>
                      </div>
                   </div>
                 ) : (
                    <div className="text-center py-12 bg-white rounded-2xl border border-dashed border-gray-200 shadow-sm">
                       <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-3">
                          <FileText className="text-gray-300" size={24} />
                       </div>
                       <p className="text-gray-500 font-medium">{currentUser ? "No reports in your account." : "No reports on this device."}</p>
                       <p className="text-gray-400 text-sm mt-1">Tap + to start your first report.</p>
                    </div>
                 )}
              </div>
            )}

            {/* HISTORY VIEW: Full List */}
            {viewMode === 'history' && (
              <div className="space-y-3 animate-in fade-in slide-in-from-bottom-8 duration-500 mt-2 pb-4">
                {isSelectionMode && (
                  <div className="text-center text-xs text-brand-700 font-bold bg-brand-50 p-3 rounded-xl mb-4 border border-brand-100 flex justify-center items-center gap-2 animate-in fade-in slide-in-from-top-2">
                    <CheckSquare size={14} className="text-brand-600"/> 
                    {selectedIds.size === 0 ? "Select items to delete" : `${selectedIds.size} selected`}
                  </div>
                )}
                {filteredReports.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-20 text-gray-400 bg-white rounded-2xl border border-dashed border-gray-200 shadow-sm mt-4">
                    <div className="bg-gray-50 p-5 rounded-full mb-4">
                       <FileText size={32} className="text-gray-300" />
                    </div>
                    <p className="text-sm font-medium text-gray-600">
                        {hasFilters ? 'No reports match your filters.' : 'No reports found.'}
                    </p>
                  </div>
                ) : (
                  filteredReports.map((report) => {
                    const isSelected = selectedIds.has(report.reportId);
                    const isOffDay = report.isOffDay;
                    return (
                      <div 
                        key={report.reportId}
                        onTouchStart={() => handleTouchStart(report.reportId)}
                        onTouchEnd={handleTouchEnd}
                        onTouchMove={handleTouchMove}
                        onClick={() => handleCardClick(report.reportId)}
                        className={`bg-white p-4 rounded-2xl border shadow-sm transition-all cursor-pointer flex justify-between items-center group relative overflow-hidden select-none ${
                          isSelectionMode 
                             ? isSelected 
                                ? 'border-brand-500 ring-1 ring-brand-500 bg-brand-50/30' 
                                : 'border-gray-100 opacity-100'
                             : 'border-gray-100 hover:border-brand-200 hover:shadow-md active:scale-[0.98]'
                        }`}
                      >
                        {isSelectionMode && (
                          <div className={`mr-4 w-6 h-6 min-w-[1.5rem] rounded-full border-2 flex items-center justify-center transition-all duration-200 ${isSelected ? 'bg-brand-500 border-brand-500 scale-110' : 'bg-white border-gray-300'}`}>
                            {isSelected && <Check size={14} className="text-white" strokeWidth={3} />}
                          </div>
                        )}

                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 mb-1.5">
                            <div className="flex items-center gap-1.5 bg-gray-50 border border-gray-100 px-2 py-0.5 rounded text-gray-600 shadow-sm">
                                <Calendar size={10} className="text-gray-400" />
                                <span className="text-[10px] font-bold uppercase tracking-wide">{report.dateLocal}</span>
                            </div>
                            <span className="text-[10px] text-gray-400 font-medium">{report.timeLocal}</span>
                          </div>
                          <p className={`text-sm font-bold truncate pr-2 ${isSelected ? 'text-brand-900' : 'text-gray-900'}`}>{report.storeName}</p>
                        </div>
                        <div className="text-right">
                          {isOffDay ? (
                              <span className="text-[10px] font-bold text-gray-400 bg-gray-100 border border-gray-200 px-2 py-1 rounded-md uppercase tracking-wider">Off Day</span>
                          ) : (
                              <span className={`block text-base font-bold ${isSelected ? 'text-brand-700' : 'text-brand-600'}`}>{formatCurrency(report.totals.net)}</span>
                          )}
                          {!isSelectionMode && !isOffDay && (
                            <div className="flex items-center justify-end text-gray-400 text-[10px] mt-1 font-medium uppercase tracking-wide group-hover:text-brand-400 transition-colors">
                              {report.items.length} items <ChevronRight size={10} className="ml-1" />
                            </div>
                          )}
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            )}
          </>
        )}
      </div>

      {/* Floating Bottom Action Bar */}
      <div className="fixed bottom-6 left-1/2 transform -translate-x-1/2 w-[calc(100%-3rem)] max-w-md z-50">

        {isSelectionMode ? (
           <div className="flex gap-3 animate-in slide-in-from-bottom-6 duration-300">
              <button 
                type="button"
                onClick={exitSelectionMode}
                className="flex-1 h-14 bg-white/90 backdrop-blur-md border border-gray-200 text-gray-700 font-bold rounded-2xl shadow-xl flex items-center justify-center gap-2 hover:bg-white active:scale-95 transition-all"
              >
                <X size={20} /> Cancel
              </button>
              <button 
                type="button"
                onClick={deleteSelectedReports}
                disabled={selectedIds.size === 0}
                className="flex-[2] h-14 bg-red-600 text-white font-bold rounded-2xl shadow-xl shadow-red-600/30 flex items-center justify-center gap-2 hover:bg-red-700 active:scale-95 transition-all disabled:opacity-50 disabled:shadow-none"
              >
                <Trash2 size={20} fill="currentColor" className="text-red-600/20" /> 
                <span>Delete ({selectedIds.size})</span>
              </button>
           </div>
        ) : (
          <div className="bg-white/80 backdrop-blur-xl border border-white/40 p-2 rounded-[2rem] shadow-2xl shadow-gray-200/50 flex items-center justify-between pl-3 pr-2 gap-4 ring-1 ring-gray-200/50">
            <div className="flex bg-gray-100/80 p-1 rounded-full relative">
               <div 
                 className={`absolute top-1 bottom-1 w-[calc(50%-4px)] bg-white rounded-full shadow-sm transition-all duration-300 ease-out ${viewMode === 'home' ? 'left-1' : 'left-[calc(50%+2px)]'}`}
               ></div>

               <button 
                  type="button"
                  onClick={() => setViewMode('home')}
                  className={`relative z-10 w-12 h-10 rounded-full flex items-center justify-center transition-colors duration-300 ${viewMode === 'home' ? 'text-brand-600' : 'text-gray-400'}`}
               >
                  <LayoutDashboard size={20} />
               </button>
               <button 
                  type="button"
                  onClick={() => setViewMode('history')}
                  className={`relative z-10 w-12 h-10 rounded-full flex items-center justify-center transition-colors duration-300 ${viewMode === 'history' ? 'text-brand-600' : 'text-gray-400'}`}
               >
                  <History size={20} />
               </button>
            </div>

            <button 
              type="button"
              onClick={() => navigate('/new')}
              className="h-14 px-8 bg-gray-900 text-white rounded-[1.5rem] shadow-lg shadow-gray-900/20 flex items-center justify-center gap-2 hover:bg-black active:scale-95 transition-all group"
            >
              <Plus size={24} className="group-hover:rotate-90 transition-transform duration-300" />
              <span className="font-bold text-sm">New Report</span>
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;

import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertTriangle, RefreshCw } from 'lucide-react';

interface Props {
  children?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null
  };

  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
  }

  public render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-gray-50 text-center font-sans">
          <div className="bg-red-100 p-4 rounded-full mb-4">
             <AlertTriangle className="text-red-600" size={32} />
          </div>
          <h1 className="text-2xl font-bold text-gray-900 mb-2">Something went wrong</h1>
          <p className="text-gray-500 mb-6 max-w-xs mx-auto">The application encountered an unexpected error.</p>

          <div className="w-full max-w-md bg-white p-4 rounded-xl border border-gray-200 shadow-sm mb-6 text-left overflow-hidden">
             <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Error Details</p>
             <pre className="text-xs text-red-600 font-mono whitespace-pre-wrap break-words">
               {this.state.error?.message || 'Unknown Error'}
             </pre>
          </div>

          <button 
            onClick={() => window.location.reload()}
            className="px-6 py-3 bg-brand-600 text-white rounded-xl font-bold shadow-lg shadow-brand-500/30 flex items-center gap-2 hover:bg-brand-700 transition-all active:scale-95"
          >
            <RefreshCw size={18} />
            Reload Application
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

