                      <div className={`absolute top-0 right-0 w-32 h-32 rounded-full -mr-10 -mt-10 blur-2xl transition-colors ${mostRecentReport.isOffDay ? 'bg-gray-100/50' : 'bg-brand-50/50 group-hover:bg-brand-100/50'}`}></div>

