  }
};

export const clearAllReports = async (): Promise<void> => {
  const reports = await loadReports();
  const ids = reports.map(r => r.reportId);

  if (ids.length === 0) return;

  const { error } = await supabase
    .from('daily_reports')
    .delete()
    .in('report_id', ids);

  if (error) {
    console.error('Error clearing reports:', error.message);
    throw new Error(`Database Error: ${error.message}`);
  }
};

export const deleteReports = async (ids: string[]): Promise<void> => {
  if (ids.length === 0) return;
  const { error } = await supabase
    .from('daily_reports')
    .delete()
    .in('report_id', ids);

  if (error) throw new Error(`Database Error: ${error.message}`);
};

export const getReportById = async (id: string): Promise<DailyReport | undefined> => {
  const { data, error } = await supabase
    .from('daily_reports')
    .select('*')
    .eq('report_id', id)
    .single();

  if (error || !data) return undefined;
  return mapFromDb(data);
};

export const uploadFile = async (file: File): Promise<string | null> => {
  try {
    const fileExt = file.name.split('.').pop();
    const fileName = `${Date.now()}_${generateId()}.${fileExt}`;
    const { data, error } = await supabase.storage.from('uploads').upload(fileName, file);
    if (error) return null;
    if (!data?.path) return null;
    const { data: { publicUrl } } = supabase.storage.from('uploads').getPublicUrl(data.path);
    return publicUrl;
  } catch (e) {
    return null;
  }
};

export const saveOcrLog = async (imageUrl: string, analysis: SalesItem[]): Promise<void> => {
  const { error } = await supabase
    .from('reports')
    .insert({ image_url: imageUrl, analysis: JSON.stringify(analysis) });
  if (error) console.warn('Error logging OCR:', error.message);
};

export const saveConfig = (config: AppConfig) => {
  localStorage.setItem(LOCAL_STORAGE_KEYS.CONFIG, JSON.stringify(config));
};

export const loadConfig = (): AppConfig => {
  const data = localStorage.getItem(LOCAL_STORAGE_KEYS.CONFIG);
  const parsed = data ? JSON.parse(data) : {};
  return { 
    salesRepName: parsed.salesRepName || '',
    phoneNumber: parsed.phoneNumber || '',
    enableReminders: parsed.enableReminders || false,
    reminderTime: parsed.reminderTime || '22:00'
  };
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Plus, Search, ChevronRight, FileText, TrendingUp, Calendar, Filter, RefreshCw, History, LayoutDashboard, Loader2, Trash2, CheckSquare, X, Check, User, UserCircle, Coffee, Settings } from 'lucide-react';
import { DailyReport } from '../types';
import * as StorageService from '../services/storageService';
import * as AuthService from '../services/authService';
import { formatCurrency } from '../utils/calculations';
import AuthModal from '../components/AuthModal';
import SettingsModal from '../components/SettingsModal';

type ViewMode = 'home' | 'history';

// Module-level variables to handle touch interactions safely without Hooks
let longPressTimer: any = null;
let isLongPressEvent = false;

const Dashboard: React.FC = () => {
  const navigate = useNavigate();
  const [reports, setReports] = useState<DailyReport[]>([]);
  const [loading, setLoading] = useState(true);
  const [viewMode, setViewMode] = useState<ViewMode>('home');

  // Auth State
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Selection Mode State
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Filter states
  const [searchTerm, setSearchTerm] = useState('');
  const [showFilters, setShowFilters] = useState(false);
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const initData = async () => {
    setLoading(true);
    // 1. Check Auth
    const user = await AuthService.getCurrentUser();
    setCurrentUser(user);

    // 2. Load Reports
    const data = await StorageService.loadReports();
    setReports(data);
    setLoading(false);
  };

  useEffect(() => {
    initData();

    // Reminder Check Logic
    const checkReminder = () => {
      const config = StorageService.loadConfig();
      if (!config.enableReminders || !config.reminderTime) return;

      const now = new Date();
      const [hours, minutes] = config.reminderTime.split(':').map(Number);

      if (now.getHours() === hours && now.getMinutes() === minutes) {
         // Check if already notified today
         const lastDate = localStorage.getItem('dsr_last_reminder_date');
         const today = new Date().toDateString();

         if (lastDate !== today) {
           if ('Notification' in window && Notification.permission === 'granted') {
             new Notification("Daily Sales Reminder", { 
               body: "Time to post your daily sales report!",
               icon: '/vite.svg' // Fallback icon
             });
             localStorage.setItem('dsr_last_reminder_date', today);
           }
         }
      }
    };

    // Check every minute
    const interval = setInterval(checkReminder, 60000);
    // Initial check
    checkReminder();

    return () => clearInterval(interval);
  }, []);

  const handleAuthSuccess = async () => {
    await initData();
  };

  const handleConfigChange = () => {
    // Reload logic if needed, but config is mostly for ReportEditor.
    // Dashboard handles the loop internally via loadConfig() call inside interval.
  };

  // --- Selection Logic ---

  const enterSelectionMode = (initialId?: string) => {
    setIsSelectionMode(true);
    if (initialId) {
      setSelectedIds(new Set([initialId]));
    }
  };

  const exitSelectionMode = () => {
    setIsSelectionMode(false);
    setSelectedIds(new Set());
  };

  const toggleReportSelection = (id: string) => {
    const newSelected = new Set(selectedIds);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedIds(newSelected);
  };

  const deleteSelectedReports = async (e: React.MouseEvent) => {
    e.preventDefault(); 
    if (selectedIds.size === 0) return;

    setLoading(true);
    try {
      await StorageService.deleteReports(Array.from(selectedIds));
      const data = await StorageService.loadReports();
      setReports(data);
      exitSelectionMode();
    } catch (e) {
      alert("Failed to delete selected reports.");
    } finally {
      setLoading(false);
    }
  };

  // --- Long Press Handlers ---
  const handleTouchStart = (id: string) => {
    if (isSelectionMode) return;
    isLongPressEvent = false;
    if (longPressTimer) clearTimeout(longPressTimer);
    longPressTimer = setTimeout(() => {
      isLongPressEvent = true;
      enterSelectionMode(id);
      if (navigator.vibrate) navigator.vibrate(50);
    }, 600);
  };

  const handleTouchEnd = () => {
    if (longPressTimer) {
      clearTimeout(longPressTimer);
      longPressTimer = null;
    }
  };

  const handleTouchMove = () => {
    if (longPressTimer) {
      clearTimeout(longPressTimer);
      longPressTimer = null;
    }
  };

  const handleCardClick = (id: string) => {
    if (isLongPressEvent) {
      isLongPressEvent = false;
      return;
    }
    if (isSelectionMode) {
      toggleReportSelection(id);
    } else {
      navigate(`/report/${id}`);
    }
  };

  // --- Filtering ---
  const filteredReports = reports.filter(r => {
    const matchesSearch = !searchTerm || r.storeName.toLowerCase().includes(searchTerm.toLowerCase());
    const reportDate = r.dateLocal;
    const matchesStart = !startDate || reportDate >= startDate;
    const matchesEnd = !endDate || reportDate <= endDate;
    return matchesSearch && matchesStart && matchesEnd;
