        onClose={() => setIsAuthModalOpen(false)} 
        user={currentUser}
        onAuthSuccess={handleAuthSuccess}
      />

      <SettingsModal 
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
        onConfigChange={handleConfigChange}
        user={currentUser}
