                        <div>
                          <span className="text-xs font-bold text-gray-500 bg-gray-100 px-2 py-0.5 rounded-md uppercase tracking-wide">Staff B</span>
                          <h4 className="font-bold text-gray-900 mt-1">{createdSplitReports.b.salesRepName}</h4>
