import { GoogleGenAI, Type } from "@google/genai";
import { SalesItem } from "../types";

const ITEM_SCHEMA = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      productName: { type: Type.STRING },
      sku: { type: Type.STRING },
      quantity: { type: Type.NUMBER },
      unitPrice: { type: Type.NUMBER },
      currency: { type: Type.STRING },
      notes: { type: Type.STRING },
      lowConfidence: { type: Type.BOOLEAN },
    },
    required: ["productName", "quantity", "unitPrice"],
  },
};

const SYSTEM_INSTRUCTION = `
You are an advanced AI assistant for a mobile sales app, specialized in OCR and data extraction.
Extract sales items from inputs (images, text, or audio).

Extraction Rules:
1. Target fields: productName, sku, quantity (number), unitPrice (number), currency, notes.
2. Normalize Spoken Numerals: Convert word-form numbers to integers/decimals (e.g., "one twenty-eight" -> 128, "three fifty" -> 3.50, "five thousand" -> 5000).
3. Normalize Units: Map unit markers like "pieces", "units", "qty", "packs", "boxes", "sets" to the numeric 'quantity' field. 
   - Example: "ten pieces of item X" -> quantity: 10.
4. Corrective Logic: If a user corrects themselves in text or speech (e.g., "send 2 pieces... no wait, 5 pieces"), extract the final intended value (5).
5. Confidence: Set 'lowConfidence: true' if the input is ambiguous, phonetic recognition is poor, or details are missing.

Handle diverse formats like "2x iPhone @ 1000" or natural speech like "I just sold ten units of the screen protector for forty five dirhams each".
`;

export const parseFromText = async (text: string): Promise<SalesItem[]> => {
  // Always create a new GoogleGenAI instance right before the call to ensure fresh configuration
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: `Extract sales items from: ${text}`,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: ITEM_SCHEMA,
      },
    });
    // The .text property is used directly on the response object
    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Gemini Text Parse Error:", error);
    throw error;
  }
};

export const parseFromFile = async (base64Data: string, mimeType: string): Promise<SalesItem[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: {
        parts: [
          { inlineData: { mimeType, data: base64Data } },
          { text: "Extract all items, quantities, and prices from this image." }
        ]
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: ITEM_SCHEMA,
      },
    });
    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Gemini File Parse Error:", error);
    throw error;
  }
};

export const parseFromAudio = async (base64Audio: string, mimeType: string = 'audio/webm'): Promise<SalesItem[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: {
        parts: [
          { inlineData: { mimeType: mimeType, data: base64Audio } },
          { text: "Listen and extract the list of sold items. Normalize spoken numbers (like 'one twenty') and unit keywords (like 'pieces') into numeric quantities and unit prices." }
        ]
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: ITEM_SCHEMA,
      },
