import React, { ErrorInfo, ReactNode } from 'react';
import { AlertTriangle, RefreshCw } from 'lucide-react';

interface Props {
  children?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

/**
 * ErrorBoundary catches runtime errors in the component tree and displays a fallback UI.
 * Explicitly extending React.Component with Props and State ensures 'this.props' and 'this.state' 
 * are correctly identified by the TypeScript compiler.
 */
// Fix: Use React.Component to provide proper context for props and state
export class ErrorBoundary extends React.Component<Props, State> {
  // Define initial state
  // Fix: Removed 'override' modifier as property overriding is not supported in this environment
  public state: State = {
    hasError: false,
    error: null,
  };

  // Update state when an error occurs
  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  // Log error information
  // Fix: Removed 'override' modifier as method overriding is failing detection in this environment
  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("ErrorBoundary caught an error", error, errorInfo);
  }

  // Fix: Removed 'override' modifier
  public render() {
    // Destructuring state and props for cleaner access and better type inference
    // Fix: this.props and this.state are now accessible through React.Component inheritance
    const { hasError, error } = this.state;
    const { children } = this.props;

    if (hasError) {
      return (
        <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-gray-50 text-center font-sans">
          <div className="bg-red-100 p-4 rounded-full mb-4">
             <AlertTriangle className="text-red-600" size={32} />
          </div>
          <h1 className="text-2xl font-bold text-gray-900 mb-2">Something went wrong</h1>
          <p className="text-gray-500 mb-6 max-w-xs mx-auto">The application encountered an unexpected error.</p>

          <div className="w-full max-w-md bg-white p-4 rounded-xl border border-gray-200 shadow-sm mb-6 text-left overflow-hidden">
             <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Error Details</p>
             <pre className="text-xs text-red-600 font-mono whitespace-pre-wrap break-words">
               {error?.message || 'Unknown Error'}
             </pre>
          </div>

          <button 
            onClick={() => window.location.reload()}
            className="px-6 py-3 bg-brand-600 text-white rounded-xl font-bold shadow-lg shadow-brand-500/30 flex items-center gap-2 hover:bg-brand-700 transition-all active:scale-95"
          >
            <RefreshCw size={18} />
            Reload Application
          </button>
        </div>
      );
    }

    // Accessing children through destructured props
    return children;
  }
}

import { GoogleGenAI, Type } from "@google/genai";
import { SalesItem } from "../types";

const ITEM_SCHEMA = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      productName: { type: Type.STRING },
      sku: { type: Type.STRING },
      quantity: { type: Type.NUMBER },
      unitPrice: { type: Type.NUMBER },
      currency: { type: Type.STRING },
      notes: { type: Type.STRING },
      lowConfidence: { type: Type.BOOLEAN },
    },
    required: ["productName", "quantity", "unitPrice"],
  },
};

const SYSTEM_INSTRUCTION = `
You are an advanced AI assistant for a mobile sales app, specialized in OCR and data extraction for sales reports.
Extract sales items from inputs (images of receipts, spoken descriptions, or pasted text).

Extraction Rules:
1. Target fields: productName, sku, quantity (number), unitPrice (number), currency, notes.
2. Normalize Spoken Numerals: Always convert spoken number words into their numeric equivalents.
3. Normalize Units: Map unit markers like "pieces", "units", "qty" to the 'quantity' field.
4. Self-Correction: Use the final intended value if user corrects themselves.
5. Confidence: Set 'lowConfidence: true' if the input is ambiguous.
`;

/**
 * Robustly checks for an API key.
 * If missing and in a supported environment, opens the selection dialog.
 */
export const ensureApiKey = async (): Promise<boolean> => {
  // 1. Check environment variable first
  if (process.env.API_KEY && process.env.API_KEY.length > 5) {
    return true;
  }

  // 2. Check if we can open the AI Studio selector
  if (window.aistudio) {
    const hasSelected = await window.aistudio.hasSelectedApiKey();
    if (hasSelected) return true;

    // In many cases, we want to return false here so the UI can show a button
    // rather than forcing the dialog immediately on every check.
    return false;
  }

  return false;
};

/**
 * Force-opens the key selector if available.
 */
export const requestKeySelection = async () => {
  if (window.aistudio) {
    await window.aistudio.openSelectKey();
    return true;
  }
  return false;
};

/**
 * Creates a new instance of the Gemini AI client.
 */
const getClient = async () => {
  const apiKey = process.env.API_KEY;

  if (!apiKey || apiKey.length < 5) {
    // Attempt to prompt if possible
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      // Per instructions, assume success after triggering to avoid race conditions
      return new GoogleGenAI({ apiKey: process.env.API_KEY });
    }
    throw new Error("Missing API Key. Please configure the API_KEY environment variable or select a key in the settings.");
  }

  return new GoogleGenAI({ apiKey });
};

export const parseFromText = async (text: string): Promise<SalesItem[]> => {
  const ai = await getClient();
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Extract sales items from the following text: "${text}"`,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: ITEM_SCHEMA,
      },
    });

    const content = response.text;
    if (!content) return [];
    return JSON.parse(content);
  } catch (error: any) {
    console.error("Gemini Text Parse Error:", error);
    if (error.message?.includes("entity was not found") && window.aistudio) {
      await window.aistudio.openSelectKey();
    }
    throw error;
  }
};

export const parseFromFile = async (base64Data: string, mimeType: string): Promise<SalesItem[]> => {
  const ai = await getClient();
  try {
    const response = await ai.models.generateContent({
