              />
              <Search className="absolute left-4 top-3.5 text-brand-200 group-hover:text-white transition-colors" size={18} />
            </div>
            <button 
              type="button"
              onClick={() => setShowFilters(!showFilters)}
              className={`p-3.5 rounded-2xl border transition-all active:scale-95 ${showFilters ? 'bg-white text-brand-600 border-white shadow-lg' : 'bg-white/10 text-white border-white/20 hover:bg-white/20'}`}
            >
              <Filter size={20} />
            </button>
          </div>
        )}
      </header>

      <div className="px-5 -mt-6 relative z-20">
        {!hasKey && (
          <div className="bg-white border border-amber-200 p-4 rounded-2xl mb-6 shadow-xl animate-in fade-in slide-in-from-top-4 duration-500 flex items-center justify-between ring-4 ring-amber-50">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-amber-100 rounded-lg text-amber-600">
                <AlertCircle size={20} />
              </div>
              <div>
                <p className="text-sm font-bold text-amber-900">AI Features Disabled</p>
                <p className="text-[10px] text-amber-600 font-medium">Please select an API Key to enable OCR & Speech extraction.</p>
