/**
 * Decodes a base64 string to a Uint8Array.
 * Required implementation per Gemini API guidelines.
 */
export function decode(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

/**
 * Encodes a Uint8Array to a base64 string.
 */
export function encode(bytes: Uint8Array): string {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

/**
 * Decodes raw PCM data into an AudioBuffer for playback.
 * Gemini 2.5 TTS returns raw PCM data without headers.
 */
export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      // Convert 16-bit PCM to float [-1.0, 1.0]
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import { GoogleGenAI, Type, Modality } from "@google/genai";
import { SalesItem } from "../types";

const ITEM_SCHEMA = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      productName: { type: Type.STRING },
      sku: { type: Type.STRING },
      quantity: { type: Type.NUMBER },
      unitPrice: { type: Type.NUMBER },
      currency: { type: Type.STRING },
      notes: { type: Type.STRING },
      lowConfidence: { type: Type.BOOLEAN },
    },
    required: ["productName", "quantity", "unitPrice"],
  },
};

const SYSTEM_INSTRUCTION = `
You are an advanced AI assistant for a mobile sales app, specialized in OCR and data extraction for sales reports.
Extract sales items from inputs (images of receipts, spoken descriptions, or pasted text).

Extraction Rules:
1. Target fields: productName, sku, quantity (number), unitPrice (number), currency, notes.
2. Normalize Spoken Numerals: Always convert spoken number words into their numeric equivalents.
3. Normalize Units: Map unit markers like "pieces", "units", "qty" to the 'quantity' field.
4. Self-Correction: Use the final intended value if user corrects themselves.
5. Confidence: Set 'lowConfidence: true' if the input is ambiguous.
`;

/**
 * Checks if a valid API key is available in the environment.
 */
export const hasValidKey = (): boolean => {
  const key = process.env.API_KEY;
  return !!(key && key.length > 5 && key !== "undefined" && key !== "null" && key !== "");
};

/**
 * Ensures an API key is selected. In AI Studio, this opens the picker.
 */
export const ensureApiKey = async (): Promise<boolean> => {
  if (hasValidKey()) return true;

  try {
    if (typeof window !== 'undefined' && window.aistudio && typeof window.aistudio.hasSelectedApiKey === 'function') {
      const hasSelected = await window.aistudio.hasSelectedApiKey();
      return !!hasSelected;
    }
  } catch (e) {
    console.warn("Key check failed:", e);
  }

  return false;
};

/**
 * Triggers the native API key selection dialog.
 */
export const requestKeySelection = async (): Promise<boolean> => {
  if (typeof window !== 'undefined' && window.aistudio && typeof window.aistudio.openSelectKey === 'function') {
    try {
      await window.aistudio.openSelectKey();
      // Per instructions: assume success after triggering to mitigate race conditions
      return true;
    } catch (e) {
      console.error("Failed to open key selector:", e);
      throw e;
    }
  }
  return false;
};

/**
 * Creates a fresh instance of the Gemini AI client using the latest environment key.
 */
const getClient = async () => {
  const apiKey = process.env.API_KEY;

  if (!apiKey || apiKey.length < 5 || apiKey === "undefined" || apiKey === "null") {
    if (typeof window !== 'undefined' && window.aistudio) {
      await window.aistudio.openSelectKey();
      // Use latest injected key immediately
      return new GoogleGenAI({ apiKey: process.env.API_KEY });
    }
    throw new Error("Gemini API Key is missing. Please click 'Select Key' in the app dashboard.");
  }

  return new GoogleGenAI({ apiKey });
};

/**
 * Handles common API errors, specifically re-triggering key selection on 404s.
 */
const handleApiError = async (error: any) => {
  console.error("Gemini API Error:", error);
  const message = error?.message || "";

  if (message.includes("Requested entity was not found") && typeof window !== 'undefined' && window.aistudio) {
    await window.aistudio.openSelectKey();
  }

  throw error;
};

export const parseFromText = async (text: string): Promise<SalesItem[]> => {
  const ai = await getClient();
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Extract sales items from the following text: "${text}"`,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: ITEM_SCHEMA,
      },
    });

    const content = response.text;
    if (!content) return [];
    return JSON.parse(content);
  } catch (error) {
    return handleApiError(error);
  }
};

export const parseFromFile = async (base64Data: string, mimeType: string): Promise<SalesItem[]> => {
  const ai = await getClient();
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          { inlineData: { mimeType, data: base64Data } },
          { text: "Extract all sales items, their quantities, and their individual unit prices from this image. Output JSON." }
        ]
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: ITEM_SCHEMA,
      },
    });

    const content = response.text;
    if (!content) return [];
    return JSON.parse(content);
  } catch (error) {
    return handleApiError(error);
  }
};

export const parseFromAudio = async (base64Audio: string, mimeType: string = 'audio/webm'): Promise<SalesItem[]> => {
  const ai = await getClient();
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          { inlineData: { mimeType: mimeType, data: base64Audio } },
          { text: "Listen to this audio and extract the list of sold items. Normalize numbers. Output JSON." }
        ]
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: ITEM_SCHEMA,
      },
    });

    const content = response.text;
    if (!content) return [];
    return JSON.parse(content);
  } catch (error) {
    return handleApiError(error);
  }
};

/**
 * Transforms text into spoken audio using gemini-2.5-flash-preview-tts.
 */
export const generateSpeech = async (text: string): Promise<string | undefined> => {
  const ai = await getClient();
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    return base64Audio;
  } catch (error) {
    return handleApiError(error);
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { ArrowLeft, Share2, Clock, MapPin, User, Calendar, CheckCircle, Globe, AlertTriangle, Loader2, Undo2, Redo2, Save, Users, X, Split, Percent, Copy, MessageCircle, ArrowRightLeft, ArrowRight, ArrowLeft as ArrowLeftIcon, Plus, Minus, Volume2, VolumeX } from 'lucide-react';
import { DailyReport, SalesItem, SourceType } from '../types';
import * as StorageService from '../services/storageService';
import * as CalculationUtils from '../utils/calculations';
import { MOCK_STORES, LOCAL_STORAGE_KEYS } from '../constants';
import useUndoRedo from '../hooks/useUndoRedo';
import * as GeminiService from '../services/geminiService';
import * as AudioUtils from '../utils/audioUtils';

import CapturePanel from '../components/CapturePanel';
import ItemsTable from '../components/ItemsTable';
import TotalsPanel from '../components/TotalsPanel';

const ReportEditor: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const isNew = !id;

  const [loading, setLoading] = useState(true);
  const [processing, setProcessing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);

  // Use Custom Hook for State Management
  const { state: report, set: setReport, undo, redo, canUndo, canRedo, init: initReport } = useUndoRedo<DailyReport | null>(null);

  const [isDirty, setIsDirty] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const [dateWarning, setDateWarning] = useState<{msg: string, date: string} | null>(null);

  // Validation State
  const [errors, setErrors] = useState<Record<number, { [key in keyof SalesItem]?: string } & { items?: string }>>({});
  const [globalError, setGlobalError] = useState<string | null>(null);

  // Split Feature State
  const [isSplitModalOpen, setIsSplitModalOpen] = useState(false);
  const [splitRatio, setSplitRatio] = useState<0.5 | 0.6 | 0.7>(0.5);
  const [staff2Name, setStaff2Name] = useState('');

  // Advanced Split State
  const [splitItemsA, setSplitItemsA] = useState<SalesItem[]>([]);
  const [splitItemsB, setSplitItemsB] = useState<SalesItem[]>([]);

  // New State for Success View
  const [createdSplitReports, setCreatedSplitReports] = useState<{a: DailyReport, b: DailyReport} | null>(null);

  // Initialize Report
  useEffect(() => {
    const init = async () => {
      if (isNew) {
        const { dateLocal, timeLocal, tz } = CalculationUtils.getLocalDateTimeAndTimezone();
        const config = StorageService.loadConfig();

        const lastStore = localStorage.getItem(LOCAL_STORAGE_KEYS.LAST_STORE) || MOCK_STORES[0];
        const defaultName = [config.salesRepName, config.phoneNumber].filter(Boolean).join(' | ');

        const newReport: DailyReport = {
          reportId: CalculationUtils.generateId(),
          dateLocal,
          timeLocal,
          timezone: tz,
          storeName: lastStore,
          salesRepName: defaultName,
          items: [],
          totals: { gross: 0, discounts: 0, net: 0 },
          sources: [],
          attachments: [],
          shareMessage: '',
          createdAt: Date.now()
        };
        initReport(newReport);
        setLoading(false);
      } else {
        const existing = await StorageService.getReportById(id as string);
        if (existing) {
          initReport(existing);
        } else {
          alert("Report not found");
          navigate('/');
        }
        setLoading(false);
      }
    };
    init();

    return () => {
      stopSpeech();
    };
  }, [id, isNew, navigate, initReport]);

  const stopSpeech = () => {
    if (sourceNodeRef.current) {
      try { sourceNodeRef.current.stop(); } catch (e) {}
      sourceNodeRef.current = null;
    }
    setIsSpeaking(false);
  };

  const handleTTS = async () => {
    if (isSpeaking) {
      stopSpeech();
      return;
    }

    if (!report?.shareMessage) return;

    setIsSpeaking(true);
    try {
      const base64Audio = await GeminiService.generateSpeech(report.shareMessage);
      if (!base64Audio) {
        setIsSpeaking(false);
        return;
      }

      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const ctx = audioContextRef.current;
      const audioBuffer = await AudioUtils.decodeAudioData(AudioUtils.decode(base64Audio), ctx);

      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      source.onended = () => setIsSpeaking(false);

      sourceNodeRef.current = source;
      source.start();
    } catch (e) {
      console.error("TTS failed", e);
      setIsSpeaking(false);
    }
  };

  // Reset split state when modal closes/opens
  useEffect(() => {
    if (!isSplitModalOpen) {
      setCreatedSplitReports(null);
      setStaff2Name('');
    }
  }, [isSplitModalOpen]);

  const updateReport = useCallback((changes: Partial<DailyReport>) => {
    if (!report) return;

    const updatedReport = { ...report, ...changes };
    const newTotals = CalculationUtils.computeTotals(updatedReport.items, updatedReport.totals.discounts);
    updatedReport.totals = newTotals;
    updatedReport.shareMessage = CalculationUtils.buildShareMessage(updatedReport);

    setReport(updatedReport);
    setIsDirty(true);
  }, [report, setReport]);

  useEffect(() => {
    if (isSplitModalOpen && report && !createdSplitReports) {
      const [itemsA, itemsB] = CalculationUtils.splitSalesItems(report.items, splitRatio);
      setSplitItemsA(itemsA);
      setSplitItemsB(itemsB);
    }
  }, [isSplitModalOpen, splitRatio, report, createdSplitReports]);

  const moveOneUnit = (fromList: SalesItem[], toList: SalesItem[], index: number, setFrom: any, setTo: any) => {
    const itemToMove = fromList[index];
    if (!itemToMove) return;

    const newFrom = [...fromList];
    if (itemToMove.quantity > 1) {
        newFrom[index] = { ...itemToMove, quantity: itemToMove.quantity - 1 };
    } else {
        newFrom.splice(index, 1);
    }

    const newTo = [...toList];
    const existingIndex = newTo.findIndex(i => 
        i.productName === itemToMove.productName && 
        i.unitPrice === itemToMove.unitPrice && 
        i.sku === itemToMove.sku &&
        i.notes === itemToMove.notes
    );

    if (existingIndex >= 0) {
        newTo[existingIndex] = { ...newTo[existingIndex], quantity: newTo[existingIndex].quantity + 1 };
    } else {
        newTo.push({ ...itemToMove, quantity: 1 });
    }

    setFrom(newFrom);
    setTo(newTo);
  };

  const getTotal = (items: SalesItem[]) => items.reduce((sum, i) => sum + (i.quantity * i.unitPrice), 0);

  useEffect(() => {
    if (!report?.timezone || !report?.dateLocal) return;

    try {
      const now = new Date();
      const formatter = new Intl.DateTimeFormat('en-CA', {
        timeZone: report.timezone,
        year: 'numeric',
        month: '2-digit',
        day: '2-digit'
      });
      const todayInTz = formatter.format(now);

      if (todayInTz !== report.dateLocal) {
        setDateWarning({
          msg: `It is currently ${todayInTz} in ${report.timezone.split('/')[1] || report.timezone}.`,
          date: todayInTz
        });
      } else {
        setDateWarning(null);
      }
    } catch (e) {
      setDateWarning(null); 
    }
  }, [report?.timezone, report?.dateLocal]);

  const validate = (reportToValidate: DailyReport | null = report): boolean => {
    if (!reportToValidate) return false;
    let isValid = true;
    const newErrors: Record<number, { [key in keyof SalesItem]?: string } & { items?: string }> = {};
    setGlobalError(null);

    if (reportToValidate.items.length === 0) {
      newErrors[-1] = { items: "At least one item is required." }; 
      setGlobalError("Please add at least one item.");
      isValid = false;
    }

    reportToValidate.items.forEach((item, index) => {
      const itemErrors: { [key in keyof SalesItem]?: string } = {};
      if (!item.productName || !(item.productName || '').trim()) {
        itemErrors.productName = "Required";
        isValid = false;
      }
      if (item.quantity <= 0 || isNaN(item.quantity) || !Number.isInteger(item.quantity)) {
        itemErrors.quantity = "Min 1";
        isValid = false;
      }
      if (item.unitPrice < 0 || isNaN(item.unitPrice)) {
        itemErrors.unitPrice = "Invalid";
        isValid = false;
      }
      if (Object.keys(itemErrors).length > 0) {
        newErrors[index] = itemErrors;
      }
    });

    setErrors(newErrors);
    return isValid;
  };

  const sanitizeInput = (input: string): string => {
    if (!input) return '';
    let clean = input.replace(/<\/?[^>]+(>|$)/g, "");
    if (/^[=+\-@]/.test(clean)) clean = "'" + clean;
    return clean.trim();
  };

  const handleSave = async (showErrorAlert = true): Promise<DailyReport | null> => {
    if (!report) return null;

    const sanitizedReport: DailyReport = {
        ...report,
        salesRepName: sanitizeInput(report.salesRepName),
        items: report.items.map(i => ({
            ...i,
            productName: sanitizeInput(i.productName),
            sku: sanitizeInput(i.sku),
            notes: sanitizeInput(i.notes || '')
        }))
    };

    if (!sanitizedReport.salesRepName) {
      if (showErrorAlert) alert("Please enter a Sales Rep Name");
      return null;
    }

    if (!validate(sanitizedReport)) return null;

    setSaving(true);
    try {
      await StorageService.saveReport(sanitizedReport);
      setReport(sanitizedReport);
      setIsDirty(false);
      setErrors({});
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 2000);
      return sanitizedReport;
    } catch (e: any) {
      if (showErrorAlert) alert(e.message || "Failed to save report.");
      return null;
    } finally {
      setSaving(false);
    }
  };

  const handleSaveAndExit = async () => {
    const saved = await handleSave();
    if (saved) navigate('/');
  };

  const handleShare = async () => {
    if (!report) return;

    const tempReport: DailyReport = {
        ...report,
        salesRepName: sanitizeInput(report.salesRepName),
        items: report.items.map(i => ({
            ...i,
            productName: sanitizeInput(i.productName),
            sku: sanitizeInput(i.sku),
            notes: sanitizeInput(i.notes || '')
        }))
    };

    if (!tempReport.salesRepName) {
      alert("Please enter a Sales Rep Name");
      return;
    }

    if (!validate(tempReport)) return;

    let reportToShare = report;
    if (isDirty || isNew) {
      const saved = await handleSave(false); 
      if (saved) reportToShare = saved;
      else {
        reportToShare = tempReport;
        reportToShare.shareMessage = CalculationUtils.buildShareMessage(reportToShare);
      }
    } else {
       reportToShare = report;
    }
    navigate(`/share/${reportToShare.reportId}`, { state: { report: reportToShare } });
  };

  const handleSplit = () => {
    if (!report) return;
    if (!staff2Name.trim()) {
      alert("Please enter a name for the second staff member.");
      return;
    }

    setSaving(true);
    try {
      const reportA: DailyReport = {
        ...report,
        reportId: CalculationUtils.generateId(),
        items: splitItemsA,
        totals: CalculationUtils.computeTotals(splitItemsA, 0),
        salesRepName: report.salesRepName,
        createdAt: Date.now()
      };
      reportA.shareMessage = CalculationUtils.buildShareMessage(reportA);

      const reportB: DailyReport = {
        ...report,
        reportId: CalculationUtils.generateId(),
        items: splitItemsB,
        totals: CalculationUtils.computeTotals(splitItemsB, 0),
        salesRepName: staff2Name,
        createdAt: Date.now() + 1
      };
      reportB.shareMessage = CalculationUtils.buildShareMessage(reportB);

      StorageService.saveConfig({ salesRepName: report.salesRepName });
      setCreatedSplitReports({ a: reportA, b: reportB });
    } catch (e: any) {
      alert(`Failed to generate split reports: ${e.message}`);
    } finally {
      setSaving(false);
    }
  };

  const handleItemsCaptured = (newItems: SalesItem[], source: SourceType) => {
    if (!report) return;
    updateReport({
      items: [...report.items, ...newItems],
      sources: Array.from(new Set([...report.sources, source]))
    });
  };

  const handleRemoveAttachment = (index: number) => {
    if (!report) return;
    const newAttachments = [...report.attachments];
    newAttachments.splice(index, 1);
    updateReport({ attachments: newAttachments });
  };

  const handleAddAttachments = (urls: string[]) => {
    if (!report) return;
    const newAttachments = urls.map(url => ({ type: 'image' as const, url }));
    updateReport({ attachments: [...report.attachments, ...newAttachments] });
  };

