              <ShieldCheck size={24} />
            </div>
            <h1 className="text-2xl font-black text-gray-900 tracking-tight">Cloud Report</h1>
          </div>
          <button onClick={() => navigate('/')} className="p-2 text-gray-400 hover:text-gray-900 transition-colors">
            <ArrowLeft size={24} />
