import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertTriangle, RefreshCw } from 'lucide-react';

interface Props {
  children?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

/**
 * ErrorBoundary catches runtime errors in the component tree and displays a fallback UI.
 */
// Fix: Extending 'Component' directly from 'react' helps TypeScript correctly infer 'this.props' and 'this.state' 
// types from the provided generics, resolving the "Property 'props' does not exist" error.
export class ErrorBoundary extends Component<Props, State> {
  // Use property initialization for state
  public state: State = {
    hasError: false,
    error: null,
  };

  // Update state when an error occurs
  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  // Log error information
  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("ErrorBoundary caught an error", error, errorInfo);
  }

  public render() {
    // Standard access to state and props from the Component base class.
    const { hasError, error } = this.state;
    const { children } = this.props;

    if (hasError) {
      return (
        <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-gray-50 text-center font-sans">
          <div className="bg-red-100 p-4 rounded-full mb-4">
             <AlertTriangle className="text-red-600" size={32} />
          </div>
          <h1 className="text-2xl font-bold text-gray-900 mb-2">Something went wrong</h1>
          <p className="text-gray-500 mb-6 max-w-xs mx-auto">The application encountered an unexpected error.</p>

          <div className="w-full max-w-md bg-white p-4 rounded-xl border border-gray-200 shadow-sm mb-6 text-left overflow-hidden">
             <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Error Details</p>
             <pre className="text-xs text-red-600 font-mono whitespace-pre-wrap break-words">
               {error?.message || 'Unknown Error'}
             </pre>
          </div>

          <button 
            onClick={() => window.location.reload()}
            className="px-6 py-3 bg-brand-600 text-white rounded-xl font-bold shadow-lg shadow-brand-500/30 flex items-center gap-2 hover:bg-brand-700 transition-all active:scale-95"
          >
            <RefreshCw size={18} />
            Reload Application
          </button>
        </div>
      );
    }

    return children;
  }
}

import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { Plus, Search, ChevronRight, FileText, TrendingUp, History, LayoutDashboard, Loader2, Settings, Key, Sparkles, MapPinned, X, UserCircle, Calendar, Trash2 } from 'lucide-react';
import { DailyReport } from '../types';
import * as StorageService from '../services/storageService';
import * as AuthService from '../services/authService';
import * as GeminiService from '../services/geminiService';
import { formatCurrency } from '../utils/calculations';
import { MOCK_STORES, LOCAL_STORAGE_KEYS } from '../constants';
import AuthModal from '../components/AuthModal';
import SettingsModal from '../components/SettingsModal';

type ViewMode = 'home' | 'history';
type FilterRange = 'all' | 'day' | 'week' | 'month';

const Dashboard: React.FC = () => {
  const navigate = useNavigate();
  const [reports, setReports] = useState<DailyReport[]>([]);
  const [loading, setLoading] = useState(true);
  const [viewMode, setViewMode] = useState<ViewMode>('home');
  const [filterRange, setFilterRange] = useState<FilterRange>('all');
  const [hasKey, setHasKey] = useState(true);

  const [currentUser, setCurrentUser] = useState<any>(null);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeStore, setActiveStore] = useState<string>(localStorage.getItem(LOCAL_STORAGE_KEYS.LAST_STORE) || '');

  const initData = async (checkKey = true) => {
    setLoading(true);
    if (checkKey) {
      const keyOk = await GeminiService.ensureApiKey();
      setHasKey(keyOk);
    }
    const [user, data] = await Promise.all([
      AuthService.getCurrentUser(),
      StorageService.loadReports()
    ]);
    setCurrentUser(user);
    setReports(data);
    setLoading(false);
  };

  useEffect(() => {
    initData();
    const interval = setInterval(() => {
      setHasKey(GeminiService.hasValidKey());
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  const handleKeyActivation = async () => {
    const success = await GeminiService.requestKeySelection();
    if (success) {
      setHasKey(true);
      setTimeout(() => initData(true), 1500);
    }
  };

  const handleStoreChange = (store: string) => {
    setActiveStore(store);
    if (store) {
      localStorage.setItem(LOCAL_STORAGE_KEYS.LAST_STORE, store);
    } else {
      localStorage.removeItem(LOCAL_STORAGE_KEYS.LAST_STORE);
    }
  };

  const handleDeleteDay = async (date: string) => {
    const reportsToDelete = reports.filter(r => r.dateLocal === date);
    const ids = reportsToDelete.map(r => r.reportId);

    if (window.confirm(`Delete all ${ids.length} reports for ${date}? This cannot be undone.`)) {
      await StorageService.deleteReports(ids);
      setReports(prev => prev.filter(r => !ids.includes(r.reportId)));
    }
  };

  const filteredReports = useMemo(() => {
    let list = [...reports];

    if (searchTerm) {
      list = list.filter(r => 
        r.storeName.toLowerCase().includes(searchTerm.toLowerCase()) || 
        r.salesRepName.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    const now = new Date();
    if (filterRange === 'day') {
      const todayStr = now.toISOString().split('T')[0];
      list = list.filter(r => r.dateLocal === todayStr);
    } else if (filterRange === 'week') {
      const lastWeek = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
      list = list.filter(r => r.createdAt >= lastWeek.getTime());
    } else if (filterRange === 'month') {
      const lastMonth = new Date(now.getFullYear(), now.getMonth() - 1, now.getDate());
      list = list.filter(r => r.createdAt >= lastMonth.getTime());
    }

    return list.sort((a, b) => b.createdAt - a.createdAt);
  }, [reports, searchTerm, filterRange]);

  const groupedReports = useMemo(() => {
    const groups: Record<string, DailyReport[]> = {};
    filteredReports.forEach(report => {
      if (!groups[report.dateLocal]) groups[report.dateLocal] = [];
      groups[report.dateLocal].push(report);
    });
    return groups;
  }, [filteredReports]);

  const mostRecentReport = reports[0];
  const last7Days = reports.slice(0, 7).reverse();
  const maxVal = Math.max(...last7Days.map(r => r.totals.net), 1);

  return (
